{
  "name": "ScrollMotion AI",
  "description": "A high-end cinematic landing page builder that turns any video clip into a scroll-synchronized interactive experience using Gemini AI to craft the narrative.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ScrollSection {
  title: string;
  description: string;
  triggerTime: number; // 0 to 1 scale
}

export interface VideoState {
  url: string | null;
  duration: number;
  sections: ScrollSection[];
  isAnalyzing: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  const prompt = `Based on this video description: "${videoDescription}", generate 4 cinematic landing page sections. 
  Each section needs a punchy title and a short poetic description (max 15 words). 
  Return the response as a JSON array of objects.
  Distribute the 'triggerTime' equally from 0.1 to 0.9.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER }
            },
            required: ["title", "description", "triggerTime"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");
    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    // Fallback content if API fails
    return [
      { title: "The Beginning", description: "Every story starts with a single frame of light.", triggerTime: 0.1 },
      { title: "The Motion", description: "Movement defines the soul of the visual experience.", triggerTime: 0.4 },
      { title: "The Depth", description: "Explore the hidden layers beneath the surface.", triggerTime: 0.7 },
      { title: "The Finale", description: "Capturing eternity in a fleeting moment.", triggerTime: 0.9 },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current || !videoRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const containerHeight = containerRef.current.offsetHeight;
      const windowHeight = window.innerHeight;

      // Calculate progress based on how much of the sticky container has passed the top
      // rect.top goes from 0 to -(containerHeight - windowHeight)
      const totalScrollable = containerHeight - windowHeight;
      const currentScroll = -rect.top;

      let progress = Math.max(0, Math.min(1, currentScroll / totalScrollable));

      setScrollProgress(progress);

      // Update video time
      if (videoRef.current.duration) {
        videoRef.current.currentTime = videoRef.current.duration * progress;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div ref={containerRef} className="relative w-full h-[500vh] bg-black">
      {/* Sticky Video Background */}
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">
        <video
          ref={videoRef}
          src={videoUrl}
          playsInline
          muted
          preload="auto"
          className="w-full h-full object-cover brightness-50"
        />

        {/* Progress Bar */}
        <div className="absolute bottom-0 left-0 h-1 bg-blue-600 transition-all duration-75 z-50" 
             style={{ width: `${scrollProgress * 100}%` }} />

        {/* Text Overlays */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => {
            // Calculate opacity based on proximity to triggerTime
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const opacity = Math.max(0, 1 - distance * 10); // Very sharp fade
            const scale = 1 + (1 - opacity) * 0.1;
            const translateY = (1 - opacity) * 20;

            return (
              <div
                key={idx}
                className="absolute text-center px-6 max-w-2xl transition-all duration-300 ease-out"
                style={{ 
                  opacity, 
                  transform: `scale(${scale}) translateY(${translateY}px)`,
                  visibility: opacity > 0 ? 'visible' : 'hidden'
                }}
              >
                <h2 className="text-4xl md:text-7xl font-extrabold mb-4 tracking-tighter uppercase italic">
                  {section.title}
                </h2>
                <p className="text-lg md:text-2xl text-gray-300 font-light leading-relaxed">
                  {section.description}
                </p>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import React from 'react';
import { Upload, Video, Sparkles } from 'lucide-react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
  isAnalyzing: boolean;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, isAnalyzing }) => {
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && file.type.startsWith('video/')) {
      onFileSelect(file);
    } else {
      alert("Please upload a valid video file.");
    }
  };

  return (
    <div className="max-w-xl w-full mx-auto p-8 rounded-3xl border border-white/10 bg-white/5 backdrop-blur-xl">
      <div className="text-center mb-8">
        <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-blue-600/20 text-blue-400 mb-4">
          <Video size={32} />
        </div>
        <h2 className="text-3xl font-bold mb-2">Create Your Experience</h2>
        <p className="text-gray-400">Upload a video clip and let Gemini AI craft the narrative.</p>
      </div>

      <label className={`relative group cursor-pointer block p-12 border-2 border-dashed rounded-2xl transition-all ${
        isAnalyzing ? 'border-blue-500 bg-blue-500/5' : 'border-white/20 hover:border-white/40 hover:bg-white/5'
      }`}>
        <input 
          type="file" 
          accept="video/*" 
          onChange={handleFileChange} 
          className="hidden" 
          disabled={isAnalyzing}
        />

        <div className="flex flex-col items-center gap-4">
          {isAnalyzing ? (
            <>
              <div className="animate-spin text-blue-400">
                <Sparkles size={48} />
              </div>
              <p className="text-blue-400 font-medium animate-pulse">Gemini is analyzing the vibe...</p>
            </>
          ) : (
            <>
              <Upload className="text-gray-400 group-hover:text-white transition-colors" size={48} />
              <div className="text-center">
                <p className="text-lg font-medium">Click to upload or drag and drop</p>
                <p className="text-sm text-gray-500 mt-1">MP4, MOV, or WEBM (Max 50MB suggested)</p>
              </div>
            </>
          )}
        </div>
      </label>

      <div className="mt-8 grid grid-cols-2 gap-4 text-xs text-gray-500 uppercase tracking-widest font-semibold">
        <div className="flex items-center gap-2">
          <div className="w-1 h-1 rounded-full bg-blue-500" />
          Scroll-Synced Playback
        </div>
        <div className="flex items-center gap-2">
          <div className="w-1 h-1 rounded-full bg-purple-500" />
          AI Storytelling
        </div>
        <div className="flex items-center gap-2">
          <div className="w-1 h-1 rounded-full bg-green-500" />
          Cinematic Layout
        </div>
        <div className="flex items-center gap-2">
          <div className="w-1 h-1 rounded-full bg-yellow-500" />
          Adaptive Design
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState } from 'react';
