import { ScrollSection } from "../types";

export function generateStandaloneHTML(sections: ScrollSection[]): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cinematic Scroll Experience</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;800&display=swap" rel="stylesheet">
    <style>
        body {
            font-family: 'Inter', sans-serif;
            background-color: #000;
            color: #fff;
            margin: 0;
            overflow-x: hidden;
        }
        /* Hide scrollbar but allow scrolling */
        ::-webkit-scrollbar { width: 0px; background: transparent; }
    </style>
</head>
<body>
    <!-- 
      INSTRUCTIONS:
      1. Place your video file in the same folder as this HTML file.
      2. Rename your video to "video.mp4" or update the 'src' attribute in the <video> tag below.
    -->
    <div id="scroll-container" style="height: 500vh; position: relative; background: black;">
        <div style="position: sticky; top: 0; left: 0; width: 100%; height: 100vh; overflow: hidden;">
            <video
                id="main-video"
                src="video.mp4"
                playsinline
                muted
                preload="auto"
                style="width: 100%; height: 100%; object-fit: cover; filter: brightness(0.5);"
            ></video>

            <div id="progress-bar" style="position: absolute; bottom: 0; left: 0; height: 4px; background: #2563eb; width: 0%; transition: width 0.1s linear; z-index: 50;"></div>

            <div id="text-overlay-container" style="position: absolute; inset: 0; display: flex; items-center: center; justify-content: center; pointer-events: none;">
                <!-- Content will be injected here by JS -->
            </div>
        </div>
    </div>

    <footer style="height: 100vh; display: flex; align-items: center; justify-content: center; background: #000; border-top: 1px solid #111;">
        <h2 style="font-size: 5rem; font-weight: 800; letter-spacing: -0.05em;">FIN.</h2>
    </footer>

    <script>
        const sections = ${sectionsJSON};
        const video = document.getElementById('main-video');
        const container = document.getElementById('scroll-container');
        const progressBar = document.getElementById('progress-bar');
        const textContainer = document.getElementById('text-overlay-container');

        // Initial injection of sections
        sections.forEach((section, idx) => {
            const div = document.createElement('div');
            div.id = 'section-' + idx;
            div.className = 'absolute text-center px-6 max-w-2xl transition-all duration-300 ease-out';
            div.style.opacity = '0';
            div.style.visibility = 'hidden';
            div.innerHTML = \`
                <h2 style="font-size: 4rem; font-weight: 800; margin-bottom: 1rem; text-transform: uppercase; font-style: italic; letter-spacing: -0.05em;">\${section.title}</h2>
                <p style="font-size: 1.5rem; color: #d1d5db; font-weight: 300;">\${section.description}</p>
            \`;
            textContainer.appendChild(div);
        });

        function update() {
            const rect = container.getBoundingClientRect();
            const totalScrollable = container.offsetHeight - window.innerHeight;
            const currentScroll = -rect.top;
            let progress = Math.max(0, Math.min(1, currentScroll / totalScrollable));

            // Update video
            if (video.duration) {
                video.currentTime = video.duration * progress;
            }

            // Update progress bar
            progressBar.style.width = (progress * 100) + '%';

            // Update text overlays
            sections.forEach((section, idx) => {
                const el = document.getElementById('section-' + idx);
                const distance = Math.abs(progress - section.triggerTime);
                const opacity = Math.max(0, 1 - distance * 10);
                const scale = 1 + (1 - opacity) * 0.1;
                const translateY = (1 - opacity) * 20;

                el.style.opacity = opacity;
                el.style.transform = \`scale(\${scale}) translateY(\${translateY}px)\`;
                el.style.visibility = opacity > 0 ? 'visible' : 'hidden';
            });
        }

        window.addEventListener('scroll', update, { passive: true });
        // Handle case where video might not be found initially
        video.onerror = () => {
            console.error("Video file not found. Please ensure 'video.mp4' exists in the root directory.");
        };
    </script>
</body>
</html>`;
}

