export interface ScrollSection {
  title: string;
  description: string;
  triggerTime: number; // 0 to 1 scale
  alignment: 'left' | 'right' | 'center';
  vibe: 'cinematic' | 'minimal' | 'energetic';
}

export interface VideoState {
  url: string | null;
  duration: number;
  sections: ScrollSection[];
  isAnalyzing: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  const prompt = `Based on this video context: "${videoDescription}", generate 5 professional cinematic landing page sections. 
  Each section needs:
  1. A punchy, high-end title.
  2. A sophisticated description (max 20 words).
  3. A 'triggerTime' between 0.05 and 0.95.
  4. An 'alignment' ('left', 'right', or 'center') to create visual rhythm.
  5. A 'vibe' ('cinematic', 'minimal', or 'energetic').

  Return the response as a JSON array of objects. Ensure sections are sorted by triggerTime.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");
    return JSON.parse(text);
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return [
      { title: "Origins", description: "Where the narrative finds its first breath of light.", triggerTime: 0.1, alignment: 'left', vibe: 'cinematic' },
      { title: "Fluidity", description: "Motion becomes an extension of the soul's intent.", triggerTime: 0.3, alignment: 'right', vibe: 'energetic' },
      { title: "The Void", description: "Embracing the silence between the frames.", triggerTime: 0.55, alignment: 'center', vibe: 'minimal' },
      { title: "Convergence", description: "Every element aligns to form a perfect vision.", triggerTime: 0.75, alignment: 'left', vibe: 'cinematic' },
      { title: "Everlasting", description: "The final capture of a moment that never ends.", triggerTime: 0.9, alignment: 'right', vibe: 'energetic' },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  // Smooth Scrubbing Logic (LERP)
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    // Smoothing factor: higher = more delay/smoothness
    const lerpFactor = 0.08;
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    if (videoRef.current && videoRef.current.duration) {
      videoRef.current.currentTime = videoRef.current.duration * currentProgress.current;
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      targetProgress.current = progress;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getAlignmentClass = (alignment: string) => {
    switch (alignment) {
      case 'left': return 'justify-start items-center pl-10 md:pl-24 text-left';
      case 'right': return 'justify-end items-center pr-10 md:pr-24 text-right';
      default: return 'justify-center items-center text-center';
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-[700vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">
        {/* Dynamic Video Layers */}
        <div className="absolute inset-0 z-0">
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `brightness(${0.4 + (1 - scrollProgress) * 0.1}) contrast(1.1)`,
              transform: `scale(${1 + scrollProgress * 0.05})`
            }}
          />
        </div>

        {/* Cinematic Overlays */}
        <div className="absolute inset-0 pointer-events-none bg-gradient-to-t from-black via-transparent to-black opacity-60 z-10" />
        <div className="absolute inset-0 pointer-events-none z-10" 
             style={{ 
               background: `radial-gradient(circle, transparent 40%, rgba(0,0,0,${0.2 + scrollProgress * 0.5}) 100%)` 
             }} 
        />

        {/* Professional Film Grain Layer */}
        <div className="absolute inset-0 opacity-[0.03] pointer-events-none z-20" 
             style={{ backgroundImage: 'url("https://grainy-gradients.vercel.app/noise.svg")' }} />

        {/* Text Engine */}
        <div className="absolute inset-0 flex z-30 pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            // Sharp reveal curve
            const opacity = Math.max(0, 1 - distance * 15); 
            const isVisible = opacity > 0.01;

            // Subtle motion per section
            const yOffset = (scrollProgress - section.triggerTime) * 150;
            const blurAmount = distance * 20;

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex p-8 transition-opacity duration-300 ${getAlignmentClass(section.alignment)}`}
                style={{ 
                  opacity,
                  visibility: isVisible ? 'visible' : 'hidden',
                  transform: `translateY(${yOffset}px)`,
                  filter: `blur(${blurAmount}px)`
                }}
              >
                <div className="max-w-2xl">
                  <div className="overflow-hidden mb-2">
                    <h2 className={`text-5xl md:text-8xl font-black tracking-tighter uppercase italic leading-[0.9] transition-transform duration-700 delay-75 ${isVisible ? 'translate-y-0' : 'translate-y-full'}`}>
                      {section.title}
                    </h2>
                  </div>
                  <div className="h-1 w-24 bg-blue-600 mb-6 origin-left scale-x-100 transition-transform duration-1000" style={{ transform: isVisible ? 'scaleX(1)' : 'scaleX(0)' }} />
                  <p className={`text-xl md:text-3xl text-gray-300 font-light leading-snug transition-all duration-1000 delay-300 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-8'}`}>
                    {section.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Minimal Scroll Progress Side Indicator */}
        <div className="absolute right-6 top-1/2 -translate-y-1/2 flex flex-col gap-4 z-40">
          {sections.map((s, i) => (
            <div 
              key={i} 
              className={`w-1 transition-all duration-500 rounded-full ${Math.abs(scrollProgress - s.triggerTime) < 0.05 ? 'h-8 bg-blue-500' : 'h-2 bg-white/20'}`}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import { ScrollSection } from "../types";

export function generateStandaloneHTML(sections: ScrollSection[]): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cinematic Scroll Experience</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;800&display=swap" rel="stylesheet">
    <style>
        body { font-family: 'Inter', sans-serif; background-color: #000; color: #fff; margin: 0; overflow-x: hidden; }
        ::-webkit-scrollbar { width: 0px; }
        .clip-text { -webkit-background-clip: text; background-clip: text; color: transparent; background-image: linear-gradient(to bottom, #fff, #555); }
    </style>
</head>
<body>
    <div id="scroll-container" style="height: 700vh; position: relative;">
        <div style="position: sticky; top: 0; left: 0; width: 100%; height: 100vh; overflow: hidden;">
            <video
                id="main-video"
                src="video.mp4"
                playsinline muted preload="auto"
                style="width: 100%; height: 100%; object-fit: cover;"
            ></video>
            <div style="position: absolute; inset: 0; background: linear-gradient(to top, rgba(0,0,0,0.8), transparent, rgba(0,0,0,0.8)); opacity: 0.6; pointer-events: none;"></div>
            <div id="text-overlay-container" style="position: absolute; inset: 0; z-index: 50; pointer-events: none;"></div>
        </div>
    </div>

    <script>
        const sections = ${sectionsJSON};
        const video = document.getElementById('main-video');
        const container = document.getElementById('scroll-container');
        const textContainer = document.getElementById('text-overlay-container');

        let targetProgress = 0;
        let currentProgress = 0;

        sections.forEach((section, idx) => {
            const wrapper = document.createElement('div');
            wrapper.id = 'section-' + idx;
            wrapper.style.position = 'absolute';
            wrapper.style.inset = '0';
            wrapper.style.display = 'flex';
            wrapper.style.padding = '2rem';
            wrapper.style.opacity = '0';
            wrapper.style.visibility = 'hidden';
            wrapper.style.transition = 'opacity 0.3s ease';

            if(section.alignment === 'left') {
                wrapper.style.justifyContent = 'flex-start';
                wrapper.style.alignItems = 'center';
                wrapper.style.paddingLeft = '10%';
                wrapper.style.textAlign = 'left';
            } else if(section.alignment === 'right') {
                wrapper.style.justifyContent = 'flex-end';
                wrapper.style.alignItems = 'center';
                wrapper.style.paddingRight = '10%';
                wrapper.style.textAlign = 'right';
            } else {
                wrapper.style.justifyContent = 'center';
                wrapper.style.alignItems = 'center';
                wrapper.style.textAlign = 'center';
            }

            wrapper.innerHTML = \`
                <div style="max-width: 40rem;">
                    <h2 style="font-size: clamp(3rem, 10vw, 6rem); font-weight: 900; line-height: 0.9; margin-bottom: 1.5rem; text-transform: uppercase; font-style: italic;">\${section.title}</h2>
                    <p style="font-size: 1.5rem; color: #ccc; font-weight: 300;">\${section.description}</p>
                </div>
            \`;
            textContainer.appendChild(wrapper);
        });

        function animate() {
            currentProgress += (targetProgress - currentProgress) * 0.08;

            if (video.duration) {
                video.currentTime = video.duration * currentProgress;
                video.style.transform = \`scale(\${1 + currentProgress * 0.05})\`;
                video.style.filter = \`brightness(\${0.4 + (1 - currentProgress) * 0.1})\`;
            }

            sections.forEach((section, idx) => {
                const el = document.getElementById('section-' + idx);
                const distance = Math.abs(currentProgress - section.triggerTime);
                const opacity = Math.max(0, 1 - distance * 15);
                const yOffset = (currentProgress - section.triggerTime) * 150;

                el.style.opacity = opacity;
                el.style.transform = \`translateY(\${yOffset}px)\`;
                el.style.filter = \`blur(\${distance * 20}px)\`;
                el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
            });

            requestAnimationFrame(animate);
        }

        window.addEventListener('scroll', () => {
            const rect = container.getBoundingClientRect();
            const total = container.offsetHeight - window.innerHeight;
            targetProgress = Math.max(0, Math.min(1, -rect.top / total));
        }, { passive: true });

        animate();
    </script>
</body>
</html>`;
}

import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  const prompt = `Act as a world-class creative director for a high-end digital agency. 
  Analyze this video concept: "${videoDescription}".

  Generate 5 distinct landing page sections that transform this video into a premium scroll-synchronized narrative.

  Requirements for each section:
  1. Title: 1-3 words, evocative and powerful (e.g., "UNSEEN DEPTHS", "KINETIC SOUL").
  2. Description: 15-25 words of high-end marketing copy that matches the visual vibe.
  3. triggerTime: A float between 0.05 and 0.95, perfectly spaced for narrative flow.
  4. alignment: Must vary between 'left', 'right', and 'center' to prevent repetitive layouts.
  5. vibe: Choose between:
     - 'cinematic': For sweeping, emotional moments (slow reveals).
     - 'energetic': For fast-paced, high-motion segments (sharp movements).
     - 'minimal': For quiet, atmospheric breathers (subtle presence).

  Return strictly as a JSON array of objects.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return [
      { title: "THE AWAKENING", description: "In the quiet before the motion, every frame holds a promise of what is to come.", triggerTime: 0.1, alignment: 'left', vibe: 'cinematic' },
      { title: "VELOCITY", description: "Breaking the boundaries of still life. Experience the raw power of unbridled kinetic energy.", triggerTime: 0.35, alignment: 'right', vibe: 'energetic' },
      { title: "SILENCE", description: "A pause in the chaos. Finding clarity in the minimalist geometry of the moving image.", triggerTime: 0.55, alignment: 'center', vibe: 'minimal' },
      { title: "THE NEXUS", description: "Where color and light converge to create something entirely new and unexpected.", triggerTime: 0.75, alignment: 'left', vibe: 'cinematic' },
      { title: "ETERNITY", description: "Finality is just a perspective. The loop continues in the memory of the observer.", triggerTime: 0.92, alignment: 'right', vibe: 'energetic' },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const lerpFactor = 0.08;
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    if (videoRef.current && videoRef.current.duration) {
      // Direct assignment for low latency scrubbing
      videoRef.current.currentTime = videoRef.current.duration * currentProgress.current;
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      targetProgress.current = progress;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getAlignmentStyles = (alignment: string) => {
    switch (alignment) {
      case 'left': return 'justify-start pl-8 md:pl-32 text-left items-center';
      case 'right': return 'justify-end pr-8 md:pr-32 text-right items-center';
      default: return 'justify-center text-center items-center';
    }
  };

  const getVibeStyles = (vibe: string, isVisible: boolean, distance: number) => {
    const base = "transition-all duration-1000 ease-out";
    switch (vibe) {
      case 'energetic':
        return {
          title: `${base} ${isVisible ? 'tracking-normal' : 'tracking-[0.5em]'} font-black`,
          transform: `scale(${1 + (1 - Math.exp(-distance * 5)) * 0.2}) rotate(${(currentProgress.current - distance) * 2}deg)`
        };
      case 'minimal':
        return {
          title: `${base} ${isVisible ? 'opacity-100' : 'opacity-0'} font-light`,
          transform: `translateY(${(currentProgress.current - distance) * 20}px)`
        };
      default: // cinematic
        return {
          title: `${base} ${isVisible ? 'scale-100' : 'scale-90'} italic font-bold`,
          transform: `translateY(${(currentProgress.current - distance) * 80}px)`
        };
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-[800vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">
        {/* Cinematic Video Layer */}
        <div className="absolute inset-0">
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `brightness(${0.5 + (1 - scrollProgress) * 0.1}) saturate(1.1) contrast(1.1)`,
              transform: `scale(${1 + scrollProgress * 0.08})`
            }}
          />
        </div>

        {/* Professional Post-Processing Overlays */}
        <div className="absolute inset-0 pointer-events-none z-10">
          {/* Edge Vignette */}
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.8)_100%)] opacity-70" />

          {/* Subtle Grain */}
          <div className="absolute inset-0 opacity-[0.04]" 
               style={{ backgroundImage: 'url("https://grainy-gradients.vercel.app/noise.svg")' }} />

          {/* Top/Bottom Letterbox Gradient */}
          <div className="absolute inset-0 bg-gradient-to-b from-black via-transparent to-black opacity-40" />
        </div>

        {/* The Narrative Text Engine */}
        <div className="absolute inset-0 flex z-30 pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const opacity = Math.max(0, 1 - distance * 12); 
            const isVisible = opacity > 0.01;
            const vibeStyles = getVibeStyles(section.vibe, isVisible, distance);

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex p-8 transition-opacity duration-500 ${getAlignmentStyles(section.alignment)}`}
                style={{ 
                  opacity,
                  visibility: isVisible ? 'visible' : 'hidden',
                  filter: `blur(${distance * 15}px)`,
                  transform: vibeStyles.transform
                }}
              >
                <div className="max-w-3xl">
                  {/* Title with Mask Reveal */}
                  <div className="overflow-hidden mb-4">
                    <h2 className={`text-6xl md:text-9xl leading-[0.85] uppercase tracking-tighter ${vibeStyles.title} ${isVisible ? 'translate-y-0' : 'translate-y-full'}`}>
                      {section.title}
                    </h2>
                  </div>

                  {/* Decorative Accent */}
                  <div className="flex items-center gap-4 mb-6">
                    <div className="h-[2px] w-12 bg-blue-600 transition-all duration-1000" style={{ transform: isVisible ? 'scaleX(1)' : 'scaleX(0)', transformOrigin: 'left' }} />
                    <span className="text-[10px] font-bold tracking-[0.5em] text-blue-500 uppercase opacity-70">
                      Chapter 0{idx + 1}
                    </span>
                  </div>

                  {/* Description with fade-in */}
                  <p className={`text-xl md:text-3xl text-gray-200/90 font-light leading-relaxed max-w-xl transition-all duration-1000 delay-300 ${isVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                    {section.description}
                  </p>
                </div>
              </div>
            );
          })}
        </div>

        {/* Modern Vertical Progress Indicator */}
        <div className="absolute left-8 top-1/2 -translate-y-1/2 hidden md:flex flex-col items-center gap-6 z-40">
           <div className="h-40 w-[1px] bg-white/10 relative">
              <div className="absolute top-0 left-0 w-full bg-blue-500 transition-all duration-75" style={{ height: `${scrollProgress * 100}%` }} />
           </div>
           {sections.map((s, i) => (
             <div 
               key={i} 
               className={`text-[8px] font-black tracking-widest transition-all duration-300 ${Math.abs(scrollProgress - s.triggerTime) < 0.06 ? 'text-white scale-125' : 'text-white/20'}`}
             >
               0{i+1}
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

