import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastScrollTime = useRef(Date.now());
  const requestRef = useRef<number>(null);

  const animate = () => {
    const now = Date.now();
    const dt = now - lastScrollTime.current;
    lastScrollTime.current = now;

    // Advanced Spring-Damping LERP
    // Higher factor = more responsive, Lower = smoother/heavier
    const lerpFactor = 0.075;
    const prevProgress = currentProgress.current;
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    // Calculate instantaneous velocity for motion effects
    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      // Seek Optimization: Only update if the change is meaningful
      // to avoid overwhelming the hardware decoder
      const targetTime = video.duration * currentProgress.current;
      if (Math.abs(video.currentTime - targetTime) > 0.01) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      targetProgress.current = progress;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getCameraTransform = () => {
    const currentSection = sections.find(s => Math.abs(scrollProgress - s.triggerTime) < 0.1) || sections[0];
    const vibe = currentSection?.vibe || 'cinematic';

    // Base scale with a subtle "breathing" effect
    let scale = 1.05 + scrollProgress * 0.05;
    let rotateY = (scrollProgress - 0.5) * 8;
    let skewX = velocity * 0.5; // Skew based on scroll speed

    if (vibe === 'energetic') {
      scale += velocity * 0.01;
    }

    return `perspective(1200px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg)`;
  };

  const getAlignmentStyles = (alignment: string) => {
    switch (alignment) {
      case 'left': return 'justify-start pl-12 md:pl-32 text-left items-center';
      case 'right': return 'justify-end pr-12 md:pr-32 text-right items-center';
      default: return 'justify-center text-center items-center';
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-[1200vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">

        {/* Optimized Video Container */}
        <div 
          className="absolute inset-0 z-0 bg-black will-change-transform"
          style={{ transform: getCameraTransform() }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `contrast(1.1) brightness(${0.4 + (1 - scrollProgress) * 0.1}) blur(${velocity * 0.2}px)`,
              transition: 'filter 0.1s linear'
            }}
          />
        </div>

        {/* Global Cinematic Grading */}
        <div className="absolute inset-0 pointer-events-none z-10">
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_30%,rgba(0,0,0,0.85)_110%)] opacity-90" />
          <div className="absolute inset-0 mix-blend-overlay opacity-20 bg-gradient-to-b from-blue-500/10 via-transparent to-purple-500/10" />
          <div className="absolute inset-0 opacity-[0.05] pointer-events-none" 
               style={{ backgroundImage: 'url("https://grainy-gradients.vercel.app/noise.svg")' }} />
        </div>

        {/* Narrative Layers */}
        <div className="absolute inset-0 flex z-30 pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const isActive = distance < 0.06;
            const opacity = Math.max(0, 1 - distance * 18); // Sharper falloff

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex p-8 ${getAlignmentStyles(section.alignment)} will-change-[opacity,transform]`}
                style={{ 
                  opacity,
                  visibility: opacity > 0.01 ? 'visible' : 'hidden',
                  transform: `translateY(${(scrollProgress - section.triggerTime) * 120}px)`,
                }}
              >
                <div className="relative max-w-4xl">
                  {/* Dynamic Heading with velocity-based skew */}
                  <div className="overflow-hidden mb-6">
                     <h2 
                       className={`text-7xl md:text-[11rem] font-black leading-[0.8] uppercase italic tracking-tighter transition-all duration-700 ease-out ${isActive ? 'translate-y-0 scale-100' : 'translate-y-full scale-95'}`}
                       style={{ transform: `skewY(${velocity * (section.alignment === 'right' ? -1 : 1)}deg)` }}
                     >
                       {section.title}
                     </h2>
                  </div>

                  {/* Aesthetic Accents */}
                  <div className={`flex items-center gap-4 mb-8 transition-all duration-1000 ${isActive ? 'opacity-100' : 'opacity-0 translate-x-[-20px]'}`}>
                    <div className="h-[3px] w-16 bg-blue-600 rounded-full" />
                    <span className="text-[10px] font-bold tracking-[0.6em] text-white/40 uppercase">
                      Segment_0{idx + 1}
                    </span>
                  </div>

                  {/* Content Body with glassmorphism to mask background jitter */}
                  <div className={`backdrop-blur-md bg-white/5 p-8 rounded-2xl border border-white/10 transition-all duration-1000 delay-100 ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
                    <p className="text-xl md:text-2xl text-gray-200 font-light leading-relaxed max-w-xl">
                      {section.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Floating Side Index */}
        <div className="absolute right-10 top-1/2 -translate-y-1/2 flex flex-col gap-8 z-40">
           {sections.map((_, i) => {
             const dist = Math.abs(scrollProgress - sections[i].triggerTime);
             const active = dist < 0.06;
             return (
               <div key={i} className="flex items-center gap-4 group">
                 <div className={`h-[1px] transition-all duration-500 ${active ? 'w-12 bg-blue-500' : 'w-4 bg-white/20'}`} />
                 <span className={`text-[9px] font-mono transition-colors duration-500 ${active ? 'text-blue-500' : 'text-white/20'}`}>
                   0{i+1}
                 </span>
               </div>
             );
           })}
        </div>

        {/* Global Progress */}
        <div className="absolute bottom-0 left-0 w-full h-[4px] bg-white/5 z-50">
           <div 
             className="h-full bg-blue-600 transition-all duration-75 ease-linear shadow-[0_0_20px_rgba(37,99,235,0.4)]" 
             style={{ width: `${scrollProgress * 100}%` }} 
           />
        </div>
      </div>
    </div>
  );
};

