  const lastScrollTime = useRef(Date.now());
  const requestRef = useRef<number>(null);

  const animate = () => {
    const now = Date.now();
    const prevProgress = currentProgress.current;

    // Smooth easing factor - safe for external integration
    const lerpFactor = 0.07; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    // Instantaneous velocity for motion effects
    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      // Precision check to prevent constant bus traffic to GPU
      if (Math.abs(video.currentTime - targetTime) > 0.01) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
