import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  showText?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, showText = true }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;

    // Smooth easing factor for professional "scrubbing" feel
    const lerpFactor = 0.08; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    // Velocity calculation for dynamic effects (motion blur/skew)
    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      // Precision scrubbing: Only update if change is significant to avoid jitter
      if (Math.abs(video.currentTime - targetTime) > 0.001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      if (rect.top <= window.innerHeight && rect.bottom >= 0) {
        const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
        const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
        targetProgress.current = progress;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getBackgroundTransform = () => {
    const scale = 1.01 + scrollProgress * 0.03; // Extremely subtle scale to maintain high pixel density
    const rotateY = (scrollProgress - 0.5) * 3; // Minimal tilt
    const skewX = velocity * 0.05; 
    return `perspective(2500px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg) translateZ(0)`;
  };

  return (
    <div 
      ref={containerRef} 
      className="scroll-motion-root relative w-full h-[1000vh] bg-black overflow-clip"
      id="scroll-motion-engine"
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">

        {/* VIDEO CONTENT: Optimized for High Quality */}
        <div 
          className="absolute inset-0 z-0 will-change-transform pointer-events-none"
          style={{ 
            transform: getBackgroundTransform(),
            backfaceVisibility: 'hidden',
            WebkitBackfaceVisibility: 'hidden',
            // Forces the browser to keep the video in high-quality GPU memory
            transformStyle: 'preserve-3d'
          }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              // Using image-rendering for sub-pixel accuracy
              imageRendering: 'high-quality',
              // Very light filter to maintain sharp detail
              filter: `contrast(1.02) brightness(${0.6 + (1 - scrollProgress) * 0.1}) blur(${velocity * 0.02}px)`,
            }}
          />
          {/* Subtle Ambient Mask */}
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_60%,rgba(0,0,0,0.6)_140%)] z-10" />
        </div>

        {/* OVERLAY UI (Optional Text Narrative) */}
        {showText && (
          <div className="absolute inset-0 z-20 flex pointer-events-none">
            {sections.map((section, idx) => {
              const distance = Math.abs(scrollProgress - section.triggerTime);
              const isActive = distance < 0.06;
              const opacity = Math.max(0, 1 - distance * 18);

              return (
                <div
                  key={idx}
                  className={`absolute inset-0 flex p-8 ${
                    section.alignment === 'left' ? 'justify-start pl-12 md:pl-32' : 
                    section.alignment === 'right' ? 'justify-end pr-12 md:pr-32' : 
                    'justify-center'
                  } items-center`}
                  style={{ 
                    opacity,
                    visibility: opacity > 0.01 ? 'visible' : 'hidden',
                    transform: `translateY(${(scrollProgress - section.triggerTime) * 120}px)`,
                  }}
                >
                  <div className="max-w-4xl">
                    <div className="overflow-hidden mb-4">
                       <h2 className={`text-6xl md:text-[8rem] font-black uppercase italic tracking-tighter transition-transform duration-1000 ease-out ${isActive ? 'translate-y-0' : 'translate-y-full'}`}>
                         {section.title}
                       </h2>
                    </div>
                    <div className={`transition-all duration-1000 delay-200 border-l-4 border-blue-600 pl-6 ${isActive ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`}>
                      <p className="text-xl md:text-2xl text-gray-200/90 font-light leading-relaxed max-w-xl">
                        {section.description}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Telemetry Display */}
        <div className="absolute bottom-10 left-10 z-30 font-mono text-[10px] text-white/30 uppercase tracking-[0.4em]">
          DATA_FEED // {(scrollProgress * 100).toFixed(1)}%
        </div>
      </div>
    </div>
  );
};

