<body>

<div id="sm-root-container">
    <div id="sm-viewport" style="position: sticky; top: 0; width: 100%; height: 100vh; overflow: hidden;">

        <div id="sm-video-layer" style="position: absolute; inset: 0; z-index: 0; will-change: transform; pointer-events: none; backface-visibility: hidden;">
            <video id="sm-video-element" playsinline muted style="width: 100%; height: 100%; object-fit: cover;"></video>
            <div style="position: absolute; inset: 0; background: radial-gradient(circle, transparent 40%, rgba(0,0,0,0.8) 120%); pointer-events: none;"></div>
        </div>

        <div id="sm-ui-layer" style="position: absolute; inset: 0; z-index: 10; pointer-events: none;"></div>
        <div id="sm-progress-bar" style="position: absolute; bottom: 0; left: 0; height: 3px; background: #4f46e5; width: 0%; z-index: 20;"></div>

        <div style="position: absolute; bottom: 30px; left: 30px; z-index: 30; font-family: monospace; font-size: 10px; color: rgba(79,70,229,0.5); letter-spacing: 0.4em;">
          AEON // INFINITY
        </div>
    </div>
</div>

<script>
(function() {
    const CONFIG = {
        videoPath: "REPLACE_WITH_YOUR_VIDEO_URL.mp4", 
        showNarrative: true,
        smoothness: 0.08,
        tiltEffect: 3,
        motionBlur: 0.03,
        textDuration: 0.07
    };

    const sections = ${sectionsJSON};
    const video = document.getElementById('sm-video-element');
    const vLayer = document.getElementById('sm-video-layer');
    const ui = document.getElementById('sm-ui-layer');
    const pBar = document.getElementById('sm-progress-bar');
    const root = document.getElementById('sm-root-container');

    video.src = CONFIG.videoPath;
    let target = 0, current = 0, velocity = 0;

    if (CONFIG.showNarrative) {
        sections.forEach((s, i) => {
            const wrap = document.createElement('div');
            wrap.id = 'sm-sec-' + i;
            wrap.style.cssText = 'position:absolute; inset:0; display:flex; padding:8%; opacity:0; visibility:hidden; transition:opacity 0.4s;';
            const alignMap = {
                left: 'justify-content:flex-start; align-items:center; text-align:left;',
                right: 'justify-content:flex-end; align-items:center; text-align:right;',
                center: 'justify-content:center; align-items:center; text-align:center;'
            };
            wrap.style.cssText += alignMap[s.alignment] || alignMap.center;
            wrap.innerHTML = \`
                <div style="max-width: 50rem;">
                    <h2 id="sm-t-\${i}" class="sm-narrative-title" style="font-size: clamp(3rem, 10vw, 8rem); transition: transform 0.8s cubic-bezier(.23,1,.32,1); transform: translateY(100%);">\${s.title}</h2>
                    <div id="sm-b-\${i}" style="border-left: 4px solid #4f46e5; padding-left: 2rem; margin-top: 2rem; transition: all 1s 0.2s; opacity: 0; transform: translateX(-20px);">
                      <p class="sm-narrative-body" style="font-size: clamp(1.2rem, 2.5vw, 2rem); italic: italic;">\${s.description}</p>
                    </div>
                </div>
            \`;
            ui.appendChild(wrap);
        });
    }

    function update() {
        const prev = current;
        current += (target - current) * CONFIG.smoothness;
        velocity = Math.abs(current - prev) * 100;

        if (video.duration && !video.seeking) {
            video.currentTime = video.duration * current;
            const scale = 1.01 + current * 0.03;
            const rotY = (current - 0.5) * CONFIG.tiltEffect;
            const skew = velocity * 0.05;
            vLayer.style.transform = \`perspective(2500px) rotateY(\${rotY}deg) scale(\${scale}) skewX(\${skew}deg) translateZ(0)\`;
            video.style.filter = \`brightness(\${0.6 + (1-current)*0.1}) contrast(1.02) blur(\${velocity * CONFIG.motionBlur}px)\`;
        }
        pBar.style.width = (current * 100) + '%';

        if (CONFIG.showNarrative) {
            sections.forEach((s, i) => {
                const el = document.getElementById('sm-sec-' + i);
                const t = document.getElementById('sm-t-' + i);
                const b = document.getElementById('sm-b-' + i);
                const dist = Math.abs(current - s.triggerTime);
                const isActive = dist < CONFIG.textDuration;
                const opacity = Math.max(0, 1 - dist * (1/CONFIG.textDuration));

                el.style.opacity = opacity;
                el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                el.style.transform = \`translateY(\${(current - s.triggerTime) * 120}px)\`;

                if (isActive) {
                    t.style.transform = 'translateY(0)';
                    b.style.opacity = '1';
                    b.style.transform = 'translateX(0)';
                } else {
                    t.style.transform = 'translateY(100%)';
                    b.style.opacity = '0';
                    b.style.transform = 'translateX(-20px)';
                }
            });
        }
        requestAnimationFrame(update);
    }

    window.addEventListener('scroll', () => {
        const r = root.getBoundingClientRect();
        if (r.top <= window.innerHeight && r.bottom >= 0) {
            target = Math.max(0, Math.min(1, -r.top / (root.offsetHeight - window.innerHeight)));
        }
    }, { passive: true });
    update();
})();
</script>
</body>
</html>`;
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  showText?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, showText = true }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;
    const lerpFactor = 0.08; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      if (Math.abs(video.currentTime - targetTime) > 0.001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      if (rect.top <= window.innerHeight && rect.bottom >= 0) {
        const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
        const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
        targetProgress.current = progress;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getBackgroundTransform = () => {
    const scale = 1.01 + scrollProgress * 0.03;
    const rotateY = (scrollProgress - 0.5) * 3;
    const skewX = velocity * 0.05; 
    return `perspective(2500px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg) translateZ(0)`;
  };

  return (
    <div 
      ref={containerRef} 
      className="scroll-motion-root relative w-full h-[1000vh] bg-black overflow-clip"
      id="aeon-engine"
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">

        <div 
          className="absolute inset-0 z-0 will-change-transform pointer-events-none"
          style={{ 
            transform: getBackgroundTransform(),
            backfaceVisibility: 'hidden',
            WebkitBackfaceVisibility: 'hidden',
            transformStyle: 'preserve-3d'
          }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              // Fix: Changed 'high-quality' to 'auto' as 'high-quality' is not a valid CSS image-rendering value in TypeScript
              imageRendering: 'auto',
              filter: `contrast(1.02) brightness(${0.6 + (1 - scrollProgress) * 0.1}) blur(${velocity * 0.02}px)`,
            }}
          />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_60%,rgba(0,0,0,0.6)_140%)] z-10" />
        </div>

        {showText && (
          <div className="absolute inset-0 z-20 flex pointer-events-none">
            {sections.map((section, idx) => {
              const distance = Math.abs(scrollProgress - section.triggerTime);
              const isActive = distance < 0.06;
              const opacity = Math.max(0, 1 - distance * 18);

              return (
                <div
                  key={idx}
                  className={`absolute inset-0 flex p-8 ${
                    section.alignment === 'left' ? 'justify-start pl-12 md:pl-32' : 
                    section.alignment === 'right' ? 'justify-end pr-12 md:pr-32' : 
                    'justify-center'
                  } items-center`}
                  style={{ 
                    opacity,
                    visibility: opacity > 0.01 ? 'visible' : 'hidden',
                    transform: `translateY(${(scrollProgress - section.triggerTime) * 120}px)`,
                  }}
                >
                  <div className="max-w-4xl">
                    <div className="overflow-hidden mb-4">
                       <h2 className={`text-6xl md:text-[8rem] font-black uppercase italic tracking-tighter transition-transform duration-1000 ease-out ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/50'}`}>
                         {section.title}
                       </h2>
                    </div>
                    <div className={`transition-all duration-1000 delay-200 border-l-4 border-indigo-600 pl-8 ${isActive ? 'opacity-100 translate-x-0' : 'opacity-0 -translate-x-10'}`}>
                      <p className="text-xl md:text-3xl text-gray-200/90 font-light leading-relaxed max-w-xl italic tracking-tight">
                        {section.description}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* AEON Branded Telemetry */}
        <div className="absolute bottom-10 left-10 z-30 font-mono text-[9px] text-indigo-400/50 uppercase tracking-[0.5em] flex flex-col gap-1">
          <span>AEON_FLOW // INFINITY_SYNC</span>
          <span className="text-white/20">PROGRESS :: {(scrollProgress * 100).toFixed(2)}%</span>
        </div>
      </div>
    </div>
  );
};

