import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';
import { AlertTriangle, WifiOff, RefreshCcw } from 'lucide-react';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  showText?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, showText = true }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);
  const [loadError, setLoadError] = useState(false);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;
    const lerpFactor = 0.08; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      if (Math.abs(video.currentTime - targetTime) > 0.001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      if (rect.top <= window.innerHeight && rect.bottom >= 0) {
        const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
        const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
        targetProgress.current = progress;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getBackgroundTransform = () => {
    const scale = 1 + scrollProgress * 0.06;
    const rotateY = (scrollProgress - 0.5) * 1.5;
    const skewX = velocity * 0.01; 
    return `perspective(2500px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg) translateZ(0)`;
  };

  return (
    <div 
      ref={containerRef} 
      className="scroll-motion-root relative w-full h-[1000vh] bg-black overflow-clip"
      id="aeon-engine"
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">

        {/* Dynamic Letterboxing */}
        <div className="absolute top-0 left-0 w-full z-50 bg-black transition-all duration-700 pointer-events-none" style={{ height: `${8 + velocity * 0.1}%` }} />
        <div className="absolute bottom-0 left-0 w-full z-50 bg-black transition-all duration-700 pointer-events-none" style={{ height: `${8 + velocity * 0.1}%` }} />

        <div 
          className="absolute inset-0 z-0 will-change-transform pointer-events-none"
          style={{ 
            transform: getBackgroundTransform(),
            backfaceVisibility: 'hidden',
            WebkitBackfaceVisibility: 'hidden',
            transformStyle: 'preserve-3d'
          }}
        >
          {!loadError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setLoadError(true)}
              className="w-full h-full object-cover"
              style={{ 
                imageRendering: 'auto',
                filter: `contrast(1.15) brightness(${0.35 + (1 - scrollProgress) * 0.25}) blur(${velocity * 0.06}px) saturate(1.1)`,
              }}
            />
          ) : (
            <div className="w-full h-full bg-[#0a0a0a] flex flex-col items-center justify-center text-center p-12">
               <div className="relative mb-10">
                  <div className="absolute inset-0 bg-red-500 blur-[80px] opacity-10" />
                  <WifiOff size={80} className="text-red-500 relative z-10 opacity-40" />
               </div>
               <h3 className="text-4xl font-black uppercase tracking-tighter italic mb-4">Signal Interrupted.</h3>
               <p className="text-white/20 text-xs font-bold uppercase tracking-[0.4em] max-w-lg leading-relaxed italic">
                 Remote source rejected connection. This usually occurs when using a social media link instead of a direct MP4 source.
               </p>
               <button 
                 onClick={() => window.location.reload()}
                 className="mt-12 flex items-center gap-3 text-[10px] font-black uppercase tracking-[0.3em] text-white/40 hover:text-white transition-colors"
               >
                 <RefreshCcw size={14} /> Retry Hardware Link
               </button>
            </div>
          )}
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_30%,rgba(0,0,0,0.9)_130%)] z-10" />
        </div>

        {showText && !loadError && (
          <div className="absolute inset-0 z-20 flex pointer-events-none">
            {sections.map((section, idx) => {
              const distance = Math.abs(scrollProgress - section.triggerTime);
              const isActive = distance < 0.07;
              const opacity = Math.max(0, 1 - distance * 15);

              return (
                <div
                  key={idx}
                  className={`absolute inset-0 flex px-16 md:px-32 py-20 ${
                    section.alignment === 'left' ? 'justify-start items-center text-left' : 
                    section.alignment === 'right' ? 'justify-end items-center text-right' : 
                    'justify-center items-center text-center'
                  }`}
                  style={{ 
                    opacity,
                    visibility: opacity > 0.01 ? 'visible' : 'hidden',
                    transform: `translateY(${(scrollProgress - section.triggerTime) * 180}px)`,
                  }}
                >
                  <div className="max-w-6xl">
                    <div className="overflow-hidden mb-12">
                       <h2 className={`text-[8rem] md:text-[12rem] font-black uppercase italic tracking-[-0.09em] transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) leading-[0.8] ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/5'}`}>
                         {section.title}
                       </h2>
                    </div>
                    <div className={`transition-all duration-1000 delay-500 border-white/10 ${section.alignment === 'right' ? 'border-r pr-12 ml-auto' : section.alignment === 'center' ? 'px-12 mx-auto' : 'border-l pl-12'} ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
                      <p className="text-xl md:text-2xl text-white/40 font-medium leading-relaxed max-w-xl italic tracking-[0.05em] uppercase">
                        {section.description}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* PRO Telemetry Panel */}
        <div className="absolute bottom-16 left-16 z-30 flex items-end gap-16 pointer-events-none">
           <div className="flex flex-col gap-3">
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.5em] italic">AEON CORE ENGINE</span>
              <div className="flex items-center gap-8">
                 <InfinityLogo size={32} className="text-white/10" />
                 <div className="h-10 w-[1px] bg-white/5" />
                 <div className="flex flex-col gap-2 font-mono text-[9px] text-white/30 uppercase tracking-[0.2em]">
                    <div className="flex items-center gap-4">
                       <span className="text-white/10">V_VEL</span>
                       <span className="text-white/60">{velocity.toFixed(4)}</span>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="text-white/10">T_POS</span>
                       <span className="text-white/60">{(scrollProgress * 100).toFixed(2)}%</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>

        {/* Global Progress Line */}
        <div className="absolute bottom-0 left-0 w-full h-[2px] bg-white/5 z-40">
           <div 
             className="h-full bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.8)] transition-all duration-500" 
             style={{ width: `${scrollProgress * 100}%` }}
           />
        </div>
      </div>
    </div>
  );
};

