import React, { useState } from 'react';
import { Github, Zap, Terminal, Layers } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateStandaloneHTML } from './services/exportService';
import { VideoState } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
  });

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, isAnalyzing: true }));
    const description = `A cinematic video titled "${title}". Video context: ${metadata}. Create a high-end landing page narrative.`;

    try {
      const storySections = await generateVideoStory(description);
      setState({
        url,
        duration: 0,
        sections: storySections,
        isAnalyzing: false,
      });
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const handleFileSelect = async (file: File) => {
    const url = URL.createObjectURL(file);
    await analyzeVideo(url, file.name, `Local upload, type ${file.type}`);
  };

  const handleSampleSelect = async (url: string, name: string) => {
    await analyzeVideo(url, name, `Sample stock video, professional grade cinematic visuals`);
  };

  const handleReset = () => {
    setState({
      url: null,
      duration: 0,
      sections: [],
      isAnalyzing: false,
    });
  };

  const handleDownloadCode = () => {
    if (!state.sections.length) return;
    const htmlContent = generateStandaloneHTML(state.sections);
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'aeon-infinity-export.html';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white selection:bg-indigo-500 selection:text-white antialiased overflow-x-hidden">
      {/* Precision Navigation */}
      <nav className="fixed top-0 left-0 w-full z-[100] px-10 py-8 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <div 
          className="flex items-center gap-4 cursor-pointer group"
          onClick={handleReset}
        >
          <InfinityLogo size={32} className="text-white transform group-hover:rotate-12 transition-transform duration-700 ease-out" />
          <div className="flex flex-col">
            <span className="font-extrabold text-xl tracking-[0.3em] uppercase italic leading-none">AEON</span>
            <span className="text-[7px] font-black text-indigo-500 tracking-[0.6em] uppercase mt-1">Infinity Labs</span>
          </div>
        </div>

        <div className="flex items-center gap-10">
          <div className="hidden md:flex items-center gap-12">
            <a href="#" className="text-[9px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-white transition-colors">Framework</a>
            <a href="#" className="text-[9px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-white transition-colors">Manifesto</a>
          </div>
          <a href="#" className="p-3 bg-white/5 rounded-full hover:bg-white/10 transition-colors border border-white/5">
            <Github size={16} />
          </a>
        </div>
      </nav>

      {!state.url ? (
        <main className="relative min-h-screen flex flex-col items-center justify-center px-6 pt-24 pb-20">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[1200px] h-[1200px] bg-indigo-600/[0.03] blur-[250px] rounded-full pointer-events-none" />

          <div className="text-center mb-20 max-w-7xl relative z-10">
            <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-white/5 bg-white/5 text-[8px] font-bold uppercase tracking-[0.5em] mb-12 text-indigo-400 italic">
              <Terminal size={10} />
              Infinity Sync Engine Ready
            </div>

            <h1 className="text-[12vw] md:text-[9rem] font-black tracking-[-0.07em] mb-12 leading-[0.75] italic uppercase text-white">
              Infinite<br />
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-white via-white/40 to-white/10">Synthesis.</span>
            </h1>

            <p className="text-base md:text-lg text-white/30 font-medium max-w-xl mx-auto leading-relaxed tracking-[0.1em] uppercase italic border-l border-white/10 pl-8">
              Transforming raw motion into narrative experiences through temporal scroll-synchronization.
            </p>
          </div>

          <FileUpload 
            onFileSelect={handleFileSelect} 
            onSampleSelect={handleSampleSelect}
            isAnalyzing={state.isAnalyzing} 
          />
        </main>
      ) : (
        <section className="relative">
          {/* Experience Telemetry Overlay */}
          <div className="fixed top-32 right-10 z-[100] flex flex-col gap-6 items-end">
             <div className="p-6 bg-black/40 backdrop-blur-3xl border border-white/10 rounded-3xl flex flex-col gap-4 min-w-[180px]">
