import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  showText?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, showText = true }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;
    const lerpFactor = 0.08; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      if (Math.abs(video.currentTime - targetTime) > 0.001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      if (rect.top <= window.innerHeight && rect.bottom >= 0) {
        const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
        const progress = Math.max(0, Math.min(1, -rect.top / totalScrollable));
        targetProgress.current = progress;
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getBackgroundTransform = () => {
    const scale = 1 + scrollProgress * 0.08;
    const rotateY = (scrollProgress - 0.5) * 1.2;
    const skewX = velocity * 0.005; 
    return `perspective(3000px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg) translateZ(0)`;
  };

  return (
    <div 
      ref={containerRef} 
      className="scroll-motion-root relative w-full h-[1000vh] bg-black overflow-clip"
      id="aeon-engine"
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden">

        {/* Dynamic Agency Letterboxing */}
        <div className="absolute top-0 left-0 w-full z-50 bg-black transition-all duration-[1200ms] cubic-bezier(0.16,1,0.3,1) pointer-events-none" style={{ height: `${10 + velocity * 0.2}%` }} />
        <div className="absolute bottom-0 left-0 w-full z-50 bg-black transition-all duration-[1200ms] cubic-bezier(0.16,1,0.3,1) pointer-events-none" style={{ height: `${10 + velocity * 0.2}%` }} />

        <div 
          className="absolute inset-0 z-0 will-change-transform pointer-events-none"
          style={{ 
            transform: getBackgroundTransform(),
            backfaceVisibility: 'hidden',
            WebkitBackfaceVisibility: 'hidden',
            transformStyle: 'preserve-3d'
          }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              imageRendering: 'auto',
              filter: `contrast(1.2) brightness(${0.3 + (1 - scrollProgress) * 0.3}) blur(${velocity * 0.08}px) saturate(1.2)`,
            }}
          />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_20%,rgba(0,0,0,0.95)_140%)] z-10" />
        </div>

        {showText && (
          <div className="absolute inset-0 z-20 flex pointer-events-none">
            {sections.map((section, idx) => {
              const distance = Math.abs(scrollProgress - section.triggerTime);
              const isActive = distance < 0.06;
              const opacity = Math.max(0, 1 - distance * 18);

              return (
                <div
                  key={idx}
                  className={`absolute inset-0 flex px-20 md:px-40 py-24 ${
                    section.alignment === 'left' ? 'justify-start items-center text-left' : 
                    section.alignment === 'right' ? 'justify-end items-center text-right' : 
                    'justify-center items-center text-center'
                  }`}
                  style={{ 
                    opacity,
                    visibility: opacity > 0.01 ? 'visible' : 'hidden',
                    transform: `translateY(${(scrollProgress - section.triggerTime) * 220}px)`,
                  }}
                >
                  <div className="max-w-7xl">
                    <div className="overflow-hidden mb-16">
                       <h2 className={`text-[10rem] md:text-[14rem] font-black uppercase italic tracking-[-0.1em] transition-all duration-[1500ms] cubic-bezier(0.16, 1, 0.3, 1) leading-[0.75] ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/5'}`}>
                         {section.title}
                       </h2>
                    </div>
                    <div className={`transition-all duration-[1500ms] delay-700 border-indigo-600 ${section.alignment === 'right' ? 'border-r-2 pr-16 ml-auto' : section.alignment === 'center' ? 'px-16 mx-auto' : 'border-l-2 pl-16'} ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-16'}`}>
                      <p className="text-2xl md:text-3xl text-white/40 font-light leading-relaxed max-w-2xl italic tracking-[0.05em] uppercase">
                        {section.description}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* HUD Telemetry Visualizer */}
        <div className="absolute bottom-20 left-20 z-30 flex items-end gap-20 pointer-events-none">
           <div className="flex flex-col gap-5">
              <span className="text-[11px] font-black text-indigo-500 uppercase tracking-[0.8em] italic">Aeon Sync Engine v4.2</span>
              <div className="flex items-center gap-10">
                 <InfinityLogo size={36} className="text-white/10" />
                 <div className="h-12 w-[1px] bg-white/5" />
                 <div className="flex flex-col gap-3 font-mono text-[10px] text-white/20 uppercase tracking-[0.4em]">
                    <div className="flex items-center gap-6">
                       <span className="opacity-40">VELOCITY</span>
                       <span className="text-white/60 tabular-nums">{velocity.toFixed(5)}</span>
                    </div>
                    <div className="flex items-center gap-6">
                       <span className="opacity-40">PROGRESS</span>
                       <span className="text-white/60 tabular-nums">{(scrollProgress * 100).toFixed(2)}%</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>

        {/* Global Progress Hardware Line */}
        <div className="absolute bottom-0 left-0 w-full h-[3px] bg-white/5 z-40">
           <div 
             className="h-full bg-indigo-600 shadow-[0_0_30px_rgba(79,70,229,1)] transition-all duration-700 ease-out" 
             style={{ width: `${scrollProgress * 100}%` }}
           />
        </div>
      </div>
    </div>
  );
};

