const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;
    const lerpFactor = 0.08; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    const v = Math.abs(currentProgress.current - prevProgress) * 100;
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      // Precision seek
      if (Math.abs(video.currentTime - targetTime) > 0.001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalHeight = containerRef.current.offsetHeight;
      const viewportHeight = window.innerHeight;

      // Calculate progress strictly within the container bounds
      const scrolled = -rect.top;
      const scrollable = totalHeight - viewportHeight;
      const progress = Math.max(0, Math.min(1, scrolled / scrollable));

      targetProgress.current = progress;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  const getBackgroundTransform = () => {
    const scale = 1 + scrollProgress * 0.05;
    const rotateY = (scrollProgress - 0.5) * 0.5;
    const skewX = velocity * 0.002; 
    return `perspective(2000px) rotateY(${rotateY}deg) scale(${scale}) skewX(${skewX}deg) translateZ(0)`;
  };

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-[1200vh] bg-black"
      id="aeon-engine"
    >
      <div className="sticky top-0 left-0 w-full h-[100vh] h-[100dvh] overflow-hidden">

        {/* Cinema Bars - Dynamic height based on movement */}
        <div className="absolute top-0 left-0 w-full z-50 bg-black transition-all duration-[1000ms] ease-out pointer-events-none" style={{ height: `${12 + velocity * 0.1}%` }} />
        <div className="absolute bottom-0 left-0 w-full z-50 bg-black transition-all duration-[1000ms] ease-out pointer-events-none" style={{ height: `${12 + velocity * 0.1}%` }} />

        {/* Visual Layer */}
        <div 
          className="absolute inset-0 z-0 will-change-transform pointer-events-none"
          style={{ 
            transform: getBackgroundTransform(),
            backfaceVisibility: 'hidden',
            WebkitBackfaceVisibility: 'hidden',
            transformStyle: 'preserve-3d'
          }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `contrast(1.2) brightness(${0.4 + (1 - scrollProgress) * 0.2}) blur(${velocity * 0.05}px) saturate(1.1)`,
            }}
          />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_30%,rgba(0,0,0,0.95)_140%)] z-10" />
        </div>

        {/* Narrative Layer */}
        <div className="absolute inset-0 z-20 flex pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const isActive = distance < 0.05;
            const opacity = Math.max(0, 1 - distance * 15);

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex px-16 md:px-32 py-24 ${
                  section.alignment === 'left' ? 'justify-start items-center text-left' : 
                  section.alignment === 'right' ? 'justify-end items-center text-right' : 
                  'justify-center items-center text-center'
                }`}
                style={{ 
                  opacity,
                  visibility: opacity > 0.01 ? 'visible' : 'hidden',
                  transform: `translateY(${(scrollProgress - section.triggerTime) * 150}px)`,
                }}
              >
                <div className="max-w-5xl">
                  <div className="overflow-hidden mb-12">
                     <h2 className={`text-[8vw] md:text-[8rem] font-black uppercase italic tracking-[-0.08em] transition-all duration-[1200ms] cubic-bezier(0.16, 1, 0.3, 1) leading-[0.85] ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/5'}`}>
                       {section.title}
                     </h2>
                  </div>
                  <div className={`transition-all duration-[1200ms] delay-500 border-indigo-600/50 ${section.alignment === 'right' ? 'border-r-2 pr-12 ml-auto' : section.alignment === 'center' ? 'px-12 mx-auto' : 'border-l-2 pl-12'} ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
                    <p className="text-xl md:text-2xl text-white/40 font-light leading-relaxed max-w-xl italic tracking-[0.05em] uppercase">
                      {section.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Telemetry Panel */}
        <div className="absolute bottom-20 left-20 z-[60] flex items-end gap-16 pointer-events-none opacity-40 hover:opacity-100 transition-opacity">
           <div className="flex flex-col gap-4">
              <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.6em] italic">Aeon Sync Engine</span>
              <div className="flex items-center gap-8">
                 <InfinityLogo size={32} className="text-white/10" />
                 <div className="h-10 w-[1px] bg-white/10" />
                 <div className="flex flex-col gap-2 font-mono text-[9px] text-white/30 uppercase tracking-[0.2em]">
                    <div className="flex items-center gap-4">
                       <span className="opacity-20 tabular-nums">VEL: {velocity.toFixed(4)}</span>
                    </div>
                    <div className="flex items-center gap-4">
                       <span className="opacity-20 tabular-nums">POS: {(scrollProgress * 100).toFixed(2)}%</span>
                    </div>
                 </div>
              </div>
           </div>
        </div>

        {/* Hardware Progress Line */}
        <div className="absolute bottom-0 left-0 w-full h-[4px] bg-white/5 z-[70]">
           <div 
             className="h-full bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.8)] transition-all duration-700 ease-out" 
             style={{ width: `${scrollProgress * 100}%` }}
           />
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

