import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scrollProgress, setScrollProgress] = useState(0);
  const [velocity, setVelocity] = useState(0);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const requestRef = useRef<number>(null);

  const animate = () => {
    const prevProgress = currentProgress.current;
    const lerpFactor = 0.1; 
    currentProgress.current += (targetProgress.current - currentProgress.current) * lerpFactor;

    const v = Math.abs(currentProgress.current - prevProgress);
    setVelocity(v);

    const video = videoRef.current;
    if (video && video.duration && !video.seeking) {
      const targetTime = video.duration * currentProgress.current;
      if (Math.abs(video.currentTime - targetTime) > 0.0001) {
        video.currentTime = targetTime;
      }
    }

    setScrollProgress(currentProgress.current);
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalHeight = containerRef.current.offsetHeight;
      const viewportHeight = window.innerHeight;

      const scrolled = -rect.top;
      const scrollable = totalHeight - viewportHeight;
      const progress = Math.max(0, Math.min(1, scrolled / scrollable));

      targetProgress.current = progress;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    requestRef.current = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-[1200vh] bg-black"
      id="aeon-engine"
    >
      <div className="sticky top-0 left-0 w-full h-[100vh] h-[100dvh] overflow-hidden">

        {/* Deep Field Cinematic Gradients */}
        <div className="absolute inset-0 z-10 pointer-events-none">
          <div className="absolute top-0 left-0 w-full h-1/4 bg-gradient-to-b from-black via-black/60 to-transparent" />
          <div className="absolute bottom-0 left-0 w-full h-1/4 bg-gradient-to-t from-black via-black/60 to-transparent" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_30%,rgba(0,0,0,0.8)_150%)]" />
        </div>

        {/* Visual Engine: High Performance */}
        <div 
          className="absolute inset-0 z-0 will-change-transform"
          style={{ 
            transform: `scale(${1 + scrollProgress * 0.05}) translateZ(0)`,
          }}
        >
          <video
            ref={videoRef}
            src={videoUrl}
            playsInline
            muted
            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `contrast(1.1) brightness(${0.5 + (1 - scrollProgress) * 0.2}) saturate(1.1)`,
            }}
          />
        </div>

        {/* Narrative Layer: Standardized Text Scale */}
        <div className="absolute inset-0 z-20 flex pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const isActive = distance < 0.06;
            const opacity = Math.max(0, 1 - distance * 12);

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex px-12 md:px-32 py-20 ${
                  section.alignment === 'left' ? 'justify-start items-center text-left' : 
                  section.alignment === 'right' ? 'justify-end items-center text-right' : 
                  'justify-center items-center text-center'
                }`}
                style={{ 
                  opacity,
                  visibility: opacity > 0.01 ? 'visible' : 'hidden',
                  transform: `translateY(${(scrollProgress - section.triggerTime) * 120}px)`,
                }}
              >
                <div className="max-w-5xl w-full">
                  <div className="overflow-hidden mb-10">
                     <h2 className={`text-[clamp(3rem,10vw,7rem)] font-black uppercase italic tracking-[-0.08em] transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) leading-[0.85] ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/5'}`}>
                       {section.title}
                     </h2>
                  </div>
                  <div className={`transition-all duration-1000 delay-300 border-indigo-600/40 ${section.alignment === 'right' ? 'border-r-2 pr-12 ml-auto' : section.alignment === 'center' ? 'px-12 mx-auto' : 'border-l-2 pl-12'} ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-12'}`}>
                    <p className="text-xl md:text-3xl text-white/40 font-light leading-relaxed italic tracking-[0.05em] uppercase">
                      {section.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Dynamic HUD Telemetry */}
        <div className="absolute bottom-16 left-16 z-40 flex items-end gap-16 pointer-events-none opacity-40">
           <div className="flex flex-col gap-4">
              <span className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.6em] italic">Aeon_Infinity_v4</span>
              <div className="flex items-center gap-8">
                 <InfinityLogo size={32} className="text-white/20" />
                 <div className="h-10 w-[1px] bg-white/10" />
                 <div className="flex flex-col gap-1 font-mono text-[9px] text-white/30 uppercase tracking-[0.2em]">
                    <span className="tabular-nums">FPS: 60.00</span>
                    <span className="tabular-nums">MAP: {(scrollProgress * 100).toFixed(1)}%</span>
                 </div>
              </div>
           </div>
        </div>

        {/* Global Hardware Progress */}
        <div className="absolute bottom-0 left-0 w-full h-[3px] bg-white/5 z-50">
           <div 
             className="h-full bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.8)] transition-all duration-700 ease-out" 
             style={{ width: `${scrollProgress * 100}%` }}
           />
