import { ScrollSection } from "../types";

export function generateStandaloneHTML(sections: ScrollSection[]): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!DOCTYPE html>
<!-- 
  AEON // INFINITY
  ====================================
  SCROLL-DRIVEN CINEMATIC ENGINE
-->

<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AEON EXPERIENCE</title>
    <style>
        body { margin: 0; background: #000; overflow-x: hidden; color: #fff; font-family: sans-serif; }
        #aeon-root { position: relative; width: 100%; height: 1000vh; }
        .cinema-title { font-weight: 900; text-transform: uppercase; font-style: italic; color: #fff; margin: 0; line-height: 0.85; letter-spacing: -0.08em; font-size: clamp(3rem, 10vw, 7rem); }
        .cinema-body { font-weight: 300; text-transform: uppercase; font-style: italic; letter-spacing: 0.05em; color: rgba(255,255,255,0.4); font-size: clamp(1rem, 2.5vw, 1.75rem); line-height: 1.4; }
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: #000; }
        ::-webkit-scrollbar-thumb { background: #4f46e5; border-radius: 10px; }
    </style>
</head>
<body>

<div id="aeon-root">
    <div id="sm-viewport" style="position: sticky; top: 0; width: 100%; height: 100vh; height: 100dvh; overflow: hidden;">

        <div id="sm-video-layer" style="position: absolute; inset: 0; z-index: 0; will-change: transform; pointer-events: none;">
            <video id="sm-video-element" playsinline muted style="width: 100%; height: 100%; object-fit: cover; filter: contrast(1.1) brightness(0.6);"></video>
            <div style="position: absolute; inset: 0; background: radial-gradient(circle, transparent 30%, rgba(0,0,0,0.8) 150%);"></div>
        </div>

        <div id="sm-ui-layer" style="position: absolute; inset: 0; z-index: 10; pointer-events: none;"></div>
        <div id="sm-progress-bar" style="position: absolute; bottom: 0; left: 0; height: 3px; background: #4f46e5; width: 0%; z-index: 20;"></div>
    </div>
</div>

<script>
(function() {
    const CONFIG = {
        videoPath: "REPLACE_WITH_YOUR_VIDEO_URL.mp4", 
        smoothness: 0.1,
        textDuration: 0.06
    };

    const sections = ${sectionsJSON};
    const video = document.getElementById('sm-video-element');
    const vLayer = document.getElementById('sm-video-layer');
    const ui = document.getElementById('sm-ui-layer');
    const pBar = document.getElementById('sm-progress-bar');
    const root = document.getElementById('aeon-root');

    video.src = CONFIG.videoPath;
    let target = 0, current = 0;

    sections.forEach((s, i) => {
        const wrap = document.createElement('div');
        wrap.id = 'sec-' + i;
        wrap.style.cssText = 'position:absolute; inset:0; display:flex; padding:8%; opacity:0; visibility:hidden; transition:opacity 0.5s;';
        const alignMap = {
            left: 'justify-content:flex-start; align-items:center; text-align:left;',
            right: 'justify-content:flex-end; align-items:center; text-align:right;',
            center: 'justify-content:center; align-items:center; text-align:center;'
        };
        wrap.style.cssText += alignMap[s.alignment] || alignMap.center;
        wrap.innerHTML = \`
            <div style="max-width: 60rem;">
                <div style="overflow:hidden; margin-bottom: 2rem;">
                  <h2 id="t-\${i}" class="cinema-title" style="transition: transform 1s cubic-bezier(.16,1,.3,1); transform: translateY(100%);">\${s.title}</h2>
                </div>
                <div id="b-\${i}" style="border-left: 2px solid rgba(79,70,229,0.4); padding-left: 2rem; transition: all 1s 0.3s; opacity: 0; transform: translateY(20px);">
                  <p class="cinema-body">\${s.description}</p>
                </div>
            </div>
        \`;
        ui.appendChild(wrap);
    });

    function update() {
        current += (target - current) * CONFIG.smoothness;

        if (video.duration && !video.seeking) {
            video.currentTime = video.duration * current;
            vLayer.style.transform = \`scale(\${1 + current * 0.05}) translateZ(0)\`;
        }
        pBar.style.width = (current * 100) + '%';

        sections.forEach((s, i) => {
            const el = document.getElementById('sec-' + i);
            const t = document.getElementById('t-' + i);
            const b = document.getElementById('b-' + i);
            const dist = Math.abs(current - s.triggerTime);
            const isActive = dist < CONFIG.textDuration;
            const opacity = Math.max(0, 1 - dist * (1/CONFIG.textDuration));

            el.style.opacity = opacity;
            el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
            el.style.transform = \`translateY(\${(current - s.triggerTime) * 120}px)\`;

            if (isActive) {
                t.style.transform = 'translateY(0)';
                b.style.opacity = '1';
                b.style.transform = 'translateY(0)';
            } else {
                t.style.transform = 'translateY(100%)';
                b.style.opacity = '0';
                b.style.transform = 'translateY(20px)';
            }
        });
        requestAnimationFrame(update);
    }

    window.addEventListener('scroll', () => {
        const r = root.getBoundingClientRect();
        target = Math.max(0, Math.min(1, -r.top / (root.offsetHeight - window.innerHeight)));
    }, { passive: true });
    update();
})();
</script>
</body>
</html>`;
}

import React, { useState } from 'react';
