            <span className="font-black text-xl tracking-[0.4em] uppercase italic leading-none">AEON</span>
            <span className="text-[9px] font-black text-indigo-500 tracking-[0.6em] uppercase mt-1.5 opacity-60">Studio Core</span>
          </div>
        </div>

        {state.url && (
          <button 
            onClick={handleDownloadCode}
            className="group flex items-center gap-4 px-8 py-3 bg-white text-black rounded-full font-black text-[10px] uppercase tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all duration-500 active:scale-95 shadow-2xl pointer-events-auto"
