            preload="auto"
            className="w-full h-full object-cover"
            style={{ 
              filter: `contrast(1.1) brightness(${0.45 + (1 - scrollProgress) * 0.2}) saturate(1.1)`,
            }}
          />
        </div>

        {/* Narrative Layer: Standardized Text Scale with Overflow Protection */}
        <div className="absolute inset-0 z-20 flex pointer-events-none">
          {sections.map((section, idx) => {
            const distance = Math.abs(scrollProgress - section.triggerTime);
            const isActive = distance < 0.06;
            const opacity = Math.max(0, 1 - distance * 10);

            return (
              <div
                key={idx}
                className={`absolute inset-0 flex px-8 md:px-24 py-16 ${
                  section.alignment === 'left' ? 'justify-start items-center text-left' : 
                  section.alignment === 'right' ? 'justify-end items-center text-right' : 
                  'justify-center items-center text-center'
                }`}
                style={{ 
                  opacity,
                  visibility: opacity > 0.01 ? 'visible' : 'hidden',
                  transform: `translateY(${(scrollProgress - section.triggerTime) * 100}px)`,
                }}
              >
                <div className="max-w-4xl w-full">
                  <div className="overflow-visible mb-8">
                     <h2 className={`text-[clamp(2.5rem,8vw,5.5rem)] font-black uppercase italic tracking-[-0.06em] transition-all duration-1000 cubic-bezier(0.16, 1, 0.3, 1) leading-[0.9] pb-2 ${isActive ? 'translate-y-0 text-white' : 'translate-y-full text-white/5'}`}>
                       {section.title}
                     </h2>
                  </div>
                  <div className={`transition-all duration-1000 delay-300 border-indigo-600/40 ${section.alignment === 'right' ? 'border-r-2 pr-10 ml-auto' : section.alignment === 'center' ? 'px-10 mx-auto' : 'border-l-2 pl-10'} ${isActive ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-10'}`}>
                    <p className="text-lg md:text-2xl text-white/40 font-light leading-relaxed italic tracking-[0.04em] uppercase max-w-lg">
                      {section.description}
                    </p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Telemetry HUD */}
        <div className="absolute bottom-16 left-12 z-40 flex items-end gap-12 pointer-events-none opacity-30">
           <div className="flex flex-col gap-3">
              <span className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.4em] italic">Aeon_Core_v4</span>
              <div className="flex items-center gap-6">
                 <InfinityLogo size={28} className="text-white/20" />
                 <div className="h-8 w-[1px] bg-white/10" />
                 <div className="flex flex-col gap-1 font-mono text-[8px] text-white/30 uppercase tracking-[0.2em]">
                    <span className="tabular-nums">FPS: 60.00</span>
                    <span className="tabular-nums">SYNC: {(scrollProgress * 100).toFixed(1)}%</span>
                 </div>
              </div>
           </div>
        </div>

        {/* Global Progress Bar */}
        <div className="absolute bottom-0 left-0 w-full h-[2px] bg-white/5 z-50">
           <div 
             className="h-full bg-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.7)] transition-all duration-500 ease-out" 
             style={{ width: `${scrollProgress * 100}%` }}
           />
        </div>
      </div>
    </div>
  );
};

