              <Terminal size={12} className="opacity-50" />
              Engine Online // Module 4.2
            </div>

            <h1 className="text-[clamp(3.5rem,11vw,8rem)] font-black tracking-[-0.04em] mb-12 leading-[1.0] italic uppercase text-white px-4 relative">
              <span className="block opacity-0 animate-[slide-up_0.8s_ease-out_forwards]">Temporal</span>
              <span className="block text-transparent bg-clip-text bg-gradient-to-r from-white via-indigo-100 to-indigo-400/80 opacity-0 animate-[slide-up_1s_ease-out_0.2s_forwards] py-2">Synthesis</span>
