import React, { useState } from 'react';
import { Code, Terminal, Layers, ArrowUpRight } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateStandaloneHTML } from './services/exportService';
import { VideoState } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
  });

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, isAnalyzing: true }));
    const description = `A cinematic video titled "${title}". Video context: ${metadata}. Create a high-end landing page narrative.`;

    try {
      const storySections = await generateVideoStory(description);
      setState({
        url,
        duration: 0,
        sections: storySections,
        isAnalyzing: false,
      });
    } catch (error) {
      console.error(error);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const handleFileSelect = async (file: File) => {
    const url = URL.createObjectURL(file);
    await analyzeVideo(url, file.name, `Local upload, type ${file.type}`);
  };

  const handleSampleSelect = async (url: string, name: string) => {
    await analyzeVideo(url, name, `Sample stock video, professional grade cinematic visuals`);
  };

  const handleReset = () => {
    setState({
      url: null,
      duration: 0,
      sections: [],
      isAnalyzing: false,
    });
  };

  const handleDownloadCode = () => {
    if (!state.sections.length) return;
    const htmlContent = generateStandaloneHTML(state.sections);
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'aeon-project.html';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-[#020202] text-white selection:bg-indigo-600 selection:text-white antialiased">
      {/* Brand Navigation */}
      <nav className="fixed top-0 left-0 w-full z-[100] px-8 md:px-16 py-8 flex justify-between items-center bg-gradient-to-b from-black/90 via-black/40 to-transparent pointer-events-none">
        <div 
          className="flex items-center gap-4 cursor-pointer group pointer-events-auto"
          onClick={handleReset}
        >
          <InfinityLogo size={32} className="text-white relative z-10 transition-all duration-500 group-hover:scale-110 group-hover:text-indigo-400" />
          <div className="flex flex-col">
            <span className="font-black text-lg tracking-[0.3em] uppercase italic leading-none">AEON</span>
            <span className="text-[8px] font-black text-indigo-500 tracking-[0.5em] uppercase mt-1 opacity-50">Studio Core</span>
          </div>
        </div>

        {state.url && (
          <button 
            onClick={handleDownloadCode}
            className="group flex items-center gap-3 px-6 py-2.5 bg-white text-black rounded-full font-black text-[9px] uppercase tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all duration-500 active:scale-95 shadow-2xl pointer-events-auto"
          >
            <Code size={12} />
            Export Output
          </button>
        )}
      </nav>

      {!state.url ? (
        <main className="relative min-h-screen flex flex-col items-center justify-center px-6 pt-16 pb-32 overflow-hidden">
          {/* Enhanced Luminous Mesh Gradients */}
          <div className="absolute top-[-20%] left-[-10%] w-[80%] h-[80%] bg-indigo-600/10 blur-[200px] rounded-full animate-pulse pointer-events-none" />
          <div className="absolute bottom-[-20%] right-[-10%] w-[70%] h-[70%] bg-purple-600/5 blur-[200px] rounded-full pointer-events-none" />

          <div className="text-center mb-16 max-w-7xl relative z-10 w-full">
            <h1 className="text-[clamp(3.5rem,10vw,8rem)] font-black tracking-[-0.04em] mb-12 leading-[1.05] italic uppercase text-white px-4 relative">
              <span className="block opacity-0 animate-[slide-up_0.8s_ease-out_forwards]">Narrative</span>
              <span className="block text-transparent bg-clip-text bg-gradient-to-r from-white via-indigo-50 to-indigo-300 opacity-0 animate-[slide-up_1s_ease-out_0.2s_forwards] py-2">Scroll</span>
            </h1>

            <p className="text-base md:text-xl text-white/40 font-light max-w-xl mx-auto leading-relaxed tracking-[0.03em] uppercase italic border-l border-indigo-600/40 pl-8 text-left">
              Transforming raw cinematic assets into interactive, scroll-synchronized storytelling architectures.
            </p>
