                <div className="flex justify-between items-center text-[9px] tracking-widest font-black">
                  <span className="text-white/30 uppercase">Sync</span>
                  <span className="text-indigo-400 uppercase">Active</span>
                </div>
                <button 
                  onClick={handleReset}
                  className="mt-2 text-[9px] font-black text-white/40 hover:text-white uppercase tracking-[0.2em] transition-all flex items-center justify-between"
                >
                  Detach Core <ArrowUpRight size={10} />
                </button>
             </div>
          </div>

          <VideoScroller 
            videoUrl={state.url} 
