                <button 
                  onClick={handleDownloadCode}
                  className="group px-16 py-6 bg-white text-black font-black text-sm uppercase tracking-[0.15em] rounded-full hover:bg-indigo-600 hover:text-white transition-all active:scale-95 shadow-2xl"
                >
                  Download Project
                </button>
                <button 
                  onClick={handleReset}
                  className="px-16 py-6 border border-white/10 text-white/40 font-black text-sm uppercase tracking-[0.15em] rounded-full hover:bg-white/5 hover:text-white transition-all active:scale-95"
