export function generateStandaloneHTML(sections: ScrollSection[]): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!DOCTYPE html>
<!-- 
  ========================================================================
  AEON // INFINITY - EXPORTED EXPERIENCE
  ========================================================================

  HOW TO IMPLEMENT THIS IN YOUR SITE:

  1. ASSETS: Host your video file (.mp4) on a fast CDN or your web server.
  2. CONFIG: Look for the 'CONFIG' object below and paste your video URL.
  3. STYLING: You can change colors and fonts in the <style> block.
  4. DEPLOY: Simply upload this HTML file to your server or embed it.

  Note: For best performance, use a video compressed for the web (H.264).
  ========================================================================
-->

<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AEON CINEMATIC NARRATIVE</title>
    <style>
        :root {
            --brand-color: #4f46e5;
            --bg-color: #000;
            --text-primary: #fff;
            --text-secondary: rgba(255, 255, 255, 0.4);
        }

        body { 
            margin: 0; 
            background: var(--bg-color); 
            overflow-x: hidden; 
            color: var(--text-primary); 
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; 
        }

        #aeon-root { 
            position: relative; 
            width: 100%; 
            height: 1000vh; /* Adjust this to change total scroll length */
        }

        .cinema-viewport {
            position: sticky; 
            top: 0; 
            width: 100%; 
            height: 100vh; 
            height: 100dvh; 
            overflow: hidden;
        }

        .video-container {
            position: absolute; 
            inset: 0; 
            z-index: 0; 
            will-change: transform; 
            pointer-events: none;
        }

        #sm-video-element {
            width: 100%; 
            height: 100%; 
            object-fit: cover; 
            filter: contrast(1.1) brightness(0.6);
        }

        .vignette {
            position: absolute; 
            inset: 0; 
            background: radial-gradient(circle, transparent 30%, rgba(0,0,0,0.85) 150%);
        }

        .cinema-title { 
            font-weight: 900; 
            text-transform: uppercase; 
