import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  // Ensure the API key is present as required by the platform guidelines
  if (!process.env.API_KEY) {
    throw new Error("API key must be set. Please use the 'Configure Key' button in the UI.");
  }

  // Initialize the AI instance using process.env.API_KEY directly as specified in the guidelines
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `Act as a world-class creative director for a high-end digital agency. 
  Analyze this video concept: "${videoDescription}".

  Generate exactly 5 distinct landing page sections that transform this video into a premium scroll-synchronized narrative.

  Requirements:
  1. Title: 1-3 words, evocative, powerful, and uppercase.
  2. Description: 15-25 words of high-end, abstract marketing copy.
  3. triggerTime: Perfectly spaced across the video duration (e.g., 0.15, 0.35, 0.55, 0.75, 0.95).
  4. alignment: Choose between 'left', 'right', 'center' to create a dynamic visual flow.
  5. vibe: 'cinematic', 'energetic', or 'minimal'.

  Return strictly as a JSON array.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from synthesis core.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);
  } catch (error: any) {
    console.warn("AI Synthesis bypassed, using default narrative core.", error);
    // Fallback cinematic structure if the AI is unavailable
    return [
      { title: "INITIAL PHASE", description: "Beginning the visual sequence with a focus on depth and atmospheric resonance.", triggerTime: 0.15, alignment: 'left', vibe: 'cinematic' },
      { title: "KINETIC FLOW", description: "Harnessing the raw motion within the frame to drive a high-energy user experience.", triggerTime: 0.35, alignment: 'right', vibe: 'energetic' },
      { title: "STATIC CALM", description: "A moment of architectural stillness, allowing the viewer to absorb the complexity of the scene.", triggerTime: 0.55, alignment: 'center', vibe: 'minimal' },
      { title: "CHROMATIC SYNC", description: "Exploring the interaction between light and shadow as the sequence nears its climax.", triggerTime: 0.75, alignment: 'left', vibe: 'cinematic' },
      { title: "FINALITY", description: "Closing the loop. The narrative returns to its origin, enriched by the journey through the visual spectrum.", triggerTime: 0.95, alignment: 'right', vibe: 'energetic' },
    ];
  }
}

