import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for 'Infinity', an AI startup. 
    Analyze this video: "${videoDescription}".

    The company vision is: "Infinity is an early-stage AI startup building next-generation intelligent systems that make advanced technology simple, natural, and accessible to everyone. We believe technology should have no limits."

    Generate 5 cinematic landing page sections (JSON array).
    Titles should be powerful (1-3 words). 
    Descriptions should be evocative (15-25 words).
    Use trigger times between 0.1 and 0.9.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    console.warn("Using bespoke Infinity fallback narrative.");

    // Updated fallback content specifically for the Infinity startup
    return [
      { 
        title: "NO LIMITS", 
        description: "Founded on the core belief that technology should have no boundaries. We are redefining the horizon of human potential.", 
        triggerTime: 0.12, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "NEXT-GEN SYSTEMS", 
        description: "Building intelligent systems that make advanced technology simple, natural, and accessible to every individual on the planet.", 
        triggerTime: 0.32, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
      { 
        title: "SEAMLESS SYNC", 
        description: "Our AI-powered applications integrate invisibly into daily life, making the complex feel effortless and the future feel present.", 
        triggerTime: 0.52, 
        alignment: 'center', 
        vibe: 'minimal' 
      },
      { 
        title: "FOUNDATIONAL CORE", 
        description: "We operate at the source, building the fundamental systems required for future-scale innovation and global intelligence.", 
        triggerTime: 0.72, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "INFINITY AI", 
        description: "An early-stage vision led by independent innovation. We are just beginning to architect the next era of technology.", 
        triggerTime: 0.92, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const hudSyncRef = useRef<HTMLSpanElement>(null);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastSeekTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      // Adjusted LERP for better responsiveness vs smoothness balance
      const lerp = 0.075;
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      // 1. Optimized Scrubbing Engine
      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        const diff = Math.abs(video.currentTime - targetTime);
        const timeSinceLastSeek = time - lastSeekTime.current;

        // Increase threshold slightly to avoid jitter (0.05s)
        // Only seek if significantly different or if some time has passed to let the decoder breathe
        if (!video.seeking && video.readyState >= 2 && (diff > 0.05 || timeSinceLastSeek > 33)) {
          video.currentTime = targetTime;
          lastSeekTime.current = time;
        }

        if (videoLayerRef.current) {
          // Subtle zoom out effect for depth
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      // 2. Telemetry & Progress
      if (progressBarRef.current) progressBarRef.current.style.width = `${progress * 100}%`;
      if (hudSyncRef.current) hudSyncRef.current.textContent = `${(progress * 100).toFixed(1)}%`;

      // 3. Section Transitions
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.09; // Slightly wider window for smoother fades
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < windowSize;

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Parallel motion for content
        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const title = el.querySelector('h2');
        const body = el.querySelector('.text-wrapper');
        if (title && body) {
          if (isActive) {
            (title as HTMLElement).style.transform = 'translate3d(0, 0, 0)';
            (body as HTMLElement).style.opacity = '1';
          } else {
            (title as HTMLElement).style.transform = 'translate3d(0, 110%, 0)';
            (body as HTMLElement).style.opacity = '0';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollable = containerRef.current.offsetHeight - window.innerHeight;
      // Clamp progress
      const prog = Math.max(0, Math.min(1, -rect.top / scrollable));
      targetProgress.current = prog;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1400vh] bg-[#020202]">
      <div className="sticky top-0 left-0 w-full h-screen h-[100dvh] overflow-hidden bg-black">

        {/* Cinematic Overlays */}
        <div className="absolute inset-0 z-10 pointer-events-none">
          <div className="absolute top-0 left-0 w-full h-1/2 bg-gradient-to-b from-black to-transparent" />
          <div className="absolute bottom-0 left-0 w-full h-1/2 bg-gradient-to-t from-black to-transparent" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_40%,rgba(0,0,0,0.8)_160%)]" />
        </div>

        {/* Video Core */}
        <div 
          ref={videoLayerRef}
          className="absolute inset-0 z-0 bg-[#050505] opacity-65 transition-opacity duration-1000"
        >
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center">
               <span className="text-[10px] font-black text-white/10 uppercase tracking-[1em]">Asset Load Error</span>
            </div>
          )}
        </div>

        {/* Narrative Layers */}
