import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for 'Infinity', an AI startup. 
    Analyze this video: "${videoDescription}".

    Company Context: "Infinity is an early-stage AI startup building next-generation intelligent systems that make advanced technology simple, natural, and accessible to everyone. We believe technology should have no limits."

    Generate 5 cinematic landing page sections (JSON array).
    - Titles: Strong, 1-2 words.
    - Descriptions: Based on the provided context, matching the video's visual flow.
    - Alignment: Vary between left, right, and center.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    // High-quality hardcoded fallback based on user's specific text
    return [
      { 
        title: "NO LIMITS", 
        description: "Founded on the belief that technology should have no boundaries. We are redefining the horizon of human intelligence.", 
        triggerTime: 0.15, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "NEXT-GEN SYSTEMS", 
        description: "Building intelligent systems that make advanced technology simple, natural, and accessible to every individual.", 
        triggerTime: 0.35, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
      { 
        title: "SEAMLESS SYNC", 
        description: "Our AI-powered applications integrate invisibly into daily human life, making the complex feel effortless.", 
        triggerTime: 0.55, 
        alignment: 'center', 
        vibe: 'minimal' 
      },
      { 
        title: "FOUNDATIONAL CORE", 
        description: "We operate in our formative stage, building the fundamental systems required for future-scale innovation.", 
        triggerTime: 0.75, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "BEYOND INFINITY", 
        description: "Operating independently to architect the future of technology. Simple. Natural. Accessible to everyone.", 
        triggerTime: 0.95, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const hudSyncRef = useRef<HTMLSpanElement>(null);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastSeekTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      // Smooth interpolation (LERP) - adjusted for a snappier feel
      const lerp = 0.085;
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      // PERFORMANCE OPTIMIZATION: Throttled Scrubbing
      // Browser decoders struggle with 60fps seeks. We only seek if diff > 0.04s
      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        const diff = Math.abs(video.currentTime - targetTime);
        const timeSinceLastSeek = time - lastSeekTime.current;

        if (!video.seeking && video.readyState >= 2 && (diff > 0.04 || timeSinceLastSeek > 40)) {
          video.currentTime = targetTime;
          lastSeekTime.current = time;
        }

        if (videoLayerRef.current) {
          // Subtle zoom-out to give a "pulling back" cinematic feeling
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      // Progress indicators
      if (progressBarRef.current) progressBarRef.current.style.width = `${progress * 100}%`;
      if (hudSyncRef.current) hudSyncRef.current.textContent = `${(progress * 100).toFixed(1)}%`;

      // Section logic
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.085;
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < windowSize;

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Vertical offset for "parallax" text effect
        const yOffset = (progress - section.triggerTime) * 150;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const title = el.querySelector('h2');
        const body = el.querySelector('.text-wrapper');
        if (title && body) {
          if (isActive) {
            (title as HTMLElement).style.transform = 'translate3d(0, 0, 0)';
            (body as HTMLElement).style.opacity = '1';
          } else {
            (title as HTMLElement).style.transform = 'translate3d(0, 110%, 0)';
            (body as HTMLElement).style.opacity = '0';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollable = containerRef.current.offsetHeight - window.innerHeight;
      const prog = Math.max(0, Math.min(1, -rect.top / scrollable));
      targetProgress.current = prog;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-[1200vh] bg-black"
      style={{ zIndex: 1 }} // Ensure it stays behind fixed navs but above standard page content
    >
      <div className="sticky top-0 left-0 w-full h-screen h-[100dvh] overflow-hidden bg-black">

        {/* Cinematic Overlays */}
        <div className="absolute inset-0 z-10 pointer-events-none">
          <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-b from-black to-transparent" />
          <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-t from-black to-transparent" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_40%,rgba(0,0,0,0.9)_180%)]" />
        </div>

        {/* Video Surface */}
        <div 
          ref={videoLayerRef}
          className="absolute inset-0 z-0 bg-black opacity-60"
        >
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center opacity-20">
               <span className="text-[10px] font-black uppercase tracking-[1em]">Asset Failure</span>
            </div>
          )}
        </div>

        {/* Text Layer */}
        <div className="absolute inset-0 z-20 flex pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex px-10 md:px-32 py-20 ${
                section.alignment === 'left' ? 'justify-start items-center text-left' : 
                section.alignment === 'right' ? 'justify-end items-center text-right' : 
                'justify-center items-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-5xl w-full">
                <div className="overflow-hidden mb-6">
                   <h2 className="text-[clamp(2.5rem,10vw,6.5rem)] font-black uppercase italic tracking-[-0.07em] leading-[0.85] pb-2 transition-transform duration-1000 cubic-bezier(0.16, 1, 0.3, 1) text-white">
                     {section.title}
                   </h2>
                </div>
                <div className={`text-wrapper transition-all duration-1000 delay-200 border-indigo-500/30 ${
                  section.alignment === 'right' ? 'border-r-2 pr-8 ml-auto' : 
                  section.alignment === 'center' ? 'px-8 mx-auto' : 
                  'border-l-2 pl-8'
                }`}>
                  <p className="text-lg md:text-2xl text-white/50 font-light leading-relaxed italic tracking-[0.03em] uppercase max-w-xl">
                    {section.description}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* HUD Data (Minimized) */}
        <div className="absolute bottom-12 left-12 z-40 flex items-end gap-6 pointer-events-none opacity-20">
           <InfinityLogo size={24} className="text-white" />
           <div className="flex flex-col gap-1 font-mono text-[7px] text-white uppercase tracking-widest">
              <span className="text-indigo-400">SYNC_ACTIVE</span>
              <span ref={hudSyncRef} className="tabular-nums">0.0%</span>
           </div>
        </div>

        {/* Bottom Progress Bar */}
        <div className="absolute bottom-0 left-0 w-full h-[1px] bg-white/5 z-50">
           <div 
             ref={progressBarRef}
             className="h-full bg-indigo-500/80 shadow-[0_0_8px_rgba(79,70,229,0.3)] transition-all duration-150" 
             style={{ width: '0%' }}
           />
        </div>
      </div>
    </div>
  );
};

