import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const hudSyncRef = useRef<HTMLSpanElement>(null);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastSeekTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      // Linear interpolation for smooth kinetic feel
      const lerp = 0.08;
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      // 1. PERFORMANCE ENGINE: Throttled Scrubbing
      // Updates are skipped if the difference is too small to save CPU/GPU overhead
      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        const diff = Math.abs(video.currentTime - targetTime);
        const timeSinceLastSeek = time - lastSeekTime.current;

        if (!video.seeking && video.readyState >= 2 && (diff > 0.05 || timeSinceLastSeek > 35)) {
          video.currentTime = targetTime;
          lastSeekTime.current = time;
        }

        if (videoLayerRef.current) {
          // Subtle zoom logic for depth
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      // 2. Telemetry Updates
      if (progressBarRef.current) progressBarRef.current.style.width = `${progress * 100}%`;
      if (hudSyncRef.current) hudSyncRef.current.textContent = `${(progress * 100).toFixed(1)}%`;

      // 3. Narrative Trigger System
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.08;
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < windowSize;

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Vertical parallax offset
        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const title = el.querySelector('h2');
        const body = el.querySelector('.text-wrapper');
        if (title && body) {
          if (isActive) {
            (title as HTMLElement).style.transform = 'translate3d(0, 0, 0)';
            (body as HTMLElement).style.opacity = '1';
          } else {
            (title as HTMLElement).style.transform = 'translate3d(0, 110%, 0)';
            (body as HTMLElement).style.opacity = '0';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollableHeight = containerRef.current.offsetHeight - window.innerHeight;
      if (scrollableHeight <= 0) return;

      const prog = Math.max(0, Math.min(1, -rect.top / scrollableHeight));
      targetProgress.current = prog;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-[1200vh] bg-black"
      style={{ isolation: 'isolate' }}
    >
      <div className="sticky top-0 left-0 w-full h-screen h-[100dvh] overflow-hidden bg-black z-0">

        {/* Cinematic Background Layer */}
        <div 
          ref={videoLayerRef}
          className="absolute inset-0 z-[-1] bg-black opacity-60 pointer-events-none"
        >
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center opacity-10">
               <span className="text-[10px] font-black uppercase tracking-[1em]">Engine Halted</span>
            </div>
          )}
        </div>

        {/* Cinematic Overlays (Top/Bottom Gradient) */}
        <div className="absolute inset-0 z-0 pointer-events-none">
          <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-b from-black via-black/40 to-transparent" />
          <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-t from-black via-black/40 to-transparent" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_40%,rgba(0,0,0,0.8)_160%)]" />
        </div>

        {/* Interactive Narrative Layer */}
        <div className="absolute inset-0 z-10 flex pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex px-10 md:px-32 py-20 ${
                section.alignment === 'left' ? 'justify-start items-center text-left' : 
                section.alignment === 'right' ? 'justify-end items-center text-right' : 
                'justify-center items-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-5xl w-full">
                <div className="overflow-hidden mb-6">
                   <h2 className="text-[clamp(2.5rem,10vw,7rem)] font-black uppercase italic tracking-[-0.07em] leading-[0.85] pb-2 transition-transform duration-1000 cubic-bezier(0.16, 1, 0.3, 1) text-white">
                     {section.title}
                   </h2>
                </div>
                <div className={`text-wrapper transition-all duration-1000 delay-200 border-indigo-500/30 ${
                  section.alignment === 'right' ? 'border-r-2 pr-8 ml-auto' : 
                  section.alignment === 'center' ? 'px-8 mx-auto' : 
                  'border-l-2 pl-8'
                }`}>
                  <p className="text-lg md:text-2xl text-white/50 font-light leading-relaxed italic tracking-[0.03em] uppercase max-w-xl">
                    {section.description}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* HUD Overlay */}
        <div className="absolute bottom-12 left-12 z-20 flex items-end gap-6 pointer-events-none opacity-20">
           <InfinityLogo size={24} className="text-white" />
           <div className="flex flex-col gap-1 font-mono text-[7px] text-white uppercase tracking-[0.2em]">
              <span className="text-indigo-400 font-bold">CORE_LINK_ACTIVE</span>
              <span ref={hudSyncRef} className="tabular-nums">0.0%</span>
           </div>
        </div>

        {/* Progress Bar */}
        <div className="absolute bottom-0 left-0 w-full h-[1px] bg-white/5 z-30">
           <div 
             ref={progressBarRef}
             className="h-full bg-indigo-500 shadow-[0_0_10px_rgba(79,70,229,0.3)]" 
             style={{ width: '0%' }}
           />
        </div>
      </div>
    </div>
  );
};

