        <div class="vignette"></div>
    </div>
    <div id="narrative-ui"></div>
    <div id="scroll-progress" style="width: 0%"></div>
</div>

<!-- OVERLAY: Your Website Content Goes Here -->
<div id="website-content">
    <!-- Examples of where your site sections would live -->
    <div class="content-section"></div>
    <div class="content-section"></div>
    <div class="content-section"></div>
</div>

<script>
(function() {
    const CONFIG = {
        videoURL: "REPLACE_WITH_YOUR_VIDEO_URL.mp4", 
        lerp: 0.08,
        window: 0.08
    };

    const sections = ${sectionsJSON};
    const video = document.getElementById('bg-video');
    const videoLayer = document.getElementById('video-layer');
    const narrativeUI = document.getElementById('narrative-ui');
    const progressEl = document.getElementById('scroll-progress');

    video.src = CONFIG.videoURL;

    // Create UI Elements
    sections.forEach((s, i) => {
        const wrap = document.createElement('div');
        wrap.className = 'narrative-layer';
        wrap.id = 'n-' + i;

        const align = s.alignment || 'center';
        if(align === 'left') wrap.style.cssText = 'justify-content: flex-start; align-items: center; text-align: left;';
        else if(align === 'right') wrap.style.cssText = 'justify-content: flex-end; align-items: center; text-align: right;';
        else wrap.style.cssText = 'justify-content: center; align-items: center; text-align: center;';

        wrap.innerHTML = \`
            <div style="max-width: 60rem;">
                <div style="overflow:hidden; margin-bottom: 2rem;">
                    <h2 class="cinema-title" style="transform: translateY(110%); transition: transform 0.8s cubic-bezier(.16,1,.3,1);">\${s.title}</h2>
                </div>
                <div class="desc-wrap" style="opacity:0; transition: opacity 1s 0.2s;">
                    <p class="cinema-body">\${s.description}</p>
                </div>
            </div>
        \`;
        narrativeUI.appendChild(wrap);
    });

    let targetProg = 0;
    let currentProg = 0;
    let lastSeek = 0;

    function loop(time) {
        currentProg += (targetProg - currentProg) * CONFIG.lerp;

        if (video.duration) {
            const tTime = video.duration * currentProg;
            if (!video.seeking && (Math.abs(video.currentTime - tTime) > 0.04 || (time - lastSeek > 40))) {
                video.currentTime = tTime;
                lastSeek = time;
            }
            const z = 1.05 - (currentProg * 0.05);
            videoLayer.style.transform = \`scale3d(\${z}, \${z}, 1)\`;
        }

        progressEl.style.width = (currentProg * 100) + '%';

        sections.forEach((s, i) => {
            const el = document.getElementById('n-' + i);
            const title = el.querySelector('h2');
            const desc = el.querySelector('.desc-wrap');

            const dist = Math.abs(currentProg - s.triggerTime);
            const opacity = Math.max(0, 1 - (dist / CONFIG.window));

            el.style.opacity = opacity;
            el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
            el.style.transform = \`translate3d(0, \${(currentProg - s.triggerTime) * 150}px, 0)\`;

            if(dist < CONFIG.window) {
                title.style.transform = 'translateY(0)';
                desc.style.opacity = '1';
            } else {
                title.style.transform = 'translateY(110%)';
                desc.style.opacity = '0';
            }
        });

        requestAnimationFrame(loop);
    }

    window.addEventListener('scroll', () => {
        const h = document.documentElement.scrollHeight - window.innerHeight;
        targetProg = Math.max(0, Math.min(1, window.scrollY / h));
    }, { passive: true });

    requestAnimationFrame(loop);
})();
</script>
</body>
</html>`;
}

