        .narrative-layer {
            position: absolute; inset: 0; display: flex; padding: 10%;
            opacity: 0; visibility: hidden; pointer-events: none;
        }

        .cinema-title { 
            font-weight: 900; text-transform: uppercase; font-style: italic; 
            font-size: clamp(3rem, 10vw, 7rem); margin: 0; line-height: 0.85; 
        }

        .cinema-body { 
            font-weight: 300; text-transform: uppercase; font-style: italic; 
            opacity: 0.4; font-size: clamp(1rem, 2vw, 1.8rem); margin: 0;
            padding-left: 20px; border-left: 2px solid var(--brand);
        }

        /* YOUR CONTENT SLOT: Add your website here */
        #website-content {
            position: relative;
            z-index: 10;
            width: 100%;
            pointer-events: none;
        }
        .section-spacer { height: 100vh; pointer-events: auto; }
    </style>
</head>
<body>

<div id="infinity-stage">
    <div class="video-wrap" id="v-wrap">
        <video id="v-engine" playsinline muted preload="auto"></video>
        <div class="vignette"></div>
    </div>
    <div id="n-ui"></div>
</div>

<div id="website-content">
    <div class="section-spacer"><!-- Add Your Site Sections Here --></div>
    <div class="section-spacer"></div>
    <div class="section-spacer"></div>
</div>

<script>
(function() {
    const sections = ${sectionsJSON};
    const video = document.getElementById('v-engine');
    const vWrap = document.getElementById('v-wrap');
    const nUI = document.getElementById('n-ui');

    // Replace this with your actual uploaded video URL
    video.src = "YOUR_VIDEO_URL_HERE";

    sections.forEach((s, i) => {
        const wrap = document.createElement('div');
        wrap.className = 'narrative-layer';
        wrap.id = 'n-' + i;
        const align = s.alignment || 'center';
        wrap.style.cssText = align === 'left' ? 'justify-content:flex-start;align-items:center;text-align:left;' : 
                             align === 'right' ? 'justify-content:flex-end;align-items:center;text-align:right;' : 
                             'justify-content:center;align-items:center;text-align:center;';

        wrap.innerHTML = \`
            <div style="max-width: 60rem;">
                <div style="overflow:hidden; margin-bottom: 2rem;">
                    <h2 class="cinema-title" style="transform: translateY(110%); transition: transform 0.8s cubic-bezier(.16,1,.3,1);">\${s.title}</h2>
                </div>
                <div class="d-wrap" style="opacity:0; transition: opacity 1s 0.2s;">
                    <p class="cinema-body">\${s.description}</p>
                </div>
            </div>\`;
        nUI.appendChild(wrap);
    });

    let target = 0, current = 0, last = 0;
    function loop(t) {
        current += (target - current) * 0.08;
        if (video.duration) {
            const tt = video.duration * current;
            if (!video.seeking && (Math.abs(video.currentTime - tt) > 0.05 || (t - last > 40))) {
                video.currentTime = tt; last = t;
            }
            vWrap.style.transform = \`scale3d(\${1.05-(current*0.05)}, \${1.05-(current*0.05)}, 1)\`;
        }

        sections.forEach((s, i) => {
            const el = document.getElementById('n-' + i);
            const dist = Math.abs(current - s.triggerTime);
            const op = Math.max(0, 1 - (dist / 0.08));
            el.style.opacity = op; el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
            el.style.transform = \`translate3d(0, \${(current - s.triggerTime) * 150}px, 0)\`;
            const h = el.querySelector('h2'), d = el.querySelector('.d-wrap');
            if(dist < 0.08) { h.style.transform = 'translateY(0)'; d.style.opacity = '1'; }
            else { h.style.transform = 'translateY(110%)'; d.style.opacity = '0'; }
        });
        requestAnimationFrame(loop);
    }

    window.addEventListener('scroll', () => {
        const h = document.documentElement.scrollHeight - window.innerHeight;
        target = Math.max(0, Math.min(1, window.scrollY / h));
    }, { passive: true });
    requestAnimationFrame(loop);
})();
</script>
</body>
</html>`;
}

