import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for 'Infinity', an AI startup. 
    Analyze the visual details of this video: "${videoDescription}".

    Company Vision: "Infinity builds next-gen intelligent systems that make advanced tech simple, natural, and accessible. No limits."

    Task: Create a 5-section cinematic narrative that uses the specific visuals in the video as metaphors for our vision. 
    For example, if there is a mountain, speak of peaks of intelligence. If there is space, speak of boundless horizons.

    Generate 5 cinematic landing page sections (JSON array).
    - Titles: 1-3 powerful words.
    - Descriptions: 15-25 words that connect the video visuals to the 'Infinity' brand.
    - Trigger times: 0.1 to 0.9.
    - Alignment: Vary based on visual weight.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    // Default brand narrative fallback
    return [
      { title: "INFINITY", description: "Architecting intelligent systems that make advanced technology natural and accessible for every individual.", triggerTime: 0.15, alignment: 'left', vibe: 'cinematic' },
      { title: "NO LIMITS", description: "A core philosophy that technology should have no boundaries, empowering human potential through AI.", triggerTime: 0.35, alignment: 'right', vibe: 'energetic' },
      { title: "INTEGRATION", description: "Seamlessly syncing advanced intelligence into the fabric of daily human life and routine.", triggerTime: 0.55, alignment: 'center', vibe: 'minimal' },
      { title: "FOUNDATIONAL", description: "Building the fundamental core of future-scale innovation during our formative independent stage.", triggerTime: 0.75, alignment: 'left', vibe: 'cinematic' },
      { title: "THE HORIZON", description: "Simple. Natural. Accessible. Defining the next era of human-centered intelligent machines.", triggerTime: 0.95, alignment: 'right', vibe: 'energetic' },
    ];
  }
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import InfinityLogo from './Logo';
import { MousePointer2, Settings2 } from 'lucide-react';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const progressBarRef = useRef<HTMLDivElement>(null);
  const hudSyncRef = useRef<HTMLSpanElement>(null);

  const [hasError, setHasError] = useState(false);
  const [hasScrolled, setHasScrolled] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastSeekTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      const lerp = 0.085;
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;
      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        const diff = Math.abs(video.currentTime - targetTime);
        const timeSinceLastSeek = time - lastSeekTime.current;

        if (!video.seeking && video.readyState >= 2 && (diff > 0.04 || timeSinceLastSeek > 40)) {
          video.currentTime = targetTime;
          lastSeekTime.current = time;
        }

        if (videoLayerRef.current) {
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      if (progressBarRef.current) progressBarRef.current.style.width = `${progress * 100}%`;
      if (hudSyncRef.current) hudSyncRef.current.textContent = `${(progress * 100).toFixed(1)}%`;

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.08;
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < windowSize;

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        const yOffset = (progress - section.triggerTime) * 150;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const title = el.querySelector('h2');
        const body = el.querySelector('.text-wrapper');
        if (title && body) {
          if (isActive) {
            (title as HTMLElement).style.transform = 'translate3d(0, 0, 0)';
            (body as HTMLElement).style.opacity = '1';
          } else {
            (title as HTMLElement).style.transform = 'translate3d(0, 110%, 0)';
            (body as HTMLElement).style.opacity = '0';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (scrollable <= 0) return;
      const prog = Math.max(0, Math.min(1, -rect.top / scrollable));
      targetProgress.current = prog;
      if (prog > 0.01) setHasScrolled(true);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div 
      ref={containerRef} 
      className="relative w-full h-[1200vh] bg-black"
      style={{ isolation: 'isolate' }}
    >
      <div className="sticky top-0 left-0 w-full h-screen h-[100dvh] overflow-hidden bg-black z-0">

        {/* Cinematic Video Layer */}
        <div 
          ref={videoLayerRef}
          className="absolute inset-0 z-[-1] bg-black opacity-70 pointer-events-none"
        >
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center opacity-10">
               <span className="text-[10px] font-black uppercase tracking-[1em]">Engine Halted</span>
            </div>
          )}
        </div>

        {/* Ambient Overlays */}
        <div className="absolute inset-0 z-0 pointer-events-none">
          <div className="absolute top-0 left-0 w-full h-1/3 bg-gradient-to-b from-black to-transparent" />
          <div className="absolute bottom-0 left-0 w-full h-1/3 bg-gradient-to-t from-black to-transparent" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_40%,rgba(0,0,0,0.8)_160%)]" />
        </div>

        {/* Narrative System */}
        <div className="absolute inset-0 z-10 flex pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex px-10 md:px-32 py-20 ${
                section.alignment === 'left' ? 'justify-start items-center text-left' : 
