import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string, brandName: string = "Narrative"): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for a brand called '${brandName}'. 
    Analyze this video: "${videoDescription}".

    The brand identity is: "Next-generation, high-end, and cinematic. Advanced technology that feels natural."

    Task: Create a 5-section narrative that connects the visuals in this specific video to the brand '${brandName}'.

    Generate 5 cinematic landing page sections (JSON array).
    - Titles: 1-3 powerful words.
    - Descriptions: 15-25 words.
    - Trigger times: 0.1 to 0.9.
    - Alignment: Vary (left, right, center).`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    // Generic high-end template if AI fails or no key
    return [
      { title: brandName.toUpperCase(), description: "A cinematic experience tailored to the rhythm of motion and visual depth.", triggerTime: 0.15, alignment: 'left', vibe: 'cinematic' },
      { title: "MOMENTUM", description: "Seamlessly synchronized transitions that bridge the gap between digital and physical space.", triggerTime: 0.35, alignment: 'right', vibe: 'energetic' },
      { title: "PERSPECTIVE", description: "Every frame tells a story of precision, architected for high-end digital environments.", triggerTime: 0.55, alignment: 'center', vibe: 'minimal' },
      { title: "HARMONY", description: "The perfect intersection of human-centric design and technological capability.", triggerTime: 0.75, alignment: 'left', vibe: 'cinematic' },
      { title: "THE FINALE", description: "Elevating the digital landscape through continuous innovation and visual excellence.", triggerTime: 0.95, alignment: 'right', vibe: 'energetic' },
    ];
  }
}

import { ScrollSection } from "../types";

export function generateSnippetCode(sections: ScrollSection[], videoUrl: string, sensitivity: number = 0.08): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!-- 1. PASTE THIS AT THE END OF YOUR BODY TAG -->
<div id="scroll-engine-root">
    <div id="engine-fixed-stage">
        <div class="video-layer" id="v-layer">
            <video id="v-element" playsinline muted preload="auto" src="${videoUrl}"></video>
            <div class="v-vignette"></div>
        </div>
        <div id="narrative-ui"></div>
        <div id="engine-progress-bar"><div id="progress-fill"></div></div>
    </div>
</div>

<style>
/* 2. PASTE THIS INTO YOUR CSS */
#scroll-engine-root {
    position: fixed;
    inset: 0;
    z-index: -1; /* Sits behind your content */
    background: #000;
    pointer-events: none;
    overflow: hidden;
}
#engine-fixed-stage { position: absolute; inset: 0; }
.video-layer { position: absolute; inset: 0; opacity: 0.7; transform-origin: center; }
#v-element { width: 100%; height: 100%; object-fit: cover; }
.v-vignette { position: absolute; inset: 0; background: radial-gradient(circle, transparent 30%, rgba(0,0,0,0.8) 150%); }
#engine-progress-bar { position: absolute; bottom: 0; left: 0; width: 100%; height: 2px; background: rgba(255,255,255,0.05); }
#progress-fill { height: 100%; width: 0%; background: #4f46e5; transition: width 0.1s linear; }
.narrative-item {
    position: absolute; inset: 0; display: flex; padding: 10%;
    opacity: 0; visibility: hidden; pointer-events: none;
    transition: filter 0.5s ease;
}
.n-title { font-size: 8vw; font-weight: 900; font-style: italic; text-transform: uppercase; margin: 0; line-height: 0.8; color: #fff; }
.n-body { font-size: 1.2rem; font-weight: 300; font-style: italic; text-transform: uppercase; margin-top: 20px; color: rgba(255,255,255,0.5); padding-left: 20px; border-left: 2px solid #4f46e5; }
</style>

<script>
/* 3. PASTE THIS INTO YOUR SCRIPT TAG */
(function() {
    const sections = ${sectionsJSON};
    const video = document.getElementById('v-element');
    const vLayer = document.getElementById('v-layer');
    const nUI = document.getElementById('narrative-ui');
    const fill = document.getElementById('progress-fill');

    sections.forEach((s, i) => {
        const item = document.createElement('div');
        item.className = 'narrative-item';
        item.id = 'n-item-' + i;
        const align = s.alignment || 'left';
        item.style.cssText = \`justify-content:\${align === 'left' ? 'flex-start' : align === 'right' ? 'flex-end' : 'center'};\`;
        item.style.alignItems = 'center';
        item.style.textAlign = align;

        item.innerHTML = \`
            <div style="max-width: 800px;">
                <h2 class="n-title" style="transform: translateY(100%); transition: transform 0.8s cubic-bezier(.16,1,.3,1);">\${s.title}</h2>
                <div class="n-body-wrap" style="opacity:0; transition: opacity 1s 0.2s;"><p class="n-body">\${s.description}</p></div>
            </div>\`;
        nUI.appendChild(item);
    });

    let target = 0, current = 0;
    function animate() {
        current += (target - current) * ${sensitivity};
        if (video.duration) {
            video.currentTime = video.duration * current;
            fill.style.width = (current * 100) + '%';
            vLayer.style.transform = \`scale3d(\${1.05 - (current * 0.05)}, \${1.05 - (current * 0.05)}, 1)\`;
        }
        sections.forEach((s, i) => {
            const el = document.getElementById('n-item-' + i);
            const dist = Math.abs(current - s.triggerTime);
            const op = Math.max(0, 1 - (dist / 0.1));
            el.style.opacity = op;
            el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
            el.style.transform = \`translate3d(0, \${(current - s.triggerTime) * 150}px, 0)\`;
            const h = el.querySelector('.n-title'), b = el.querySelector('.n-body-wrap');
            if(dist < 0.1) { h.style.transform = 'translateY(0)'; b.style.opacity = '1'; el.style.filter = 'blur(0px)'; }
            else { h.style.transform = 'translateY(100%)'; b.style.opacity = '0'; el.style.filter = 'blur(10px)'; }
        });
        requestAnimationFrame(animate);
    }
    window.addEventListener('scroll', () => {
        const h = document.documentElement.scrollHeight - window.innerHeight;
        target = Math.max(0, Math.min(1, window.scrollY / h));
    }, { passive: true });
    requestAnimationFrame(animate);
})();
</script>`;
}

