           <div className={`p-6 rounded-3xl backdrop-blur-3xl border shadow-2xl ${error ? 'bg-red-950/60 border-red-500/30 text-red-100' : 'bg-indigo-950/60 border-indigo-500/30 text-indigo-100'} flex items-center gap-6`}>
              {error ? <AlertCircle size={20} className="text-red-400" /> : <Zap size={20} className="text-indigo-400 animate-pulse" />}
              <span className="text-[11px] font-black uppercase tracking-[0.4em] italic">{error || systemNote}</span>
              <button onClick={() => {setError(null); setSystemNote(null)}} className="opacity-30 hover:opacity-100 transition-opacity"><X size={18}/></button>
           </div>
        </div>
      )}

      {/* Noise Texture Overlay */}
      <div className="fixed inset-0 pointer-events-none z-[9999] opacity-[0.03] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay" />
    </div>
  );
};

