import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string, brandName: string = "Narrative"): Promise<ScrollSection[]> {
  const brand = brandName.toUpperCase();

  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for a brand called '${brandName}'. 
    Analyze this video: "${videoDescription}".

    The brand identity is: "Next-generation, high-end, and cinematic. Advanced technology that feels natural."

    Task: Create a 5-section narrative that connects the visuals in this specific video to the brand '${brandName}'.

    Generate 5 cinematic landing page sections (JSON array).
    - Titles: 1-3 powerful words.
    - Descriptions: 15-25 words.
    - Trigger times: 0.1 to 0.9.
    - Alignment: Vary (left, right, center).`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    // Blueprint Synthesis - High-end template for the user's specific brand
    return [
      { 
        title: brand, 
        description: `A cinematic architectural experience tailored for ${brandName}, defined by motion and visual depth.`, 
        triggerTime: 0.15, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "SYNCHRONY", 
        description: `Bridging the gap between digital and physical space with transitions exclusive to the ${brandName} ecosystem.`, 
        triggerTime: 0.35, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
      { 
        title: "DIMENSION", 
        description: "Every frame is a blueprint for precision, architected for high-performance digital environments.", 
        triggerTime: 0.55, 
        alignment: 'center', 
        vibe: 'minimal' 
      },
      { 
        title: "FOUNDATION", 
        description: `The intersection of human-centric design and the fundamental core of ${brandName}'s capability.`, 
        triggerTime: 0.75, 
        alignment: 'left', 
        vibe: 'cinematic' 
      },
      { 
        title: "THE HORIZON", 
        description: `Elevating the landscape through continuous innovation and the visual excellence of ${brandName}.`, 
        triggerTime: 0.95, 
        alignment: 'right', 
        vibe: 'energetic' 
      },
    ];
  }
}

