const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [systemNote, setSystemNote] = useState<string | null>(null);

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);
    setSystemNote(null);

    try {
      // Small delay to simulate synthesis if offline for better UX
      if (!process.env.API_KEY) {
        await new Promise(resolve => setTimeout(resolve, 1500));
        setSystemNote("Blueprint Engine Active (No API Key)");
      }

      const description = `A cinematic video titled "${title}". ${metadata}.`;
      const storySections = await generateVideoStory(description, state.brandName);

      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`ERR: ${err.message || 'Synthesis failed.'}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const updateSection = (index: number, updated: ScrollSection) => {
    const next = [...state.sections];
    next[index] = updated;
    setState(prev => ({ ...prev, sections: next }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setSystemNote("Component Logic Copied");
    setTimeout(() => setSystemNote(null), 3000);
  };

  const resetAll = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  const snippet = state.url ? generateSnippetCode(state.sections, state.url, state.sensitivity) : "";

  return (
    <div className="min-h-screen bg-black text-white selection:bg-indigo-600 antialiased font-sans">

