                <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase tracking-widest text-indigo-500 italic">Studio Engine</span>
                  <span className="text-[8px] font-bold text-white/30 uppercase tracking-[0.3em] mt-1">
                    {process.env.API_KEY ? "AI Integration Active" : "Blueprint Mode Active"}
                  </span>
                </div>
                <button 
                  onClick={() => setIsEditMode(!isEditMode)}
                  className={`p-3 rounded-2xl transition-all ${isEditMode ? 'bg-indigo-600 shadow-[0_0_20px_rgba(79,70,229,0.4)]' : 'bg-white/5 hover:bg-white/10'}`}
                >
                  {isEditMode ? <Eye size={16} /> : <Edit3 size={16} />}
                </button>
             </div>

             <div className="space-y-6">
               <div className="space-y-3">
                 <div className="flex justify-between text-[9px] font-black text-white/40 uppercase tracking-[0.2em]">
                    <span>Fluidity</span>
                    <span>{(state.sensitivity * 100).toFixed(0)}%</span>
                 </div>
                 <input 
                   type="range" min="0.01" max="0.2" step="0.01"
                   value={state.sensitivity}
                   onChange={(e) => setState({...state, sensitivity: parseFloat(e.target.value)})}
                   className="w-full accent-indigo-500 bg-white/10 h-[2px] rounded-full appearance-none cursor-pointer"
                 />
               </div>

               <div className="flex flex-col gap-3">
                  <button 
                    onClick={() => setShowExportModal(true)} 
                    className="w-full flex items-center justify-center gap-4 py-5 bg-white text-black rounded-3xl font-black text-[11px] uppercase tracking-[0.3em] hover:bg-indigo-600 hover:text-white transition-all shadow-xl"
                  >
                    <Code size={14} /> Get Snippet
                  </button>
                  <button 
                    onClick={resetAll}
                    className="w-full flex items-center justify-center gap-4 py-4 border border-white/5 text-white/30 rounded-3xl font-black text-[9px] uppercase tracking-[0.3em] hover:bg-white/5 hover:text-white transition-all"
                  >
                    <Trash2 size={12} /> Reset System
                  </button>
               </div>
             </div>
          </div>
        </div>
