import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [systemNote, setSystemNote] = useState<string | null>(null);

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);
    setSystemNote(null);

    try {
      if (!process.env.API_KEY) {
        await new Promise(resolve => setTimeout(resolve, 1000));
        setSystemNote("Blueprint Mode: Active");
      }

      const description = `A cinematic video titled "${title}". ${metadata}.`;
      const storySections = await generateVideoStory(description, state.brandName);

      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`ERR: ${err.message || 'Synthesis failed.'}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const updateSection = (index: number, updated: ScrollSection) => {
    const next = [...state.sections];
    next[index] = updated;
    setState(prev => ({ ...prev, sections: next }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setSystemNote("Blueprint Copied");
    setTimeout(() => setSystemNote(null), 2000);
  };

  const resetAll = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  const snippet = state.url ? generateSnippetCode(state.sections, state.url, state.sensitivity) : "";

  return (
    <div className="min-h-screen bg-black text-white selection:bg-indigo-600 antialiased font-sans">

      {/* Studio Control HUD */}
      {state.url && !state.isAnalyzing && (
        <div className="fixed bottom-10 left-10 z-[200] pointer-events-none">
          <div className="pointer-events-auto p-6 bg-black/80 border border-white/10 rounded-[2.5rem] backdrop-blur-3xl flex flex-col gap-6 w-72 shadow-2xl animate-in slide-in-from-left-4 duration-300">
             <div className="flex items-center justify-between">
                <div className="flex flex-col">
                  <span className="text-[9px] font-black uppercase tracking-widest text-indigo-500 italic">Studio Engine</span>
                  <span className="text-[7px] font-bold text-white/30 uppercase tracking-[0.2em] mt-1">
                    {process.env.API_KEY ? "AI Link Active" : "Blueprint Mode"}
                  </span>
                </div>
                <button 
                  onClick={() => setIsEditMode(!isEditMode)}
                  className={`p-3 rounded-2xl transition-all duration-200 ${isEditMode ? 'bg-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.4)]' : 'bg-white/5 hover:bg-white/10'}`}
                >
                  {isEditMode ? <Eye size={14} /> : <Edit3 size={14} />}
                </button>
             </div>

             <div className="space-y-4">
               <div className="space-y-2">
                 <div className="flex justify-between text-[8px] font-black text-white/40 uppercase tracking-[0.2em]">
                    <span>Fluidity</span>
                    <span>{(state.sensitivity * 100).toFixed(0)}%</span>
                 </div>
                 <input 
                   type="range" min="0.01" max="0.2" step="0.01"
                   value={state.sensitivity}
                   onChange={(e) => setState({...state, sensitivity: parseFloat(e.target.value)})}
                   className="w-full accent-indigo-500 bg-white/10 h-[1px] rounded-full appearance-none cursor-pointer"
                 />
               </div>

               <div className="flex flex-col gap-2">
                  <button 
                    onClick={() => setShowExportModal(true)} 
                    className="w-full flex items-center justify-center gap-3 py-4 bg-white text-black rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-xl active:scale-95 duration-200"
                  >
                    <Code size={12} /> Get Snippet
                  </button>
                  <button 
                    onClick={resetAll}
                    className="w-full flex items-center justify-center gap-3 py-3 border border-white/5 text-white/20 rounded-2xl font-black text-[8px] uppercase tracking-[0.2em] hover:bg-white/5 hover:text-white transition-all active:scale-95 duration-200"
                  >
                    <Trash2 size={10} /> Reset
                  </button>
               </div>
             </div>
          </div>
        </div>
      )}

      {/* Primary Navigation */}
      <nav className="fixed top-0 left-0 w-full z-[100] px-10 md:px-24 py-10 flex justify-between items-center pointer-events-none">
        <div className="flex items-center gap-6 cursor-pointer group pointer-events-auto" onClick={resetAll}>
          <InfinityLogo size={40} className="text-white transition-transform group-hover:scale-105 duration-300" />
          <div className="flex flex-col">
            <span className="font-black text-2xl tracking-[0.2em] uppercase italic leading-none">{state.brandName}</span>
            <span className="text-[8px] font-black text-indigo-500 tracking-[0.6em] uppercase mt-1 opacity-50">Narrative Archive</span>
          </div>
        </div>
      </nav>

      {/* Export Snippet Modal - Optimized interaction */}
      {showExportModal && (
        <div 
          className="fixed inset-0 z-[1000] flex items-center justify-center p-6 md:p-12 bg-black/90 backdrop-blur-xl animate-in fade-in duration-300"
          onClick={() => setShowExportModal(false)}
        >
          <div 
            className="w-full max-w-5xl bg-neutral-900 border border-white/10 rounded-[3rem] p-10 md:p-16 flex flex-col gap-8 shadow-[0_0_100px_rgba(0,0,0,0.8)] relative animate-in zoom-in-95 duration-300"
            onClick={(e) => e.stopPropagation()}
          >
            <button 
              onClick={() => setShowExportModal(false)} 
              className="absolute top-8 right-8 p-4 bg-white/5 hover:bg-white/10 text-white/40 hover:text-white rounded-full transition-all duration-200"
            >
              <X size={24}/>
            </button>

            <div className="space-y-3">
              <h2 className="text-4xl font-black italic uppercase tracking-tighter">Logic Assembly</h2>
              <p className="text-[10px] text-indigo-500 uppercase tracking-[0.5em] italic font-black opacity-70">Architecture Synced for {state.brandName}</p>
            </div>

            <div className="flex-1 min-h-[300px] overflow-auto bg-black/40 p-8 rounded-[2rem] border border-white/5 font-mono text-[11px] text-indigo-100/40 leading-relaxed whitespace-pre group relative">
              <button 
                onClick={() => copyToClipboard(snippet)}
                className="absolute top-6 right-6 px-6 py-4 bg-white text-black rounded-xl hover:bg-indigo-600 hover:text-white transition-all flex items-center gap-3 font-sans text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-95 duration-200"
              >
                <Copy size={14} /> Copy Blueprint
              </button>
              {snippet}
            </div>

            <div className="flex flex-col md:flex-row items-center justify-between gap-6">
              <div className="flex gap-4">
                <div className="px-5 py-3 bg-white/[0.03] rounded-xl border border-white/5 text-[9px] font-bold text-white/30 uppercase tracking-widest">Fixed Background</div>
                <div className="px-5 py-3 bg-white/[0.03] rounded-xl border border-white/5 text-[9px] font-bold text-white/30 uppercase tracking-widest">No Dependencies</div>
              </div>
              <button 
                onClick={() => setShowExportModal(false)} 
                className="px-10 py-4 border border-white/10 text-white/40 font-black text-[10px] uppercase tracking-[0.3em] rounded-2xl hover:bg-white/5 hover:text-white transition-all active:scale-95 duration-200"
              >
                Dismiss
              </button>
            </div>
          </div>
        </div>
      )}

      {!state.url ? (
        <main className="relative min-h-screen flex flex-col items-center px-10 pt-[20vh] pb-32">
          {/* Ambient Lighting */}
          <div className="absolute inset-0 overflow-hidden pointer-events-none opacity-30">
             <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(circle_at_50%_40%,rgba(79,70,229,0.1),transparent_60%)]" />
          </div>

          <div className="text-center mb-20 max-w-7xl relative z-10 w-full animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col items-center gap-8 mb-12">
               <input 
                 type="text" 
                 value={state.brandName} 
                 onChange={(e) => setState({...state, brandName: e.target.value.toUpperCase()})}
                 placeholder="NAME YOUR BRAND"
                 className="bg-transparent border-b border-white/5 text-center text-[clamp(2.5rem,10vw,8rem)] font-black tracking-[-0.03em] uppercase italic focus:border-indigo-500/50 outline-none transition-all placeholder:text-white/5 text-white/90"
               />
               <div className="flex items-center gap-6 opacity-30">
                  <div className="h-[1px] w-16 bg-gradient-to-r from-transparent to-white" />
                  <span className="text-[10px] font-black text-white tracking-[1em] uppercase italic">Obsidian Core</span>
                  <div className="h-[1px] w-16 bg-gradient-to-l from-transparent to-white" />
               </div>
            </div>
            <p className="text-[11px] md:text-sm text-white/20 font-bold max-w-lg mx-auto leading-relaxed tracking-[0.4em] uppercase italic border-l-2 border-indigo-600/30 pl-8 text-left">
              Modular background scroll engines architected for premium digital environments.
            </p>
          </div>

          <div className="w-full relative z-10 animate-in fade-in slide-in-from-bottom-8 duration-700 delay-100">
            <FileUpload 
              onFileSelect={(file) => analyzeVideo(URL.createObjectURL(file), file.name, file.type)} 
              onSampleSelect={(url, name) => analyzeVideo(url, name, 'System Logic')}
              isAnalyzing={state.isAnalyzing} 
            />
          </div>
        </main>
      ) : (
        <section className="relative">
          <VideoScroller 
            videoUrl={state.url} 
            sections={state.sections} 
            isEditMode={isEditMode}
            onUpdateSection={updateSection}
          />

          <footer className="relative min-h-[50vh] flex flex-col items-center justify-center bg-black border-t border-white/5 z-10 overflow-hidden">
            <div className="text-center z-10 px-10">
              <h2 className="text-[clamp(2rem,6vw,5rem)] font-black tracking-tighter mb-12 italic uppercase text-white/5 select-none">ASSEMBLY READY.</h2>
              <div className="flex flex-col md:flex-row gap-6 justify-center">
                <button onClick={() => setShowExportModal(true)} className="px-16 py-6 bg-white text-black font-black text-[11px] uppercase tracking-[0.3em] rounded-full hover:bg-indigo-600 hover:text-white transition-all shadow-xl active:scale-95 duration-200">
                   Get Snippet
                </button>
                <button onClick={resetAll} className="px-16 py-6 border border-white/10 text-white/30 font-black text-[11px] uppercase tracking-[0.3em] rounded-full hover:bg-white/5 hover:text-white transition-all active:scale-95 duration-200">
                  New Project
                </button>
              </div>
            </div>
          </footer>
        </section>
      )}

      {/* Alert System - Accelerated */}
      {(systemNote || error) && (
        <div className="fixed bottom-8 right-8 z-[500] animate-in slide-in-from-right-8 duration-300">
           <div className={`p-5 rounded-2xl backdrop-blur-3xl border shadow-2xl ${error ? 'bg-red-950/60 border-red-500/30 text-red-100' : 'bg-indigo-950/60 border-indigo-500/30 text-indigo-100'} flex items-center gap-5`}>
              {error ? <AlertCircle size={18} className="text-red-400" /> : <Zap size={18} className="text-indigo-400 animate-pulse" />}
              <span className="text-[10px] font-black uppercase tracking-[0.3em] italic">{error || systemNote}</span>
              <button onClick={() => {setError(null); setSystemNote(null)}} className="opacity-30 hover:opacity-100 transition-opacity"><X size={16}/></button>
           </div>
        </div>
      )}

      <div className="fixed inset-0 pointer-events-none z-[9999] opacity-[0.02] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay" />
    </div>
  );
};

export default App;

