import React, { useState, useEffect } from 'react';
import { Code, Download, Zap, AlertCircle, X, Edit3, Eye, Copy, Trash2, Check, Sparkles, ArrowRight } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [systemNote, setSystemNote] = useState<string | null>(null);

  useEffect(() => {
    if (showExportModal) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [showExportModal]);

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);
    setSystemNote(null);

    try {
      if (!process.env.API_KEY) {
        await new Promise(resolve => setTimeout(resolve, 1200));
        setSystemNote("Drafting Cinematic Narrative...");
      }
      const storySections = await generateVideoStory(`Video: ${title}. ${metadata}.`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`Analysis Error: ${err.message || 'System failed to synthesize visuals.'}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const updateSection = (index: number, updated: ScrollSection) => {
    const next = [...state.sections];
    next[index] = updated;
    setState(prev => ({ ...prev, sections: next }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const downloadSnippet = () => {
    const snippet = generateSnippetCode(state.sections, state.url || "", state.sensitivity);
    const blob = new Blob([snippet], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.brandName.toLowerCase()}-scroller.html`;
    a.click();
    URL.revokeObjectURL(url);
    setSystemNote("Template Exported Successfully");
  };

  const resetAll = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  const snippet = state.url ? generateSnippetCode(state.sections, state.url, state.sensitivity) : "";

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-indigo-500/30 antialiased font-sans overflow-x-hidden">

      {/* Dynamic Background Noise Layer */}
      <div className="fixed inset-0 pointer-events-none z-0 opacity-[0.03] bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />

      {/* Floating Control Hub - Modern Glass Interface */}
      {state.url && !state.isAnalyzing && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[200] pointer-events-none w-full max-w-xl px-6">
          <div className="pointer-events-auto p-2 bg-white/[0.03] border border-white/10 rounded-full backdrop-blur-2xl flex items-center gap-2 shadow-2xl animate-in slide-in-from-bottom-8 duration-500 ease-out">
             <div className="flex items-center gap-4 px-6 py-2 border-r border-white/5">
                <InfinityLogo size={24} className="text-white/80" />
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-white/40">Studio</span>
                  <span className="text-[11px] font-black uppercase text-indigo-400">Live</span>
                </div>
             </div>

             <div className="flex-1 flex items-center justify-center gap-2">
                <button 
                  onClick={() => setIsEditMode(!isEditMode)}
                  className={`flex items-center gap-2 px-5 py-3 rounded-full transition-all duration-300 ${isEditMode ? 'bg-indigo-600 text-white' : 'hover:bg-white/5 text-white/60 hover:text-white'}`}
                >
                  {isEditMode ? <Layout size={14} /> : <Edit3 size={14} />}
                  <span className="text-[10px] font-bold uppercase tracking-widest">{isEditMode ? 'Finish' : 'Edit'}</span>
                </button>
                <button 
                  onClick={() => setShowExportModal(true)} 
                  className="flex items-center gap-2 px-6 py-3 bg-white text-black rounded-full hover:bg-indigo-50 transition-all group"
                >
                  <Code size={14} className="group-hover:scale-110 transition-transform" />
                  <span className="text-[10px] font-black uppercase tracking-widest">Export Code</span>
                </button>
             </div>

             <button 
                onClick={resetAll}
                className="p-3 text-white/20 hover:text-white transition-colors"
                title="Reset Workspace"
              >
                <Trash2 size={16} />
              </button>
          </div>
        </div>
      )}

      {/* Sophisticated Header Navigation */}
      <nav className="fixed top-0 left-0 w-full z-[100] px-8 md:px-16 py-10 flex justify-between items-center pointer-events-none">
        <div className="flex items-center gap-5 cursor-pointer group pointer-events-auto" onClick={resetAll}>
          <div className="w-10 h-10 bg-white flex items-center justify-center rounded-xl rotate-3 group-hover:rotate-0 transition-all duration-500">
             <InfinityLogo size={24} className="text-black" />
          </div>
          <div className="flex flex-col">
            <span className="font-bold text-xl tracking-tight leading-none text-white/90">{state.brandName}</span>
            <span className="text-[8px] font-bold text-indigo-400 uppercase tracking-[0.4em] mt-1">Narrative Engine</span>
          </div>
        </div>
        <div className="hidden md:flex items-center gap-8 pointer-events-auto">
           <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.2em] hover:text-white transition-colors cursor-pointer">Showcase</span>
           <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.2em] hover:text-white transition-colors cursor-pointer">Documentation</span>
           <button onClick={() => window.open('https://github.com', '_blank')} className="px-5 py-2 bg-white/5 border border-white/10 rounded-full text-[10px] font-bold uppercase tracking-widest hover:bg-white/10 transition-all">Github</button>
        </div>
      </nav>

      {/* Export Sheet - Clean & High Contrast */}
      {showExportModal && (
        <div 
          className="fixed inset-0 z-[1000] flex items-center justify-center p-6 bg-black/80 backdrop-blur-sm animate-in fade-in duration-500"
          onClick={() => setShowExportModal(false)}
        >
          <div 
            className="w-full max-w-5xl max-h-[85vh] bg-[#0c0c0c] border border-white/10 rounded-[2rem] flex flex-col relative animate-in zoom-in-95 duration-500 overflow-hidden shadow-2xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-center justify-between px-10 py-8 border-b border-white/5">
              <div className="flex items-center gap-4">
                <div className="w-8 h-8 rounded-lg bg-indigo-500 flex items-center justify-center">
                   <Code size={16} className="text-white" />
                </div>
                <div>
                   <h2 className="text-lg font-bold tracking-tight">Export Template</h2>
                   <p className="text-[10px] text-white/40 uppercase tracking-widest font-bold">Generated Logic for {state.brandName}</p>
                </div>
              </div>
              <button 
                onClick={() => setShowExportModal(false)} 
                className="p-2 hover:bg-white/5 text-white/40 hover:text-white rounded-full transition-all"
              >
                <X size={20}/>
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-10 font-mono text-[13px] text-white/70 leading-relaxed whitespace-pre custom-scrollbar bg-black/40">
              {snippet}
            </div>

            <div className="px-10 py-8 border-t border-white/5 flex items-center justify-between bg-black/40">
               <div className="flex gap-4">
                  <div className="flex items-center gap-2 text-[9px] font-bold text-white/30 uppercase tracking-widest">
                     <Sparkles size={12} className="text-indigo-500" /> Auto-Optimized
                  </div>
               </div>
               <div className="flex gap-4">
                 <button 
                  onClick={() => copyToClipboard(snippet)}
                  className={`px-8 py-3 rounded-full transition-all flex items-center gap-3 text-[11px] font-bold uppercase tracking-widest ${
                    copied ? 'bg-indigo-600 text-white' : 'bg-white text-black hover:bg-indigo-50'
                  }`}
                >
                  {copied ? <Check size={14} /> : <Copy size={14} />}
                  {copied ? 'Copied' : 'Copy Code'}
                </button>
                <button 
                  onClick={downloadSnippet}
                  className="px-8 py-3 bg-white/5 text-white/80 hover:text-white hover:bg-white/10 rounded-full border border-white/10 transition-all flex items-center gap-3 text-[11px] font-bold uppercase tracking-widest"
                >
                  <Download size={14} /> Download
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

