import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      lastTime.current = time;

      const lerp = 0.08; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.05) {
          video.currentTime = targetTime;
        }

        if (videoLayerRef.current) {
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.1;
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < windowSize;

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const blurAmount = isActive ? 0 : Math.min(8, (distance - windowSize) * 80);
        el.style.filter = `blur(${blurAmount}px)`;

        const h2 = el.querySelector('h2');
        const textWrapper = el.querySelector('.text-wrapper');

        if (h2 && textWrapper) {
          if (isActive) {
            (h2 as HTMLElement).style.transform = 'translateY(0)';
            (h2 as HTMLElement).style.opacity = '1';
            (textWrapper as HTMLElement).style.opacity = '1';
            (textWrapper as HTMLElement).style.transform = 'translateY(0)';
          } else {
            (h2 as HTMLElement).style.transform = 'translateY(40px)';
            (h2 as HTMLElement).style.opacity = '0';
            (textWrapper as HTMLElement).style.opacity = '0';
            (textWrapper as HTMLElement).style.transform = 'translateY(20px)';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (scrollable <= 0) return;
      targetProgress.current = Math.max(0, Math.min(1, -rect.top / scrollable));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1200vh] bg-[#050505]">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden bg-black z-0">

        {/* Cinematic Video Layer */}
        <div ref={videoLayerRef} className="absolute inset-0 z-[-1] opacity-70">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/10 uppercase tracking-widest font-black">Media Engine Error</div>
          )}
          {/* Subtle Gradient Overlays for Depth */}
          <div className="absolute inset-0 bg-gradient-to-b from-[#050505] via-transparent to-[#050505] opacity-80" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,#050505_120%)] opacity-60" />
        </div>

        {/* Narrative UI Layer */}
        <div className="absolute inset-0 z-10 flex flex-col pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex px-8 md:px-24 py-20 ${
                section.alignment === 'left' ? 'justify-start items-center text-left' : 
                section.alignment === 'right' ? 'justify-end items-center text-right' : 
                'justify-center items-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-4xl w-full">
                <div className="overflow-hidden mb-8">
                   {isEditMode ? (
                     <input 
                       className="bg-white/5 border border-white/10 px-6 py-4 rounded-2xl outline-none text-[clamp(2.5rem,8vw,6rem)] font-bold tracking-tight pointer-events-auto text-white w-full backdrop-blur-md"
                       value={section.title}
                       onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                     />
                   ) : (
                     <h2 className="text-[clamp(3rem,8vw,6rem)] font-bold tracking-tight leading-none text-white transition-all duration-1000 ease-out translate-y-20 opacity-0">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="text-wrapper transition-all duration-1000 delay-200 translate-y-10 opacity-0">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/5 border border-white/10 px-6 py-4 rounded-2xl outline-none text-lg text-white/60 font-medium tracking-tight max-w-xl w-full h-32 resize-none pointer-events-auto backdrop-blur-md"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className="text-lg md:text-2xl text-white/40 font-medium leading-relaxed max-w-2xl mx-auto md:mx-0">
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

