import { Code, Download, Zap, AlertCircle, X, Edit3, Eye, Copy, Trash2, Check, Sparkles, ArrowRight, Layout } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [systemNote, setSystemNote] = useState<string | null>(null);

  useEffect(() => {
    if (showExportModal) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [showExportModal]);

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);
    setSystemNote(null);

    try {
      if (!process.env.API_KEY) {
        await new Promise(resolve => setTimeout(resolve, 1200));
        setSystemNote("Drafting Cinematic Narrative...");
      }
      const storySections = await generateVideoStory(`Video: ${title}. ${metadata}.`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`Analysis Error: ${err.message || 'System failed to synthesize visuals.'}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const updateSection = (index: number, updated: ScrollSection) => {
    const next = [...state.sections];
    next[index] = updated;
    setState(prev => ({ ...prev, sections: next }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const downloadSnippet = () => {
    const snippet = generateSnippetCode(state.sections, state.url || "", state.sensitivity);
    const blob = new Blob([snippet], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${state.brandName.toLowerCase()}-scroller.html`;
    a.click();
    URL.revokeObjectURL(url);
    setSystemNote("Template Exported Successfully");
  };

  const resetAll = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  const snippet = state.url ? generateSnippetCode(state.sections, state.url, state.sensitivity) : "";

  return (
    <div className="min-h-screen bg-[#050505] text-white selection:bg-indigo-500/30 antialiased font-sans overflow-x-hidden">

