                </button>
                <button 
                  onClick={() => setShowExportModal(true)} 
                  className="flex items-center gap-2 px-6 py-3 bg-white text-black rounded-full hover:bg-indigo-50 transition-all group"
                >
                  <Code size={14} className="group-hover:scale-110 transition-transform" />
                  <span className="text-[10px] font-black uppercase tracking-widest">Export Code</span>
                </button>
