import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const lastTime = useRef(0);

  useEffect(() => {
    const animate = (time: number) => {
      lastTime.current = time;

      // Smoother LERP for professional feeling
      const lerp = 0.06; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        // Direct scrub without browser buffering interruptions
        if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.05) {
          video.currentTime = targetTime;
        }

        if (videoLayerRef.current) {
          const zoom = 1.02 - (progress * 0.02);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.08; // Narrower trigger window for snappier transitions
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < (windowSize * 0.8);

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Vertical narrative flow
        const yOffset = (progress - section.triggerTime) * 200;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const h2 = el.querySelector('h2');
        const p = el.querySelector('p');

        if (h2 && p) {
          if (isActive) {
            (h2 as HTMLElement).style.opacity = '1';
            (h2 as HTMLElement).style.transform = 'translateY(0) scale(1)';
            (p as HTMLElement).style.opacity = '1';
            (p as HTMLElement).style.transform = 'translateY(0)';
          } else {
            (h2 as HTMLElement).style.opacity = '0';
            (h2 as HTMLElement).style.transform = `translateY(${progress > section.triggerTime ? '-20px' : '20px'}) scale(0.95)`;
            (p as HTMLElement).style.opacity = '0';
            (p as HTMLElement).style.transform = 'translateY(10px)';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollableHeight = containerRef.current.offsetHeight - window.innerHeight;

      // Corrected targetProgress mapping to ensure video stays in place
      if (scrollableHeight > 0) {
        const p = -rect.top / scrollableHeight;
        targetProgress.current = Math.max(0, Math.min(1, p));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1000vh] bg-black">
      {/* FIXED STAGE: This element handles the 'Fixed' position correctly relative to scroll progress */}
      <div className="fixed inset-0 w-full h-full overflow-hidden pointer-events-none z-0">

        {/* Cinematic Video Layer */}
        <div ref={videoLayerRef} className="absolute inset-0 z-[-1] opacity-50 scale-[1.02]">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/10 uppercase tracking-widest font-black">Video Render Error</div>
          )}

          {/* Depth Grading */}
          <div className="absolute inset-0 bg-gradient-to-b from-black via-transparent to-black opacity-80" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,black_140%)]" />
        </div>

        {/* Narrative UI Overlay */}
        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center px-10 md:px-24">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-4xl w-full">
                <div className="mb-6">
                   {isEditMode ? (
                     <input 
                       className="bg-white/5 border border-white/10 px-6 py-4 rounded-full outline-none text-4xl md:text-6xl font-black tracking-tighter pointer-events-auto text-white w-full backdrop-blur-xl"
                       value={section.title}
                       onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                     />
                   ) : (
                     <h2 className="text-5xl md:text-8xl font-black tracking-tighter text-white transition-all duration-700 ease-out opacity-0 translate-y-10 scale-95">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="pointer-events-auto">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/5 border border-white/10 px-8 py-6 rounded-3xl outline-none text-sm text-white/50 font-bold tracking-widest uppercase max-w-xl w-full h-32 resize-none backdrop-blur-xl"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className="text-xs md:text-sm text-white/40 font-black tracking-[0.4em] uppercase leading-loose max-w-lg transition-all duration-1000 delay-100 opacity-0 translate-y-10">
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

