import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      // Viscous Lerp for professional feeling
      const lerp = 0.05; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        // Directly drive video playhead
        if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.04) {
          video.currentTime = targetTime;
        }

        // Subtle Parallax Zoom
        if (videoLayerRef.current) {
          const zoom = 1.05 - (progress * 0.05);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.12; 
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < (windowSize * 0.7);

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.001 ? 'visible' : 'hidden';

        // Narrative Movement Logic
        const yOffset = (progress - section.triggerTime) * 300;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const h2 = el.querySelector('h2');
        const p = el.querySelector('p');

        if (h2 && p) {
          if (isActive) {
            (h2 as HTMLElement).style.opacity = '1';
            (h2 as HTMLElement).style.transform = 'translateY(0) scale(1)';
            (p as HTMLElement).style.opacity = '1';
            (p as HTMLElement).style.transform = 'translateY(0)';
          } else {
            (h2 as HTMLElement).style.opacity = '0';
            const moveDir = progress > section.triggerTime ? '-40px' : '40px';
            (h2 as HTMLElement).style.transform = `translateY(${moveDir}) scale(0.98)`;
            (p as HTMLElement).style.opacity = '0';
            (p as HTMLElement).style.transform = 'translateY(20px)';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;

      if (totalScrollable > 0) {
        // Calculate progress based on relative scroll position of the parent container
        const p = -rect.top / totalScrollable;
        targetProgress.current = Math.max(0, Math.min(1, p));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1200vh] bg-black">
      {/* THE STICKY STAGE: This locks content to the viewport */}
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">

        {/* Visual Engine Layer */}
        <div ref={videoLayerRef} className="absolute inset-0 z-[-1] opacity-60">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">Engine Error</div>
          )}

          {/* Post-Processing Grade */}
          <div className="absolute inset-0 bg-gradient-to-b from-black via-transparent to-black opacity-90" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,black_150%)]" />
        </div>

        {/* Cinematic Narrative UI */}
        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center px-10 md:px-24 pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center px-6 md:px-20 ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-5xl w-full">
                <div className="mb-10">
                   {isEditMode ? (
                     <div className="pointer-events-auto">
                       <input 
                         className="bg-white/[0.03] border border-white/10 px-10 py-6 rounded-[2rem] outline-none text-4xl md:text-7xl font-black tracking-tighter text-white w-full backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                         value={section.title}
                         onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                       />
                     </div>
                   ) : (
                     <h2 className="text-6xl md:text-[9.5rem] font-black tracking-[-0.06em] text-white transition-all duration-1000 ease-out opacity-0 translate-y-20">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="pointer-events-auto">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/[0.03] border border-white/10 px-10 py-8 rounded-[2rem] outline-none text-sm text-white/40 font-bold tracking-[0.4em] uppercase max-w-xl w-full h-40 resize-none backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className="text-[10px] md:text-[11px] text-white/40 font-black tracking-[0.5em] uppercase leading-[2.5] max-w-xl transition-all duration-1000 delay-200 opacity-0 translate-y-10">
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

