import React, { useState, useEffect } from 'react';
import { Code, Zap, X, Edit3, Copy, Trash2, Check, Sparkles, Monitor, Cpu, ChevronDown } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [systemNote, setSystemNote] = useState<string | null>(null);

  useEffect(() => {
    document.body.style.overflow = (showExportModal || state.isAnalyzing) ? 'hidden' : 'unset';
  }, [showExportModal, state.isAnalyzing]);

  const analyzeVideo = async (url: string, title: string, metadata: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);
    setSystemNote(null);

    try {
      if (!process.env.API_KEY) {
        await new Promise(resolve => setTimeout(resolve, 2000));
        setSystemNote("Synthesis Complete");
      }
      const storySections = await generateVideoStory(`Video: ${title}. ${metadata}.`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`CRITICAL_ERR: ${err.message || 'System fault'}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const updateSection = (index: number, updated: ScrollSection) => {
    const next = [...state.sections];
    next[index] = updated;
    setState(prev => ({ ...prev, sections: next }));
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const resetAll = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  return (
    <div className="min-h-screen bg-[#000] text-white selection:bg-indigo-500/30 antialiased font-sans">

      {/* Studio Atmosphere Overlays */}
      <div className="fixed inset-0 pointer-events-none z-50 opacity-[0.04] bg-[url('https://grainy-gradients.vercel.app/noise.svg')]" />
      <div className="fixed inset-0 pointer-events-none z-40 bg-[radial-gradient(circle_at_50%_0%,rgba(79,70,229,0.08),transparent_70%)]" />

      {/* Anchored Studio Branding - Stays in corners */}
      {!state.url && (
        <>
          <div className="fixed top-10 left-12 z-50 flex items-center gap-6 animate-in fade-in slide-in-from-top-4 duration-1000">
             <InfinityLogo size={28} className="text-white" />
             <div className="h-6 w-[1px] bg-white/10" />
             <div className="flex flex-col">
                <span className="text-[9px] font-black tracking-[0.4em] uppercase text-indigo-500">Core Engine</span>
                <span className="text-[9px] font-black tracking-[0.4em] uppercase text-white/20">V 4.2 Alpha</span>
             </div>
          </div>
          <div className="fixed top-10 right-12 z-50 hidden md:flex items-center gap-10 animate-in fade-in slide-in-from-top-4 duration-1000">
             <div className="flex items-center gap-3">
                <Monitor size={12} className="text-white/10" />
                <span className="text-[8px] font-black tracking-[0.3em] uppercase text-white/30">Viewport Ready</span>
             </div>
             <div className="flex items-center gap-3">
                <Cpu size={12} className="text-white/10" />
                <span className="text-[8px] font-black tracking-[0.3em] uppercase text-white/30">Neural Synthesis Active</span>
             </div>
          </div>
        </>
      )}

      {/* Control Dock (Visible when video is active) */}
      {state.url && !state.isAnalyzing && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[500] pointer-events-none">
          <div className="pointer-events-auto flex items-center gap-1.5 p-1.5 bg-neutral-900/90 backdrop-blur-3xl border border-white/10 rounded-full shadow-2xl">
            <div className="flex items-center gap-4 px-6 py-2 border-r border-white/5 mr-1">
              <InfinityLogo size={16} className="text-white" />
              <input 
                value={state.brandName} 
                onChange={e => setState({...state, brandName: e.target.value.toUpperCase()})}
                className="bg-transparent border-none text-[9px] font-black tracking-[0.4em] uppercase outline-none w-20 text-white/40 focus:text-white transition-all"
              />
            </div>
            <button 
              onClick={() => setIsEditMode(!isEditMode)}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-full transition-all text-[9px] font-black uppercase tracking-widest ${isEditMode ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-white/5 text-white/40 hover:text-white'}`}
            >
              {isEditMode ? <Check size={12} /> : <Edit3 size={12} />}
              {isEditMode ? 'Apply Changes' : 'Edit Narrative'}
            </button>
            <button 
              onClick={() => setShowExportModal(true)}
              className="flex items-center gap-2 px-6 py-2.5 bg-white text-black rounded-full hover:bg-neutral-200 transition-all text-[9px] font-black uppercase tracking-widest"
            >
              <Code size={12} /> Get Script
            </button>
            <button onClick={resetAll} className="p-2.5 text-white/10 hover:text-white/40 transition-colors">
              <Trash2 size={16} />
            </button>
          </div>
        </div>
      )}

      {!state.url ? (
        <main className="min-h-screen flex flex-col items-center pt-52 pb-24 px-10 relative">
          <div className="w-full max-w-4xl text-center space-y-20 animate-in fade-in slide-in-from-bottom-8 duration-1000 ease-out">
            <div className="space-y-8">
               <h1 className="text-6xl md:text-[9.5rem] font-black tracking-[-0.05em] leading-[0.85]">
                  BORN TO <br /> <span className="text-neutral-900">SCROLL.</span>
               </h1>
               <div className="h-px w-20 bg-indigo-500/40 mx-auto" />
               <p className="text-neutral-500 text-lg md:text-xl font-medium tracking-tight max-w-lg mx-auto leading-relaxed">
                  The definitive engine for synchronized scroll narratives. <br/>
                  Turn any video into a cinematic experience.
               </p>
            </div>

            <div className="w-full max-w-2xl mx-auto">
               <FileUpload 
                 onFileSelect={(file) => analyzeVideo(URL.createObjectURL(file), file.name, file.type)} 
                 onSampleSelect={(url, name) => analyzeVideo(url, name, 'Reference')}
                 isAnalyzing={state.isAnalyzing} 
               />
            </div>
          </div>

          <div className="mt-24 opacity-20 flex flex-col items-center gap-4">
             <span className="text-[8px] font-black tracking-[0.8em] uppercase">Scroll to Explore History</span>
             <ChevronDown size={14} className="animate-bounce" />
          </div>
        </main>
      ) : (
        <VideoScroller 
          videoUrl={state.url} 
          sections={state.sections} 
          isEditMode={isEditMode}
          onUpdateSection={updateSection}
        />
      )}

      {/* Script Blueprint Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-6 md:p-16 bg-black/98 backdrop-blur-2xl animate-in fade-in duration-300">
          <div className="w-full max-w-5xl h-full bg-[#050505] border border-white/10 rounded-[3rem] overflow-hidden flex flex-col shadow-2xl">
            <div className="flex items-center justify-between px-12 py-10 border-b border-white/5">
               <div className="flex items-center gap-6">
                  <div className="w-12 h-12 bg-indigo-500 text-white flex items-center justify-center rounded-2xl shadow-xl">
                    <Code size={20} />
                  </div>
                  <div>
                    <h3 className="text-lg font-bold tracking-tight">STANDALONE_SNIPPET.JS</h3>
                    <p className="text-[9px] font-black tracking-[0.3em] uppercase text-white/20">Vanilla JS // Zero Dependencies</p>
                  </div>
               </div>
               <button onClick={() => setShowExportModal(false)} className="p-3 hover:bg-white/5 text-white/20 hover:text-white rounded-full transition-all">
                 <X size={24} />
               </button>
            </div>

            <div className="flex-1 p-12 overflow-y-auto font-mono text-[12px] text-white/40 leading-relaxed custom-scrollbar bg-black/40 selection:bg-indigo-500 selection:text-white">
               {generateSnippetCode(state.sections, state.url || "", state.sensitivity)}
            </div>

            <div className="px-12 py-8 border-t border-white/5 flex items-center justify-between bg-white/[0.01]">
               <p className="text-[9px] font-black text-white/20 tracking-[0.4em] uppercase">Optimized for Production Performance</p>
               <button 
                onClick={() => copyToClipboard(generateSnippetCode(state.sections, state.url || "", state.sensitivity))}
                className={`flex items-center gap-4 px-12 py-4 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${copied ? 'bg-emerald-600 text-white' : 'bg-white text-black hover:bg-neutral-200'}`}
               >
                 {copied ? <Check size={16} /> : <Copy size={16} />}
                 {copied ? 'Engine Copied' : 'Copy Engine Code'}
               </button>
            </div>
          </div>
        </div>
      )}

      {/* System Messaging */}
      {(systemNote || error) && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[600] animate-in slide-in-from-bottom-8 duration-500">
           <div className={`px-8 py-5 rounded-2xl border backdrop-blur-3xl shadow-2xl flex items-center gap-5 ${error ? 'bg-red-500/10 border-red-500/20 text-red-400' : 'bg-white/5 border-white/10 text-indigo-400'}`}>
              <Zap size={16} className={error ? 'hidden' : 'animate-pulse text-indigo-500'} />
              <span className="text-[10px] font-black uppercase tracking-[0.4em]">{error || systemNote}</span>
              <button onClick={() => {setError(null); setSystemNote(null)}} className="ml-4 opacity-20 hover:opacity-100 transition-opacity"><X size={16}/></button>
           </div>
        </div>
      )}

      <style dangerouslySetInnerHTML={{ __html: `
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #222; border-radius: 20px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #4f46e5; }
