 * Handles video state, AI analysis, and view switching.
 */
const App: React.FC = () => {
  // --- STATE ---
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // --- EFFECTS ---
  useEffect(() => {
    // Prevent scrolling when a modal or loader is active
    document.body.style.overflow = (showExportModal || state.isAnalyzing) ? 'hidden' : 'unset';
  }, [showExportModal, state.isAnalyzing]);

  // --- ACTIONS ---
  const handleVideoUpload = async (url: string, fileName: string) => {
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    setError(null);

    try {
      // Process with Gemini API
      const storySections = await generateVideoStory(`Video: ${fileName}`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err: any) {
      setError(`ANALYSIS_ERROR: ${err.message}`);
      setState(prev => ({ ...prev, isAnalyzing: false }));
    }
  };

  const handleReset = () => {
    setState({ ...state, url: null, sections: [] });
    setIsEditMode(false);
  };

  const handleUpdateSection = (index: number, updated: ScrollSection) => {
    const newSections = [...state.sections];
    newSections[index] = updated;
    setState(prev => ({ ...prev, sections: newSections }));
  };

  // --- RENDER HELPERS ---
  if (state.url && !state.isAnalyzing) {
    return (
      <div className="bg-black text-white min-h-screen">
