            >
              {isEditMode ? <Check size={14} /> : <Edit3 size={14} />}
              {isEditMode ? 'Save Script' : 'Edit Narrative'}
            </button>
            <button 
              onClick={() => setShowExportModal(true)}
              className="flex items-center gap-2 px-6 py-2 bg-white text-black rounded-full text-[10px] font-bold uppercase hover:bg-neutral-200 transition-all"
            >
              <Code size={14} /> Export Code
            </button>
            <button onClick={handleReset} className="p-2 text-white/20 hover:text-white transition-colors">
              <Trash2 size={16} />
            </button>
          </div>
        </nav>

        {/* Video Stage */}
        <VideoScroller 
          videoUrl={state.url} 
          sections={state.sections} 
          isEditMode={isEditMode}
          onUpdateSection={handleUpdateSection}
        />

        {/* Export Modal */}
        {showExportModal && (
          <div className="fixed inset-0 z-[1000] bg-black/95 flex items-center justify-center p-10 animate-in fade-in duration-300">
            <div className="bg-[#050505] border border-white/10 rounded-3xl w-full max-w-5xl h-3/4 flex flex-col overflow-hidden">
              <div className="p-8 border-b border-white/5 flex justify-between items-center">
