                <button onClick={() => setShowExportModal(false)}><X /></button>
              </div>
              <div className="flex-1 p-8 overflow-y-auto font-mono text-sm text-white/50 bg-black/50">
                <pre>{generateSnippetCode(state.sections, state.url, state.sensitivity)}</pre>
              </div>
              <div className="p-8 border-t border-white/5 flex justify-end">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(generateSnippetCode(state.sections, state.url!, state.sensitivity));
                    setCopied(true);
                    setTimeout(() => setCopied(false), 2000);
                  }}
                  className="bg-indigo-600 text-white px-10 py-3 rounded-full font-bold uppercase text-xs"
                >
                  {copied ? 'Copied!' : 'Copy to Clipboard'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white relative">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none opacity-20 bg-[radial-gradient(circle_at_50%_0%,#4f46e5,transparent_60%)]" />

      {/* Header Info */}
      <header className="absolute top-10 left-10 flex items-center gap-6">
        <InfinityLogo size={32} />
        <div className="h-6 w-px bg-white/10" />
        <div className="flex flex-col">
          <span className="text-[10px] font-black tracking-[0.4em] uppercase text-indigo-500">Aeon Engine</span>
          <span className="text-[10px] font-black tracking-[0.4em] uppercase text-white/20">V 4.5.0</span>
        </div>
      </header>

      <div className="absolute top-10 right-10 hidden md:flex gap-10 opacity-20">
        <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest"><Monitor size={14}/> Ready</div>
        <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest"><Cpu size={14}/> GPU Active</div>
