import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string, brandName: string = "Narrative"): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for a brand called '${brandName}'. 
    Analyze this video: "${videoDescription}".
    Task: Create a 5-section narrative that connects the visuals in this video to the brand '${brandName}'.
    Generate 5 cinematic landing page sections (JSON array).
    - Titles: 1-3 powerful words.
    - Descriptions: 15-25 words.
    - Trigger times: 0.1 to 0.9.
    - Alignment: Vary (left, right, center).`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    // If AI fails or key is missing, return a blank editable template
    // This stops "hardcoded content" from appearing and lets the user build their own.
    return [
      { 
        title: "DRAFT_SECTION", 
        description: "Enter your custom narrative here. Use the Edit Script tool to architect your cinematic scroll experience.", 
        triggerTime: 0.2, 
        alignment: 'left', 
        vibe: 'cinematic' 
      }
    ];
  }
}

import { ScrollSection } from "../types";

export function generateSnippetCode(sections: ScrollSection[], videoUrl: string, sensitivity: number = 0.08): string {
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'REPLACE_WITH_YOUR_VIDEO_URL.mp4' : videoUrl;

  return `<!-- 
  AEON // INFINITY SCROLL ENGINE
  1. Paste this structure at the bottom of your <body>
-->
<div id="aeon-engine">
    <div id="aeon-stage">
        <div class="aeon-video-layer" id="aeon-v-layer">
            <video id="aeon-video" playsinline muted preload="auto" src="${displayUrl}"></video>
            <div class="aeon-grade"></div>
        </div>
        <div id="aeon-narrative"></div>
    </div>
</div>

<style>
/* 2. CORE STYLES */
#aeon-engine { position: fixed; inset: 0; z-index: -1; background: #000; overflow: hidden; pointer-events: none; }
#aeon-stage { position: absolute; inset: 0; }
.aeon-video-layer { position: absolute; inset: 0; opacity: 0.6; }
#aeon-video { width: 100%; height: 100%; object-fit: cover; }
.aeon-grade { position: absolute; inset: 0; background: radial-gradient(circle at center, transparent, #000 150%); }
.aeon-section { 
    position: absolute; inset: 0; display: flex; padding: 10%; 
    opacity: 0; visibility: hidden; transition: all 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}
.aeon-title { font-size: 8vw; font-weight: 900; color: #fff; margin: 0; line-height: 0.9; text-transform: uppercase; }
.aeon-desc { font-size: 1rem; color: rgba(255,255,255,0.4); margin-top: 2rem; max-width: 600px; letter-spacing: 0.2em; text-transform: uppercase; }
</style>

<script>
/* 3. SYSTEM CONFIGURATION & LOGIC */
(function() {
    // --- USER CONFIGURATION ---
    const CONFIG = {
        VIDEO_SOURCE: "${displayUrl}", // CHANGE THIS LINK HERE
        SENSITIVITY: ${sensitivity},
        SECTIONS: ${sectionsJSON}
    };

    const video = document.getElementById('aeon-video');
    const narrative = document.getElementById('aeon-narrative');

    // Initialize Sections
    CONFIG.SECTIONS.forEach((s, i) => {
        const div = document.createElement('div');
        div.className = 'aeon-section';
        div.id = 'sec-' + i;
        div.style.justifyContent = s.alignment === 'left' ? 'flex-start' : s.alignment === 'right' ? 'flex-end' : 'center';
        div.style.alignItems = 'center';
        div.style.textAlign = s.alignment;
        div.innerHTML = \`<div>
            <h2 class="aeon-title">\${s.title}</h2>
            <p class="aeon-desc">\${s.description}</p>
        </div>\`;
        narrative.appendChild(div);
    });

    let target = 0, current = 0;

    function update() {
        current += (target - current) * CONFIG.SENSITIVITY;

        if (video.duration) {
            video.currentTime = video.duration * current;
        }

        CONFIG.SECTIONS.forEach((s, i) => {
            const el = document.getElementById('sec-' + i);
            const dist = Math.abs(current - s.triggerTime);
            const active = dist < 0.1;
            el.style.opacity = active ? 1 : 0;
            el.style.visibility = active ? 'visible' : 'hidden';
            el.style.transform = \`translate3d(0, \${(current - s.triggerTime) * 200}px, 0)\`;
        });

        requestAnimationFrame(update);
    }

    window.addEventListener('scroll', () => {
        const max = document.documentElement.scrollHeight - window.innerHeight;
        target = Math.max(0, Math.min(1, window.scrollY / max));
    }, { passive: true });

    requestAnimationFrame(update);
})();
</script>`;
}

