/**
 * GENERATES A CLEAN, UNDERSTANDABLE HTML SNIPPET
 */
export function generateSnippetCode(sections: ScrollSection[], videoUrl: string, sensitivity: number = 0.08): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'INSERT_YOUR_VIDEO_URL_HERE.mp4' : videoUrl;

  // Clean JSON for the config
  const sectionsJSON = JSON.stringify(sections, null, 4);

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AEON Scroll Narrative</title>
    <style>
        /* CORE STYLES - DO NOT EDIT */
        body { margin: 0; background: #000; color: #fff; font-family: sans-serif; height: 1000vh; overflow-x: hidden; }
        .aeon-stage { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; }
        .aeon-video { width: 100%; height: 100%; object-fit: cover; opacity: 0.6; pointer-events: none; }
        .aeon-narrative { position: absolute; inset: 0; pointer-events: none; }

        /* CONTENT STYLES - FEEL FREE TO EDIT */
        .section { 
            position: absolute; inset: 0; display: flex; flex-direction: column; 
            padding: 10%; opacity: 0; visibility: hidden; 
            transition: opacity 0.5s ease;
        }
        .title { font-size: 8vw; font-weight: 900; margin: 0; text-transform: uppercase; line-height: 0.9; }
        .desc { font-size: 1.2rem; opacity: 0.4; max-width: 600px; margin-top: 2rem; letter-spacing: 0.1em; }
    </style>
</head>
<body>

    <div class="aeon-stage">
        <!-- THE VIDEO ENGINE -->
        <video id="v-engine" playsinline muted preload="auto" src="${displayUrl}"></video>

        <!-- THE NARRATIVE LAYER -->
        <div id="narrative-layer" class="aeon-narrative"></div>
    </div>

    <script>
        /**
         * 1. SYSTEM CONFIGURATION
         * Change your video link or scroll behavior here.
         */
        const CONFIG = {
            VIDEO_URL: "${displayUrl}", // PASTE YOUR VIDEO LINK HERE
            SMOOTHNESS: ${sensitivity}, // Scroll lag (lower = smoother)
            DATA: ${sectionsJSON}
        };

        /**
         * 2. INITIALIZATION
         * Dynamically builds the website based on the config above.
         */
        const video = document.getElementById('v-engine');
        const container = document.getElementById('narrative-layer');

        // Create HTML elements for each section
        CONFIG.DATA.forEach((item, index) => {
            const el = document.createElement('div');
            el.className = 'section';
            el.id = 'sec-' + index;
            el.style.justifyContent = 'center';
            el.style.alignItems = item.alignment === 'left' ? 'flex-start' : item.alignment === 'right' ? 'flex-end' : 'center';
            el.style.textAlign = item.alignment;

            el.innerHTML = \`
                <h2 class="title">\${item.title}</h2>
                <p class="desc">\${item.description}</p>
            \`;
            container.appendChild(el);
        });

        /**
         * 3. SCROLL ENGINE
         * Drives the video playhead and text visibility.
         */
        let targetProgress = 0;
        let currentProgress = 0;

        window.addEventListener('scroll', () => {
            const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
            targetProgress = window.scrollY / maxScroll;
        });

        function animate() {
            // Apply smoothing
            currentProgress += (targetProgress - currentProgress) * CONFIG.SMOOTHNESS;

            // Update Video Time
            if (video.duration) {
                video.currentTime = video.duration * currentProgress;
            }

            // Update Section Opacity
            CONFIG.DATA.forEach((item, index) => {
                const el = document.getElementById('sec-' + index);
                const distance = Math.abs(currentProgress - item.triggerTime);
                const isActive = distance < 0.08;

                el.style.opacity = isActive ? 1 : 0;
                el.style.visibility = isActive ? 'visible' : 'hidden';
                el.style.transform = 'translateY(' + (currentProgress - item.triggerTime) * 100 + 'px)';
            });

            requestAnimationFrame(animate);
        }

        animate();
    </script>
</body>
</html>`;
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      // Smoother viscous damping
      const lerp = 0.06; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.04) {
          video.currentTime = targetTime;
        }

        if (videoLayerRef.current) {
          const zoom = 1.03 - (progress * 0.03);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        // Wider window for visibility to prevent flickering
        const windowSize = 0.15; 
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < (windowSize * 0.6);

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Reduced vertical movement (from 300 to 80) to keep content centered
        const yOffset = (progress - section.triggerTime) * 80;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const h2 = el.querySelector('h2');
        const p = el.querySelector('p');

        if (h2 && p) {
          if (isActive) {
            (h2 as HTMLElement).style.opacity = '1';
            (h2 as HTMLElement).style.transform = 'translateY(0) scale(1)';
            (p as HTMLElement).style.opacity = '1';
            (p as HTMLElement).style.transform = 'translateY(0)';
          } else {
            (h2 as HTMLElement).style.opacity = '0';
            const moveDir = progress > section.triggerTime ? '-20px' : '20px';
            (h2 as HTMLElement).style.transform = `translateY(${moveDir}) scale(0.99)`;
            (p as HTMLElement).style.opacity = '0';
            (p as HTMLElement).style.transform = 'translateY(15px)';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;

      if (totalScrollable > 0) {
        const p = -rect.top / totalScrollable;
        targetProgress.current = Math.max(0, Math.min(1, p));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1000vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">

        <div ref={videoLayerRef} className="absolute inset-0 z-0 opacity-60">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">Engine Error</div>
          )}

          <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-transparent to-black/80" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,black_140%)]" />
        </div>

        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center px-10 md:px-32 ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-4xl w-full flex flex-col gap-6">
                <div>
                   {isEditMode ? (
                     <div className="pointer-events-auto">
                       <input 
                         className="bg-white/[0.03] border border-white/10 px-8 py-4 rounded-[1.5rem] outline-none text-4xl md:text-6xl font-black tracking-tighter text-white w-full backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                         value={section.title}
                         onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                       />
                     </div>
                   ) : (
                     <h2 className="text-5xl md:text-8xl font-black tracking-[-0.04em] text-white transition-all duration-700 ease-out opacity-0 translate-y-10 leading-[1.1]">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="pointer-events-auto flex flex-col items-inherit">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/[0.03] border border-white/10 px-8 py-6 rounded-[1.5rem] outline-none text-xs text-white/40 font-bold tracking-[0.3em] uppercase max-w-lg w-full h-32 resize-none backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className={`text-[10px] md:text-[12px] text-white/40 font-bold tracking-[0.4em] uppercase leading-relaxed max-w-2xl transition-all duration-700 delay-100 opacity-0 translate-y-5 ${section.alignment === 'center' ? 'mx-auto' : section.alignment === 'right' ? 'ml-auto' : ''}`}>
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import { GoogleGenAI, Type } from "@google/genai";
import { ScrollSection } from "../types";

export async function generateVideoStory(videoDescription: string, brandName: string = "Narrative"): Promise<ScrollSection[]> {
  try {
    if (!process.env.API_KEY) {
      throw new Error("API_KEY_MISSING");
    }

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Act as a world-class creative director for a brand called '${brandName}'. 
    Analyze this video: "${videoDescription}".
    Task: Create a 5-section narrative that connects the visuals in this video to the brand '${brandName}'.

    CRITICAL SPACING RULES:
    - Section 1: triggerTime around 0.15
    - Section 2: triggerTime around 0.35
    - Section 3: triggerTime around 0.55
    - Section 4: triggerTime around 0.75
    - Section 5: triggerTime around 0.90

    Generate 5 cinematic landing page sections (JSON array).
    - Titles: 1-3 powerful words (e.g. "BEYOND LIMITS").
    - Descriptions: 15-20 concise words.
    - Alignment: Vary (left, right, center).`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              triggerTime: { type: Type.NUMBER },
              alignment: { type: Type.STRING, enum: ['left', 'right', 'center'] },
              vibe: { type: Type.STRING, enum: ['cinematic', 'minimal', 'energetic'] }
            },
            required: ["title", "description", "triggerTime", "alignment", "vibe"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    const sections = JSON.parse(text);
    return sections.sort((a: any, b: any) => a.triggerTime - b.triggerTime);

  } catch (error: any) {
    return [
      { 
        title: "SYSTEM_READY", 
        description: "Your engine is active. architect your cinematic narrative using the edit tools provided.", 
        triggerTime: 0.25, 
        alignment: 'center', 
        vibe: 'cinematic' 
      }
    ];
  }
}

