import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      // Smoother viscous damping
      const lerp = 0.06; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        if (!video.seeking && Math.abs(video.currentTime - targetTime) > 0.04) {
          video.currentTime = targetTime;
        }

        if (videoLayerRef.current) {
          const zoom = 1.03 - (progress * 0.03);
          videoLayerRef.current.style.transform = `scale3d(${zoom}, ${zoom}, 1)`;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.15; 
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < (windowSize * 0.6);

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        // Very subtle drift (40px) to keep content within viewport safety
        const yOffset = (progress - section.triggerTime) * 40;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const h2 = el.querySelector('h2');
        const p = el.querySelector('p');

        if (h2 && p) {
          if (isActive) {
            (h2 as HTMLElement).style.opacity = '1';
            (h2 as HTMLElement).style.transform = 'translateY(0) scale(1)';
            (p as HTMLElement).style.opacity = '1';
            (p as HTMLElement).style.transform = 'translateY(0)';
          } else {
            (h2 as HTMLElement).style.opacity = '0';
            const moveDir = progress > section.triggerTime ? '-10px' : '10px';
            (h2 as HTMLElement).style.transform = `translateY(${moveDir}) scale(0.99)`;
            (p as HTMLElement).style.opacity = '0';
            (p as HTMLElement).style.transform = 'translateY(10px)';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;

      if (totalScrollable > 0) {
        const p = -rect.top / totalScrollable;
        targetProgress.current = Math.max(0, Math.min(1, p));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[1000vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">

        <div ref={videoLayerRef} className="absolute inset-0 z-0 opacity-60">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">Engine Error</div>
          )}

          <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-transparent to-black/80" />
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,black_140%)]" />
        </div>

        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center px-6 md:px-32 ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-4xl w-full flex flex-col gap-4 md:gap-6">
                <div>
                   {isEditMode ? (
                     <div className="pointer-events-auto">
                       <input 
                         className="bg-white/[0.03] border border-white/10 px-6 py-3 rounded-[1.2rem] outline-none text-3xl md:text-6xl font-black tracking-tighter text-white w-full backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                         value={section.title}
                         onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                       />
                     </div>
                   ) : (
                     <h2 className="text-4xl md:text-8xl font-black tracking-[-0.04em] text-white transition-all duration-700 ease-out opacity-0 translate-y-10 leading-[1.1]">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="pointer-events-auto flex flex-col items-inherit">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/[0.03] border border-white/10 px-6 py-4 rounded-[1.2rem] outline-none text-[10px] md:text-xs text-white/40 font-bold tracking-[0.2em] uppercase max-w-lg w-full h-24 md:h-32 resize-none backdrop-blur-3xl focus:border-indigo-500/50 transition-all"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className={`text-[9px] md:text-[12px] text-white/40 font-bold tracking-[0.4em] uppercase leading-relaxed max-w-2xl transition-all duration-700 delay-100 opacity-0 translate-y-5 ${section.alignment === 'center' ? 'mx-auto' : section.alignment === 'right' ? 'ml-auto' : ''}`}>
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import { ScrollSection } from "../types";

/**
 * GENERATES A ROBUST, PRODUCTION-READY SCROLL SNIPPET
 */
export function generateSnippetCode(sections: ScrollSection[], videoUrl: string, sensitivity: number = 0.08): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_VIDEO_URL_HERE.mp4' : videoUrl;

  const sectionsJSON = JSON.stringify(sections, null, 4);

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AEON Scroll Narrative</title>
    <style>
        body { margin: 0; background: #000; color: #fff; font-family: sans-serif; height: 800vh; overflow-x: hidden; }
        .aeon-stage { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; background: #000; }
        #v-engine { width: 100%; height: 100%; object-fit: cover; opacity: 0.5; pointer-events: none; transition: opacity 1s ease; }
        .aeon-narrative { position: absolute; inset: 0; pointer-events: none; z-index: 10; }

        .section { 
            position: absolute; inset: 0; display: flex; flex-direction: column; 
            padding: 10% 12%; opacity: 0; visibility: hidden; 
            transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
            justify-content: center;
        }
        .title { font-size: clamp(2rem, 8vw, 6rem); font-weight: 900; margin: 0; text-transform: uppercase; line-height: 1.1; letter-spacing: -0.02em; }
        .desc { font-size: clamp(0.7rem, 2vw, 1rem); opacity: 0.4; max-width: 500px; margin-top: 1.5rem; letter-spacing: 0.3em; text-transform: uppercase; line-height: 1.6; }

        /* Loading Overlay */
        #loader { position: fixed; inset: 0; z-index: 100; background: #000; display: flex; align-items: center; justify-content: center; font-size: 10px; letter-spacing: 0.5em; text-transform: uppercase; transition: opacity 0.5s ease; }
    </style>
</head>
<body>

    <div id="loader">Syncing System...</div>

    <div class="aeon-stage">
        <!-- Add crossOrigin for better CDN support -->
        <video id="v-engine" playsinline muted preload="auto" crossorigin="anonymous">
            <source src="${displayUrl}" type="video/mp4">
        </video>
        <div id="narrative-layer" class="aeon-narrative"></div>
    </div>

    <script>
        const CONFIG = {
            VIDEO_URL: "${displayUrl}",
            SMOOTHNESS: ${sensitivity},
            DATA: ${sectionsJSON}
        };

        const video = document.getElementById('v-engine');
        const container = document.getElementById('narrative-layer');
        const loader = document.getElementById('loader');

        // 1. Build Narrative UI
        CONFIG.DATA.forEach((item, index) => {
            const el = document.createElement('div');
            el.className = 'section';
            el.id = 'sec-' + index;
            el.style.alignItems = item.alignment === 'left' ? 'flex-start' : item.alignment === 'right' ? 'flex-end' : 'center';
            el.style.textAlign = item.alignment;
            el.innerHTML = \`<h2 class="title">\${item.title}</h2><p class="desc">\${item.description}</p>\`;
            container.appendChild(el);
        });

        // 2. Engine Logic
        let targetProgress = 0;
        let currentProgress = 0;
        let isReady = false;

        // Force browser to load video data
        video.load();

        video.addEventListener('loadedmetadata', () => {
            isReady = true;
            loader.style.opacity = '0';
            setTimeout(() => loader.style.display = 'none', 500);
            animate();
        });

        // Fallback for cached videos
        if (video.readyState >= 2) {
            isReady = true;
            loader.style.display = 'none';
            animate();
        }

        window.addEventListener('scroll', () => {
            const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
            targetProgress = window.scrollY / (maxScroll || 1);
        }, { passive: true });

        function animate() {
            // Lerp for smooth scrolling
            currentProgress += (targetProgress - currentProgress) * CONFIG.SMOOTHNESS;

            // Sync video time
            if (isReady && video.duration) {
                const scrubTime = video.duration * currentProgress;
                // Only update if difference is significant to save CPU
                if (Math.abs(video.currentTime - scrubTime) > 0.01) {
                    video.currentTime = scrubTime;
                }
            }

            // Sync Narrative Visibility
            CONFIG.DATA.forEach((item, index) => {
                const el = document.getElementById('sec-' + index);
                const distance = Math.abs(currentProgress - item.triggerTime);
                const activeRange = 0.12;

                const opacity = Math.max(0, 1 - (distance / activeRange));
                el.style.opacity = opacity;
                el.style.visibility = opacity > 0.05 ? 'visible' : 'hidden';

                // Subtle vertical movement
                const yShift = (currentProgress - item.triggerTime) * 60;
                el.style.transform = \`translate3d(0, \${yShift}px, 0)\`;
            });

            requestAnimationFrame(animate);
        }
    </script>
</body>
</html>`;
}

