import { ScrollSection } from "../types";

/**
 * AEON EXPORT ENGINE v2.1
 * Optimized for single-file deployment and high-performance scrubbing.
 */
export function generateSnippetCode(sections: ScrollSection[], videoUrl: string, sensitivity: number = 0.1): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_VIDEO_URL_HERE.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);

  return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>AEON // Narrative</title>
    <style>
        :root { --accent: #4f46e5; }
        body { margin: 0; background: #000; color: #fff; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; height: 800vh; overflow-x: hidden; }

        /* The Visual Stage */
        .aeon-viewport { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; overflow: hidden; z-index: 1; }
        #v-engine { width: 100%; height: 100%; object-fit: cover; opacity: 0.6; }

        /* Narrative Overlay */
        .aeon-narrative { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
        .section { 
            position: absolute; inset: 0; display: flex; flex-direction: column; justify-content: center;
            padding: 0 10%; opacity: 0; visibility: hidden; 
            transition: opacity 0.5s ease, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .title { font-size: clamp(2.5rem, 10vw, 7rem); font-weight: 900; margin: 0; text-transform: uppercase; line-height: 0.9; letter-spacing: -0.04em; }
        .desc { font-size: clamp(0.7rem, 1.5vw, 0.9rem); opacity: 0.5; max-width: 400px; margin-top: 2rem; letter-spacing: 0.4em; text-transform: uppercase; line-height: 1.8; }

        /* System UI */
        #loader { position: fixed; inset: 0; z-index: 100; background: #000; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 20px; transition: opacity 0.8s ease; }
        .spinner { width: 30px; height: 30px; border: 2px solid rgba(255,255,255,0.1); border-top-color: var(--accent); border-radius: 50%; animation: spin 1s linear infinite; }
        @keyframes spin { to { transform: rotate(360deg); } }
    </style>
</head>
<body>

    <div id="loader">
        <div class="spinner"></div>
        <div style="font-size: 10px; letter-spacing: 0.5em; opacity: 0.5;">INITIALIZING ENGINE</div>
    </div>

    <div class="aeon-viewport">
        <video id="v-engine" playsinline muted preload="auto"></video>
        <div id="narrative-layer" class="aeon-narrative"></div>
    </div>

    <script>
        /**
         * SET YOUR VIDEO LINK BELOW
         */
        const VIDEO_URL = "${displayUrl}";

        const DATA = ${sectionsJSON};
        const SENSITIVITY = ${sensitivity};

        const video = document.getElementById('v-engine');
        const container = document.getElementById('narrative-layer');
        const loader = document.getElementById('loader');

        // Setup System
        video.src = VIDEO_URL;

        DATA.forEach((item, index) => {
            const el = document.createElement('div');
            el.className = 'section';
            el.id = 's-' + index;
            el.style.alignItems = item.alignment === 'left' ? 'flex-start' : item.alignment === 'right' ? 'flex-end' : 'center';
            el.style.textAlign = item.alignment;
            el.innerHTML = \`<h2 class="title">\${item.title}</h2><p class="desc">\${item.description}</p>\`;
            container.appendChild(el);
        });

        let targetProgress = 0;
        let currentProgress = 0;

        const sync = () => {
            currentProgress += (targetProgress - currentProgress) * SENSITIVITY;

            if (video.duration) {
                video.currentTime = video.duration * currentProgress;
            }

            DATA.forEach((item, index) => {
                const el = document.getElementById('s-' + index);
                const dist = Math.abs(currentProgress - item.triggerTime);
                const opacity = Math.max(0, 1 - (dist / 0.15));
                el.style.opacity = opacity;
                el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                el.style.transform = \`translate3d(0, \${(currentProgress - item.triggerTime) * 80}px, 0)\`;
            });

            requestAnimationFrame(sync);
        };

        const onReady = () => {
            loader.style.opacity = '0';
            setTimeout(() => loader.style.display = 'none', 800);
            sync();
        };

        window.addEventListener('scroll', () => {
            targetProgress = window.scrollY / (document.documentElement.scrollHeight - window.innerHeight);
        }, { passive: true });

        video.addEventListener('loadedmetadata', onReady);
        if (video.readyState >= 2) onReady();

        // Error Handler
        video.onerror = () => {
            document.body.innerHTML = '<div style="padding:50px; text-align:center;">VIDEO_ERROR: Ensure the URL is valid and supports cross-origin scrubbing.</div>';
        };
    </script>
</body>
</html>`;
}

