<body>

    <div id="aeon-loader" style="font-size: 10px; letter-spacing: 1em; font-weight: 900;">SYNCING_AEON_ENGINE</div>

    <div class="aeon-main-container">
        <video id="aeon-video" playsinline muted preload="auto"></video>
        <div id="aeon-narrative-layer" class="aeon-narrative-overlay"></div>
    </div>

    <script>
        /**
         * 1. INPUT VIDEO URL HERE
         */
        const VIDEO_SRC = "${displayUrl}";

        /**
         * 2. DATA CONFIGURATION
         */
        const SECTIONS = ${sectionsJSON};
        const LERP_SPEED = ${sensitivity};

        const video = document.getElementById('aeon-video');
        const layer = document.getElementById('aeon-narrative-layer');
        const loader = document.getElementById('aeon-loader');

        video.src = VIDEO_SRC;

        // Build UI
        SECTIONS.forEach((s, i) => {
            const div = document.createElement('div');
            div.className = 'aeon-section';
            div.id = 'sec-' + i;
            div.style.alignItems = s.alignment === 'left' ? 'flex-start' : s.alignment === 'right' ? 'flex-end' : 'center';
            div.style.textAlign = s.alignment;
            div.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
            layer.appendChild(div);
        });

        let targetPos = 0;
        let currentPos = 0;

        const update = () => {
            // Smooth lerp
            currentPos += (targetPos - currentPos) * LERP_SPEED;

            // Sync Video
            if (video.duration) {
                video.currentTime = video.duration * currentPos;
            }

            // Sync Sections - Narrow window (0.07) to prevent overlap
            SECTIONS.forEach((s, i) => {
                const el = document.getElementById('sec-' + i);
                const dist = Math.abs(currentPos - s.triggerTime);
                const opacity = Math.max(0, 1 - (dist / 0.07)); 

                el.style.opacity = opacity;
                el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                el.style.transform = \`translate3d(0, \${(currentPos - s.triggerTime) * 100}px, 0)\`;
            });

            requestAnimationFrame(update);
        };

        const init = () => {
            loader.style.opacity = '0';
            setTimeout(() => loader.style.display = 'none', 1000);
            update();
        };

        window.addEventListener('scroll', () => {
            const max = document.documentElement.scrollHeight - window.innerHeight;
            targetPos = window.scrollY / (max || 1);
        }, { passive: true });

        video.addEventListener('loadedmetadata', init);
        if (video.readyState >= 2) init();
    </script>
</body>
</html>`;
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      const lerp = 0.08; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.05) {
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        // NARROW WINDOW to prevent overlapping mess
        const windowSize = 0.07; 
        const opacity = Math.max(0, 1 - (distance / windowSize));
        const isActive = distance < (windowSize * 0.4);

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;

        const h2 = el.querySelector('h2');
        const p = el.querySelector('p');

        if (h2 && p) {
          if (isActive) {
            (h2 as HTMLElement).style.opacity = '1';
            (h2 as HTMLElement).style.transform = 'translateY(0)';
            (p as HTMLElement).style.opacity = '1';
          } else {
            (h2 as HTMLElement).style.opacity = '0';
            (h2 as HTMLElement).style.transform = 'translateY(15px)';
            (p as HTMLElement).style.opacity = '0';
          }
        }
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (totalScrollable > 0) {
        targetProgress.current = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[800vh] bg-black">
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">

        <div ref={videoLayerRef} className="absolute inset-0 z-0 opacity-40">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">SOURCE_FAULT</div>
          )}
          <div className="absolute inset-0 bg-black/20" />
        </div>

        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center pointer-events-none px-10">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center px-10 md:px-24 ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-5xl w-full flex flex-col gap-6">
                <div className="pointer-events-auto">
                   {isEditMode ? (
                     <input 
                       className="bg-white/5 border border-white/10 px-6 py-4 rounded-xl outline-none text-3xl md:text-8xl font-black tracking-tighter text-white w-full focus:border-indigo-500/50 transition-all text-shadow-xl"
                       value={section.title}
                       onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                     />
                   ) : (
                     <h2 className="text-5xl md:text-9xl font-black tracking-tighter text-white transition-all duration-700 opacity-0 translate-y-10 leading-[0.85] drop-shadow-2xl">
                       {section.title}
                     </h2>
                   )}
                </div>
                <div className="pointer-events-auto">
                  {isEditMode ? (
                    <textarea 
                      className="bg-white/5 border border-white/10 px-6 py-4 rounded-xl outline-none text-[10px] text-white/60 font-bold tracking-[0.3em] uppercase w-full h-24 resize-none focus:border-indigo-500/50 transition-all"
                      value={section.description}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    />
                  ) : (
                    <p className={`text-[10px] md:text-[12px] text-white/40 font-bold tracking-[0.5em] uppercase leading-relaxed max-w-xl transition-all duration-700 opacity-0 ${section.alignment === 'center' ? 'mx-auto' : section.alignment === 'right' ? 'ml-auto' : ''}`}>
                      {section.description}
                    </p>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

