<body id="aeon-root">

    <div id="aeon-loader">INITIALIZING_AEON_ENGINE</div>

    <!-- BACKGROUND ENGINE -->
    <div class="aeon-stage">
        <video id="aeon-video-engine" playsinline muted preload="auto"></video>
        <div id="aeon-narrative-canvas" class="aeon-narrative-layer"></div>
    </div>

    <!-- YOUR WEBSITE CONTENT GOES HERE -->
    <div class="my-website-content">

        <!-- SECTION 1 -->
        <div class="content-block">
            <div class="card">
                <h1 style="font-size: 2rem; font-weight: 900; margin-bottom: 1rem;">YOUR TITLE HERE</h1>
                <p style="opacity: 0.6; line-height: 1.6;">
                    Paste your actual website HTML inside this "my-website-content" div. 
                    The scroll animation and narrative titles will play smoothly behind this layer.
                </p>
            </div>
        </div>

        <!-- SECTION 2 -->
        <div class="content-block" style="justify-content: flex-end;">
            <div class="card">
                <h2 style="font-size: 1.5rem; font-weight: 900; margin-bottom: 1rem;">ISOLATED & CLEAN</h2>
                <p style="opacity: 0.6; line-height: 1.6;">
                    Everything is layered. Your content has priority, while the video handles the atmosphere.
                </p>
            </div>
        </div>

        <!-- Add more blocks as needed to match the height of the page -->
        <div style="height: 500vh;"></div>

    </div>

    <script>
        const VIDEO_PATH = "${displayUrl}";
        const NARRATIVE_DATA = ${sectionsJSON};
        const SCROLL_SMOOTHNESS = ${sensitivity};

        const video = document.getElementById('aeon-video-engine');
        const canvas = document.getElementById('aeon-narrative-canvas');
        const loader = document.getElementById('aeon-loader');

        video.src = VIDEO_PATH;

        // Construct Narrative
        NARRATIVE_DATA.forEach((s, i) => {
            const div = document.createElement('div');
            div.className = 'aeon-section';
            div.id = 'aeon-sec-' + i;
            div.style.alignItems = s.alignment === 'left' ? 'flex-start' : s.alignment === 'right' ? 'flex-end' : 'center';
