            div.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
            canvas.appendChild(div);
        });

        let target = 0;
        let current = 0;

        function loop() {
            current += (target - current) * SCROLL_SMOOTHNESS;

            if (video.duration) {
                video.currentTime = video.duration * current;
            }

            NARRATIVE_DATA.forEach((s, i) => {
                const el = document.getElementById('aeon-sec-' + i);
