import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const videoLayerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      const lerp = 0.08; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const targetTime = video.duration * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.05) {
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.08; 
        const opacity = Math.max(0, 1 - (distance / windowSize));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        const yOffset = (progress - section.triggerTime) * 150;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (totalScrollable > 0) {
        targetProgress.current = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[800vh] bg-black">
      {/* BACKGROUND LAYERS */}
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">

        {/* VIDEO ENGINE */}
        <div ref={videoLayerRef} className="absolute inset-0 z-0 opacity-30">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">SOURCE_FAULT</div>
          )}
        </div>

        {/* NARRATIVE GHOST LAYER (Recessed) */}
        <div className="absolute inset-0 z-10 flex flex-col items-center justify-center pointer-events-none px-10">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className={`absolute inset-0 flex items-center px-10 md:px-24 ${
                section.alignment === 'left' ? 'justify-start text-left' : 
                section.alignment === 'right' ? 'justify-end text-right' : 
                'justify-center text-center'
              }`}
              style={{ opacity: 0, visibility: 'hidden' }}
            >
              <div className="max-w-7xl w-full flex flex-col">
                <div className="pointer-events-auto">
                   {isEditMode ? (
                     <input 
                       className="bg-white/5 border border-white/10 px-6 py-4 rounded-xl outline-none text-3xl md:text-8xl font-black tracking-tighter text-white w-full focus:border-indigo-500/50 transition-all"
                       value={section.title}
                       onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                     />
                   ) : (
                     <h2 className="text-6xl md:text-[12rem] font-black tracking-tighter text-white/10 leading-[0.8] select-none">
                       {section.title}
                     </h2>
                   )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* FOREGROUND CONTENT PREVIEW (Your website content would go here) */}
      <div className="relative z-20 pointer-events-none">
        <div className="min-h-screen flex flex-col justify-center px-20">
          <div className="bg-white/5 backdrop-blur-3xl border border-white/10 p-12 rounded-[3rem] max-w-xl pointer-events-auto">
             <span className="text-indigo-500 text-[9px] font-black tracking-[1em] uppercase mb-4 block">Foreground Layer</span>
             <h3 className="text-4xl font-black tracking-tighter text-white mb-6">Your Content Stays Clean</h3>
             <p className="text-white/40 leading-relaxed font-bold text-sm tracking-wide">
               The narrative animation is now a 'Ghost Layer' behind your content. 
               This prevents overlapping text while keeping the cinematic atmosphere.
             </p>
          </div>
        </div>
        <div className="min-h-screen" />
        <div className="min-h-screen flex flex-col justify-center items-end px-20">
          <div className="bg-black/40 backdrop-blur-3xl border border-white/10 p-12 rounded-[3rem] max-w-xl pointer-events-auto">
             <h3 className="text-4xl font-black tracking-tighter text-white mb-6">Seamless Flow</h3>
             <p className="text-white/40 leading-relaxed font-bold text-sm tracking-wide">
               As you scroll, the video scrubs and the background narrative changes, but your UI remains the focus.
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

