import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ videoUrl, sections, onUpdateSection, isEditMode }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  useEffect(() => {
    const animate = () => {
      const lerp = 0.08; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;

      const progress = currentProgress.current;
      const video = videoRef.current;

      if (video && video.duration && !isNaN(video.duration)) {
        const safeDuration = video.duration - 0.1;
        const targetTime = safeDuration * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.05) {
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const windowSize = 0.12; 
        const opacity = Math.max(0, 1 - (distance / windowSize));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';

        const yOffset = (progress - section.triggerTime) * 180;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (totalScrollable > 0) {
        targetProgress.current = Math.max(0, Math.min(1, -rect.top / totalScrollable));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections]);

  return (
    <div ref={containerRef} className="relative w-full h-[800vh] bg-black">

      {/* 1. BACKGROUND ENGINE LAYER (FULL COLOR) */}
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0 pointer-events-none">

        {/* VIDEO SCRUBBER - NO FILTERS */}
        <div className="absolute inset-0 z-0 opacity-50">
          {!hasError ? (
            <video
              ref={videoRef}
              src={videoUrl}
              playsInline
              muted
              preload="auto"
              onError={() => setHasError(true)}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full flex items-center justify-center text-white/5 font-black uppercase tracking-[1em]">SYSTEM_ERROR</div>
          )}
        </div>

        {/* GHOST TEXT LAYER */}
        <div className="absolute inset-0 z-10 flex items-center justify-center">
          {sections.map((section, idx) => (
            <div
              key={idx}
              ref={(el) => { sectionRefs.current[idx] = el; }}
              className="absolute w-full px-20"
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              {isEditMode ? (
                <div className="pointer-events-auto max-w-4xl mx-auto">
                  <input 
                    className="bg-white/5 border border-white/10 px-6 py-4 rounded-xl outline-none text-4xl md:text-8xl font-black tracking-tighter text-white/60 w-full focus:text-white transition-all text-center"
                    value={section.title}
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                  />
                </div>
              ) : (
                <h2 className="text-6xl md:text-[15rem] font-black tracking-tighter text-white/[0.06] leading-none select-none uppercase drop-shadow-2xl">
                  {section.title}
                </h2>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 2. FOREGROUND LAYER (PREVIEW CONTENT) */}
      <div className="relative z-20">
        <section className="min-h-screen flex items-center justify-center px-10">
          <div className="text-center max-w-5xl">
            <h1 className="text-7xl md:text-[10rem] font-black tracking-tighter text-white mb-8 drop-shadow-2xl leading-[0.8]">
              CONTENT<br/>
              PRIORITY
            </h1>
            <p className="text-white/50 text-[10px] md:text-xs font-black tracking-[0.8em] uppercase max-w-2xl mx-auto leading-loose bg-black/20 p-4 rounded-full backdrop-blur-md">
              Cinematic Background Active
            </p>
          </div>
        </section>

        <section className="min-h-screen flex items-center justify-center">
          <div className="bg-white/[0.02] backdrop-blur-3xl border border-white/5 p-16 rounded-[4rem] max-w-2xl pointer-events-auto text-center">
             <h3 className="text-5xl font-black text-white mb-6 tracking-tighter">COLOR OPTIMIZED</h3>
             <p className="text-white/40 text-sm leading-relaxed font-bold tracking-wide uppercase">
               The desaturation filters have been removed. Your video will now shine in its original quality.
             </p>
          </div>
        </section>

        <div className="h-[300vh]" />
      </div>

    </div>
  );
};

