/**
 * AEON MODULAR EXPORT ENGINE v9.0
 * Generates self-contained, sticky-positioned scroll sections.
 */
export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.15,
  scrollDepth: number = 4
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_PUBLIC_VIDEO_URL_HERE.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  const notice = isBlob ? `
<!-- 
     ⚠️ ATTENTION: DEPLOYMENT REQUIRED ⚠️
     This snippet uses a local preview. Update the 'SRC' constant with your public video URL.
-->` : '';

  return `${notice}
<!-- AEON MODULAR SECTION: [${instanceId}] -->
<div id="${instanceId}-track" class="aeon-instance-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible;">
    <style>
        #${instanceId}-track {
            margin: 0; padding: 0;
            font-family: 'Inter', system-ui, -apple-system, sans-serif;
        }

        #${instanceId}-track .aeon-sticky-frame {
            position: sticky;
            top: 0;
            left: 0;
            width: 100%;
            height: 100vh;
            overflow: hidden;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        #${instanceId}-track .aeon-video {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: contrast(1.1) brightness(0.9);
            z-index: 1;
        }

        #${instanceId}-track .aeon-overlay {
            position: absolute;
            inset: 0;
            z-index: 2;
            display: flex;
            align-items: center;
            justify-content: center;
            pointer-events: none;
        }

        #${instanceId}-track .aeon-text-block {
            position: absolute;
            width: 100%;
            padding: 0 10%;
            opacity: 0;
            visibility: hidden;
            transition: opacity 0.4s ease;
            will-change: transform, opacity;
        }

        #${instanceId}-track .aeon-title {
            font-size: clamp(3rem, 12vw, 15rem);
            font-weight: 900;
            text-transform: uppercase;
            line-height: 0.8;
            letter-spacing: -0.05em;
            color: rgba(255, 255, 255, 0.2);
            margin: 0;
        }

        #${instanceId}-track .aeon-loader {
            position: absolute; inset: 0; z-index: 10;
            background: #000; display: flex; align-items: center; justify-content: center;
            color: #fff; font-size: 10px; font-weight: 900; letter-spacing: 0.5em;
            transition: opacity 0.8s ease;
        }
    </style>

    <div class="aeon-sticky-frame">
        <div id="${instanceId}-loader" class="aeon-loader">AEON_SYNC_INIT</div>
        <video id="${instanceId}-video" class="aeon-video" playsinline muted preload="auto" webkit-playsinline="true"></video>
        <div id="${instanceId}-stage" class="aeon-overlay"></div>
    </div>

    <script>
        (function() {
            const CONFIG = {
                src: "${displayUrl}",
                data: ${sectionsJSON},
                lerp: ${sensitivity},
                id: "${instanceId}"
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-video');
            const stage = document.getElementById(CONFIG.id + '-stage');
            const loader = document.getElementById(CONFIG.id + '-loader');

            video.src = CONFIG.src;
            video.pause();

            CONFIG.data.forEach((s, i) => {
                const div = document.createElement('div');
                div.className = 'aeon-text-block';
                div.id = CONFIG.id + '-text-' + i;
                div.style.textAlign = s.alignment;
                div.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2>\`;
                stage.appendChild(div);
            });

            let targetProgress = 0;
            let currentProgress = 0;
            let isSeeking = false;

            function animate() {
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;

                if (video.duration && !isSeeking) {
                    const seek = (video.duration - 0.1) * currentProgress;
                    if (Math.abs(video.currentTime - seek) > 0.02) {
                        isSeeking = true;
                        video.currentTime = seek;
                    }
                }

                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-text-' + i);
                    if (!el) return;
                    const dist = Math.abs(currentProgress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.12));
                    el.style.opacity = opacity;
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(currentProgress - s.triggerTime) * 100}px, 0)\`;
                });

                requestAnimationFrame(animate);
            }

            function handleScroll() {
                const rect = track.getBoundingClientRect();
                const total = track.offsetHeight - window.innerHeight;
                if (total > 0) {
                    const p = -rect.top / total;
                    targetProgress = Math.max(0, Math.min(1, p));
                }
            }

            video.addEventListener('seeked', () => isSeeking = false);
            window.addEventListener('scroll', handleScroll, { passive: true });

            video.onloadedmetadata = () => {
                loader.style.opacity = '0';
                setTimeout(() => loader.style.display = 'none', 1000);
                handleScroll();
                animate();
            };

            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>
<!-- END AEON MODULAR SECTION -->`;
}

