import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import { RefreshCw, Lock, ArrowDown, ArrowUp } from 'lucide-react';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  scrollDepth?: number;
  startOffset?: number;
  endOffset?: number;
  topSpacer?: number;
  bottomSpacer?: number;
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  scrollDepth = 8,
  startOffset = 0,
  endOffset = 0,
  topSpacer = 0,
  bottomSpacer = 0,
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);

  const [hasError, setHasError] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setHasError(false);
    setIsLoaded(false);
    const handleCanPlay = () => {
      setIsLoaded(true);
      video.pause();
      video.currentTime = 0;
    };
    video.addEventListener('canplay', handleCanPlay, { once: true });
    video.load();
    return () => video.removeEventListener('canplay', handleCanPlay);
  }, [videoUrl, retryCount]);

  useEffect(() => {
    const animate = () => {
      const lerp = 0.1; 
      currentProgress.current += (targetProgress.current - currentProgress.current) * lerp;
      const progress = currentProgress.current;
      const video = videoRef.current;

      const activeRange = 1 - startOffset - endOffset;
      const narrativeProgress = Math.max(0, Math.min(1, (progress - startOffset) / activeRange));

      if (video && video.readyState >= 2 && video.duration && !isNaN(video.duration) && !isSeeking.current) {
        const safeDuration = video.duration - 0.1;
        const targetTime = safeDuration * narrativeProgress;
        if (Math.abs(video.currentTime - targetTime) > 0.02) {
          isSeeking.current = true;
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;
        const distance = Math.abs(narrativeProgress - section.triggerTime);
        const windowSize = 0.12; 
        const opacity = Math.max(0, 1 - (distance / windowSize));
        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        const multiplier = window.innerWidth < 768 ? 60 : 100;
        const yOffset = (narrativeProgress - section.triggerTime) * multiplier;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollable = containerRef.current.offsetHeight - window.innerHeight;
      if (totalScrollable > 0) {
        const relativeProgress = -rect.top / totalScrollable;
        targetProgress.current = Math.max(0, Math.min(1, relativeProgress));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(rafid);
    };
  }, [sections, startOffset, endOffset]);

  const handleSeeked = () => { isSeeking.current = false; };

  return (
    <div className="w-full bg-[#050505]">
      {/* Simulation: Top Spacer */}
      {topSpacer > 0 && (
        <div style={{ height: `${topSpacer}vh` }} className="w-full flex flex-col items-center justify-center border-b border-white/5 bg-zinc-950/50">
           <ArrowDown className="text-white/10 mb-4 animate-bounce" />
           <p className="text-[10px] font-black tracking-widest text-white/20 uppercase">Simulated Content Above</p>
        </div>
      )}

      {/* The Actual Video Track */}
      <div ref={containerRef} className="relative w-full bg-black overflow-visible" style={{ height: `${scrollDepth * 100}vh` }}>
        <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">
          {isEditMode && (
            <>
              <div className="absolute top-0 left-0 w-full bg-indigo-500/20 z-20 flex items-center justify-center border-b border-indigo-500/40 pointer-events-none" style={{ height: `${startOffset * 100}%` }}>
                 <span className="text-[9px] font-black tracking-widest uppercase text-indigo-400 opacity-40">Entry Lock Area</span>
              </div>
              <div className="absolute bottom-0 left-0 w-full bg-indigo-500/20 z-20 flex items-center justify-center border-t border-indigo-500/40 pointer-events-none" style={{ height: `${endOffset * 100}%` }}>
                 <span className="text-[9px] font-black tracking-widest uppercase text-indigo-400 opacity-40">Exit Lock Area</span>
              </div>
            </>
          )}

          <div className="absolute inset-0 z-0 bg-black">
            {!hasError ? (
              <video
                key={videoUrl} 
                ref={videoRef}
                src={videoUrl}
                onSeeked={handleSeeked}
                playsInline
                muted
                preload="auto"
                onError={() => setHasError(true)}
                className={`w-full h-full object-cover transition-opacity duration-1000 brightness-90 contrast-110 ${isLoaded ? 'opacity-100' : 'opacity-0'}`}
              />
            ) : (
              <div className="w-full h-full flex items-center justify-center bg-zinc-950"><p className="text-white/20 text-xs">MEDIA_LOAD_ERROR</p></div>
            )}
            {!isLoaded && !hasError && (
              <div className="absolute inset-0 flex items-center justify-center bg-black"><div className="w-10 h-10 border-2 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin" /></div>
            )}
          </div>

          <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
            {sections.map((section, idx) => (
              <div key={idx} ref={(el) => { sectionRefs.current[idx] = el; }} className="absolute w-full px-6 md:px-20" style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}>
                {isEditMode ? (
                  <div className="pointer-events-auto max-w-4xl mx-auto">
                    <input className="bg-zinc-900/95 border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-2xl md:text-7xl font-black text-white w-full text-center" value={section.title} onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} />
                  </div>
                ) : (
                  <h2 className="text-4xl md:text-[14rem] font-black text-white/20 leading-none uppercase select-none">{section.title}</h2>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Simulation: Bottom Spacer */}
      {bottomSpacer > 0 && (
        <div style={{ height: `${bottomSpacer}vh` }} className="w-full flex flex-col items-center justify-center border-t border-white/5 bg-zinc-950/50">
           <p className="text-[10px] font-black tracking-widest text-white/20 uppercase mb-4">Simulated Content Below</p>
           <ArrowUp className="text-white/10 animate-bounce" />
        </div>
      )}
    </div>
  );
};

