import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';
import { RefreshCw, Lock, ArrowDown, ArrowUp, LayoutGrid, Scissors, Anchor } from 'lucide-react';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  scrollDepth?: number;
  startOffset?: number;
  endOffset?: number;
  topSpacer?: number;
  bottomSpacer?: number;
  widthMode?: 'full' | 'boxed';
  videoTrimStart?: number;
  videoTrimEnd?: number;
  viewportAnchor?: number;
  topContentLabel?: string;
  bottomContentLabel?: string;
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  scrollDepth = 8,
  startOffset = 0,
  endOffset = 0,
  topSpacer = 0,
  bottomSpacer = 0,
  widthMode = 'full',
  videoTrimStart = 0,
  videoTrimEnd = 1,
  viewportAnchor = 0,
  topContentLabel = "BEFORE",
  bottomContentLabel = "AFTER",
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.load();
    video.oncanplay = () => { setIsLoaded(true); video.currentTime = 0; };
  }, [videoUrl]);

  useEffect(() => {
    const animate = () => {
      currentProgress.current += (targetProgress.current - currentProgress.current) * 0.1;
      const progress = currentProgress.current;
      const activeRange = 1 - startOffset - endOffset;
      const narrativeProgress = Math.max(0, Math.min(1, (progress - startOffset) / activeRange));

      if (videoRef.current && videoRef.current.readyState >= 2 && !isSeeking.current) {
        // APPLY TRIM AUTHORITY
        const fullDuration = videoRef.current.duration;
        const startTime = fullDuration * videoTrimStart;
        const endTime = fullDuration * videoTrimEnd;
        const spanDuration = endTime - startTime;

        const targetTime = startTime + (spanDuration - 0.1) * narrativeProgress;

        if (Math.abs(videoRef.current.currentTime - targetTime) > 0.05) {
          isSeeking.current = true;
          videoRef.current.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;
        const d = Math.abs(narrativeProgress - section.triggerTime);
        const op = Math.max(0, 1 - (d / 0.12));
        el.style.opacity = op.toString();
        el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
        el.style.transform = `translate3d(0, ${(narrativeProgress - section.triggerTime) * 100}px, 0)`;
      });
      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const total = containerRef.current.offsetHeight - window.innerHeight;

      // APPLY ANCHOR AUTHORITY
      const triggerPoint = window.innerHeight * viewportAnchor;
      if (total > 0) targetProgress.current = Math.max(0, Math.min(1, (triggerPoint - rect.top) / total));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);
    return () => { window.removeEventListener('scroll', handleScroll); cancelAnimationFrame(rafid); };
  }, [sections, startOffset, endOffset, videoTrimStart, videoTrimEnd, viewportAnchor]);

  return (
    <div className="w-full bg-[#050505]">
      {topSpacer > 0 && (
        <div style={{ height: `${topSpacer}vh` }} className="w-full flex flex-col items-center justify-center bg-zinc-950/20 border-b border-white/5 relative">
           <ArrowDown className="text-white/10 mb-4 animate-bounce" size={24} />
           <p className="text-[10px] font-black tracking-[0.5em] text-white/20 uppercase">{topContentLabel}</p>
        </div>
      )}

      <div ref={containerRef} className={`relative w-full overflow-visible mx-auto transition-all duration-700 ${widthMode === 'boxed' ? 'max-w-7xl px-4 md:px-12 py-12' : 'max-w-none'}`} style={{ height: `${scrollDepth * 100}vh` }}>
        <div className={`sticky top-0 left-0 w-full h-screen overflow-hidden z-0 transition-all duration-700 ${widthMode === 'boxed' ? 'rounded-[3rem] shadow-[0_0_100px_rgba(0,0,0,0.5)] border border-white/10' : ''}`}>

          {isEditMode && (
            <div className="absolute top-4 right-4 z-50 flex flex-col gap-2">
               <div className="bg-indigo-600/80 backdrop-blur px-3 py-1.5 rounded-full flex items-center gap-2 border border-indigo-400/50 shadow-xl">
                  <Scissors size={12}/>
                  <span className="text-[8px] font-black uppercase tracking-widest">Trim: {Math.round(videoTrimStart*100)}% - {Math.round(videoTrimEnd*100)}%</span>
               </div>
               <div className="bg-indigo-600/80 backdrop-blur px-3 py-1.5 rounded-full flex items-center gap-2 border border-indigo-400/50 shadow-xl">
                  <Anchor size={12}/>
                  <span className="text-[8px] font-black uppercase tracking-widest">Anchor: {Math.round(viewportAnchor*100)}%</span>
               </div>
            </div>
          )}

          <div className="absolute inset-0 bg-black">
            <video ref={videoRef} src={videoUrl} onSeeked={() => isSeeking.current = false} playsInline muted preload="auto" className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} />
          </div>

          <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
            {sections.map((section, idx) => (
              <div key={idx} ref={(el) => { sectionRefs.current[idx] = el; }} className="absolute w-full px-6 md:px-20" style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}>
                {isEditMode ? (
                  <div className="pointer-events-auto max-w-4xl mx-auto"><input className="bg-zinc-900/95 border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-2xl md:text-7xl font-black text-white w-full text-center" value={section.title} onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} /></div>
                ) : (
