import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  scrollDepth?: number;
  startOffset?: number;
  endOffset?: number;
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  scrollDepth = 8,
  startOffset = 0.05,
  endOffset = 0.05,
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.load();
    video.oncanplay = () => { setIsLoaded(true); video.currentTime = 0; };
  }, [videoUrl]);

  useEffect(() => {
    const animate = () => {
      currentProgress.current += (targetProgress.current - currentProgress.current) * 0.1;
      const progress = currentProgress.current;
      const activeRange = 1 - startOffset - endOffset;
      const narrativeProgress = Math.max(0, Math.min(1, (progress - startOffset) / activeRange));

      if (videoRef.current && videoRef.current.readyState >= 2 && !isSeeking.current) {
        const targetTime = (videoRef.current.duration - 0.1) * narrativeProgress;
        if (Math.abs(videoRef.current.currentTime - targetTime) > 0.05) {
          isSeeking.current = true;
          videoRef.current.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;
        const d = Math.abs(narrativeProgress - section.triggerTime);
        const op = Math.max(0, 1 - (d / 0.15));
        el.style.opacity = op.toString();
        el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
        el.style.transform = `translate3d(0, ${(narrativeProgress - section.triggerTime) * 120}px, 0)`;
      });
      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const total = containerRef.current.offsetHeight - window.innerHeight;
      if (total > 0) targetProgress.current = Math.max(0, Math.min(1, -rect.top / total));
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);
    return () => { window.removeEventListener('scroll', handleScroll); cancelAnimationFrame(rafid); };
  }, [sections, startOffset, endOffset]);

  return (
    <div ref={containerRef} className="relative w-full overflow-visible" style={{ height: `${scrollDepth * 100}vh` }}>
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">
        <div className="absolute inset-0 bg-black">
          <video 
            ref={videoRef} 
            src={videoUrl} 
            onSeeked={() => isSeeking.current = false} 
            playsInline 
            muted 
            preload="auto" 
            className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/60 pointer-events-none" />
          {!isLoaded && <div className="absolute inset-0 flex items-center justify-center bg-black"><div className="w-12 h-12 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" /></div>}
        </div>

        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div key={idx} ref={(el) => { sectionRefs.current[idx] = el; }} className="absolute w-full max-w-7xl mx-auto px-12" style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}>
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-4xl mx-auto">
                  <input 
                    className="bg-black/80 backdrop-blur-xl border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-4xl md:text-8xl font-black text-white w-full text-center tracking-tighter uppercase" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                </div>
              ) : (
                <div className="space-y-4">
                  <h2 className="text-6xl md:text-[12rem] font-black text-white leading-none uppercase select-none tracking-tighter">{section.title}</h2>
                  <p className="text-white/40 text-sm md:text-lg max-w-lg mx-auto font-medium tracking-wide uppercase">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import { ScrollSection } from "../types";

export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.15,
  scrollDepth: number = 4,
  startOffset: number = 0.05,
  endOffset: number = 0.05
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_PUBLIC_VIDEO_URL_HERE.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  return `
<!-- AEON NARRATIVE MODULE: [${instanceId}] -->
<div id="${instanceId}-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible;">
    <style>
        #${instanceId}-track { font-family: sans-serif; contain: paint; }
        #${instanceId}-track .aeon-s { position: sticky; top: 0; left: 0; width: 100%; height: 100vh; overflow: hidden; display: flex; align-items: center; justify-content: center; }
        #${instanceId}-track .aeon-v { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; filter: contrast(1.1) brightness(0.9); z-index: 1; }
        #${instanceId}-track .aeon-o { position: absolute; inset: 0; z-index: 2; display: flex; align-items: center; justify-content: center; pointer-events: none; }
        #${instanceId}-track .aeon-t { position: absolute; width: 100%; padding: 0 8%; opacity: 0; visibility: hidden; transition: opacity 0.3s ease; will-change: transform, opacity; }
        #${instanceId}-track .aeon-h { font-size: clamp(3rem, 12vw, 15rem); font-weight: 900; text-transform: uppercase; line-height: 0.8; letter-spacing: -0.05em; color: white; margin: 0; }
        #${instanceId}-track .aeon-d { font-size: 14px; font-weight: 700; text-transform: uppercase; color: rgba(255,255,255,0.4); margin-top: 20px; letter-spacing: 0.2em; }
        #${instanceId}-track .aeon-l { position: absolute; inset: 0; z-index: 10; background: #000; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 10px; font-weight: 900; letter-spacing: 0.5em; transition: opacity 0.8s ease; }
    </style>
    <div class="aeon-s">
        <div id="${instanceId}-l" class="aeon-l">AEON_INITIALIZING</div>
        <video id="${instanceId}-v" class="aeon-v" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-o"></div>
    </div>
    <script>
        (function() {
            const C = { src: "${displayUrl}", data: ${sectionsJSON}, lerp: ${sensitivity}, id: "${instanceId}", s: ${startOffset}, e: ${endOffset} };
            const track = document.getElementById(C.id + '-track');
            const video = document.getElementById(C.id + '-v');
            const stage = document.getElementById(C.id + '-g');
            const loader = document.getElementById(C.id + '-l');
            video.src = C.src;
            C.data.forEach((s, i) => {
                const d = document.createElement('div');
                d.className = 'aeon-t'; d.id = C.id + '-t-' + i;
                d.style.textAlign = s.alignment;
                d.innerHTML = \`<h2 class="aeon-h">\${s.title}</h2><p class="aeon-d">\${s.description}</p>\`;
                stage.appendChild(d);
            });
            let tR = 0, cR = 0, seek = false, active = false;
            const obs = new IntersectionObserver((es) => { active = es[0].isIntersecting; }, { threshold: 0 });
            obs.observe(track);
            function loop() {
                if (!active) return requestAnimationFrame(loop);
                cR += (tR - cR) * C.lerp;
                const range = 1 - C.s - C.e;
                const p = Math.max(0, Math.min(1, (cR - C.s) / range));
                if (video.duration && !seek) {
                    const t = (video.duration - 0.1) * p;
                    if (Math.abs(video.currentTime - t) > 0.05) { seek = true; video.currentTime = t; }
                }
                C.data.forEach((s, i) => {
                    const el = document.getElementById(C.id + '-t-' + i);
                    if (!el) return;
                    const d = Math.abs(p - s.triggerTime);
                    const op = Math.max(0, 1 - (d / 0.15));
                    el.style.opacity = op; el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(p - s.triggerTime) * 120}px, 0)\`;
                });
                requestAnimationFrame(loop);
            }
            function sync() {
                const rect = track.getBoundingClientRect();
                const total = track.offsetHeight - window.innerHeight;
                if (total > 0) tR = Math.max(0, Math.min(1, -rect.top / total));
            }
            video.onseeked = () => seek = false;
            window.addEventListener('scroll', sync, { passive: true });
            video.onloadedmetadata = () => { loader.style.opacity = '0'; sync(); loop(); };
            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>`;
}

export interface ScrollSection {
  title: string;
  description: string;
  triggerTime: number; // 0 to 1 scale
  alignment: 'left' | 'right' | 'center';
  vibe: 'cinematic' | 'minimal' | 'energetic';
}

export interface VideoState {
  url: string | null;
  duration: number;
  sections: ScrollSection[];
  isAnalyzing: boolean;
  brandName: string;
  sensitivity: number;
  scrollDepth: number;
  startOffset: number; 
  endOffset: number;
  // Positioning Authority properties
  viewportAnchor: number; // 0 = Top of screen, 0.5 = Center, 1 = Bottom
  widthMode: 'full' | 'boxed';
  topSpacer: number; // For previewing context
  bottomSpacer: number; // For previewing context
}

import { ScrollSection } from "../types";

/**
 * AEON UNIVERSAL NARRATIVE EXPORT v15.0
 * Generates a self-contained, position-aware component.
 */
export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.15,
  scrollDepth: number = 4,
  startOffset: number = 0.05,
  endOffset: number = 0.05,
  viewportAnchor: number = 0,
  widthMode: 'full' | 'boxed' = 'full'
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_PUBLIC_VIDEO_URL_HERE.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  const containerStyles = widthMode === 'boxed' 
    ? `max-width: 1200px; margin: 80px auto; border-radius: 40px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 40px 100px -20px rgba(0,0,0,0.8);` 
    : `width: 100%; margin: 0;`;

  return `
<!-- 
  AEON NARRATIVE MODULE [${instanceId}]
  IMPLEMENTATION GUIDE:
  1. This snippet is self-contained (HTML/CSS/JS).
  2. PASTE ANYWHERE: It uses relative viewport anchoring, so you can place it 
     at the top, middle, or bottom of your page.
  3. ASSET: Update the 'src' variable in the script if you move the video file.
-->

<div id="${instanceId}-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible; ${containerStyles}">
    <style>
        /* SCROLL CONTAINER SYSTEM */
        #${instanceId}-track { font-family: 'Inter', sans-serif; contain: paint; }

        /* THE STICKY STAGE: Stays fixed while the parent tracks scrolls */
        #${instanceId}-track .aeon-s { 
            position: sticky; top: 0; left: 0; width: 100%; height: 100vh; 
            overflow: hidden; display: flex; align-items: center; justify-content: center; 
        }

        /* CINEMATIC VIDEO ENGINE */
        #${instanceId}-track .aeon-v { 
            position: absolute; inset: 0; width: 100%; height: 100%; 
            object-fit: cover; filter: contrast(1.1) brightness(0.9); z-index: 1; 
        }

        /* TEXT OVERLAY LAYER */
        #${instanceId}-track .aeon-o { 
            position: absolute; inset: 0; z-index: 2; 
            display: flex; align-items: center; justify-content: center; pointer-events: none; 
        }

        /* INDIVIDUAL NARRATIVE NODES */
        #${instanceId}-track .aeon-t { 
            position: absolute; width: 100%; padding: 0 10%; 
            opacity: 0; visibility: hidden; transition: opacity 0.3s ease; will-change: transform, opacity; 
        }

        #${instanceId}-track .aeon-h { 
            font-size: clamp(3rem, 12vw, 12rem); font-weight: 900; 
            text-transform: uppercase; line-height: 0.8; letter-spacing: -0.05em; color: white; margin: 0; 
        }

        #${instanceId}-track .aeon-d { 
            font-size: 14px; font-weight: 700; text-transform: uppercase; 
            color: rgba(255,255,255,0.4); margin-top: 24px; letter-spacing: 0.3em; 
        }

        /* STATUS LOADER */
        #${instanceId}-track .aeon-l { 
            position: absolute; inset: 0; z-index: 10; background: #000; 
            display: flex; align-items: center; justify-content: center; 
            color: #fff; font-size: 10px; font-weight: 900; letter-spacing: 0.5em; transition: opacity 0.8s ease; 
        }
    </style>

    <div class="aeon-s">
        <div id="${instanceId}-l" class="aeon-l">SYSTEM_SYNCING</div>
        <video id="${instanceId}-v" class="aeon-v" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-o"></div>
    </div>

    <script>
        (function() {
            /**
             * CONFIGURATION BLUEPRINT
             * Edit these parameters to refine the behavior manually
             */
            const CONFIG = { 
                src: "${displayUrl}", 
                data: ${sectionsJSON}, 
                lerp: ${sensitivity}, 
                id: "${instanceId}", 
                startBuffer: ${startOffset}, 
                endBuffer: ${endOffset},
                anchor: ${viewportAnchor} // 0 = triggers at top, 0.5 = center
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-v');
            const stage = document.getElementById(CONFIG.id + '-g');
            const loader = document.getElementById(CONFIG.id + '-l');

            video.src = CONFIG.src;

            // Initialize Narrative Nodes
            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-t'; 
                node.id = CONFIG.id + '-t-' + i;
                node.style.textAlign = s.alignment;
                node.innerHTML = \`<h2 class="aeon-h">\${s.title}</h2><p class="aeon-d">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0;
            let currentProgress = 0;
            let isSeeking = false;
            let isVisible = false;

            // Performance: Only run logic when section is in view
            const observer = new IntersectionObserver((entries) => {
                isVisible = entries[0].isIntersecting;
            }, { threshold: 0 });
            observer.observe(track);

            function update() {
                if (!isVisible) return requestAnimationFrame(update);

                // Smooth interpolation (Lerp)
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;

                // Map progress to active narrative range
                const range = 1 - CONFIG.startBuffer - CONFIG.endBuffer;
                const progress = Math.max(0, Math.min(1, (currentProgress - CONFIG.startBuffer) / range));

                // Sync Video Time
                if (video.duration && !isSeeking) {
                    const time = (video.duration - 0.1) * progress;
                    if (Math.abs(video.currentTime - time) > 0.05) {
                        isSeeking = true;
                        video.currentTime = time;
                    }
                }

                // Animate Text Sections
                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-t-' + i);
                    if (!el) return;

                    const dist = Math.abs(progress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.15));

                    el.style.opacity = opacity;
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(progress - s.triggerTime) * 150}px, 0)\`;
                });

                requestAnimationFrame(update);
            }

            // Calculate progress based on element position relative to viewport
            function onScroll() {
                const rect = track.getBoundingClientRect();
                const totalHeight = track.offsetHeight - window.innerHeight;

                // Relative calculation: works regardless of where the element is in the DOM
                const triggerPoint = window.innerHeight * CONFIG.anchor;
                if (totalHeight > 0) {
                    targetProgress = Math.max(0, Math.min(1, (triggerPoint - rect.top) / totalHeight));
                }
            }

            video.onseeked = () => isSeeking = false;
            window.addEventListener('scroll', onScroll, { passive: true });

            video.onloadedmetadata = () => {
                loader.style.opacity = '0';
                onScroll();
                update();
            };

            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>`;
}

