                  <input 
                    className="bg-black/80 backdrop-blur-xl border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-4xl md:text-8xl font-black text-white w-full text-center tracking-tighter uppercase focus:border-white transition-all" 
