import { ScrollSection } from "../types";

/**
 * AEON UNIVERSAL NARRATIVE EXPORT v16.0
 * Generates a self-contained, position-aware component.
 */
export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.15,
  scrollDepth: number = 4,
  startOffset: number = 0.05,
  endOffset: number = 0.05,
  viewportAnchor: number = 0,
  widthMode: 'full' | 'boxed' = 'full',
  maxWidth: string = '1200px'
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'PASTE_YOUR_PUBLIC_VIDEO_URL_HERE.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  const containerStyles = widthMode === 'boxed' 
    ? `max-width: ${maxWidth}; margin: 80px auto; border-radius: 40px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 40px 100px -20px rgba(0,0,0,0.8);` 
    : `width: 100%; margin: 0;`;

  return `
<!-- 
  AEON NARRATIVE MODULE [${instanceId}]
  DESIGNATED SPACE IMPLEMENTATION GUIDE:
  1. PASTE ANYWHERE: This element tracks its own position relative to the viewport.
  2. TRIGGER ANCHOR: Configured to trigger when the top of this container reaches ${Math.round(viewportAnchor * 100)}% of your screen height.
  3. CONTAINER SPACE: The height of this container (${scrollDepth * 100}vh) dictates how long the user scrolls through the narrative.
-->

<div id="${instanceId}-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible; ${containerStyles}">
    <style>
        /* SCROLL CONTAINER SYSTEM */
        #${instanceId}-track { font-family: 'Inter', sans-serif; contain: paint; }

        /* THE STICKY STAGE: Locked within the track */
        #${instanceId}-track .aeon-s { 
            position: sticky; top: 0; left: 0; width: 100%; height: 100vh; 
            overflow: hidden; display: flex; align-items: center; justify-content: center; 
        }

        /* CINEMATIC VIDEO ENGINE */
        #${instanceId}-track .aeon-v { 
            position: absolute; inset: 0; width: 100%; height: 100%; 
            object-fit: cover; filter: contrast(1.1) brightness(0.9); z-index: 1; 
        }

        /* TEXT OVERLAY LAYER */
        #${instanceId}-track .aeon-o { 
            position: absolute; inset: 0; z-index: 2; 
            display: flex; align-items: center; justify-content: center; pointer-events: none; 
        }

        /* NARRATIVE NODES */
        #${instanceId}-track .aeon-t { 
            position: absolute; width: 100%; padding: 0 10%; 
            opacity: 0; visibility: hidden; transition: opacity 0.3s ease; will-change: transform, opacity; 
        }

        #${instanceId}-track .aeon-h { 
            font-size: clamp(2rem, 10vw, 10rem); font-weight: 900; 
            text-transform: uppercase; line-height: 0.85; letter-spacing: -0.05em; color: white; margin: 0; 
        }

        #${instanceId}-track .aeon-d { 
            font-size: 14px; font-weight: 700; text-transform: uppercase; 
            color: rgba(255,255,255,0.4); margin-top: 24px; letter-spacing: 0.3em; 
        }

        /* SYSTEM LOADER */
        #${instanceId}-track .aeon-l { 
            position: absolute; inset: 0; z-index: 10; background: #000; 
            display: flex; align-items: center; justify-content: center; 
            color: #fff; font-size: 10px; font-weight: 900; letter-spacing: 0.5em; transition: opacity 0.8s ease; 
        }
    </style>

    <div class="aeon-s">
        <div id="${instanceId}-l" class="aeon-l">AEON_SYNCING_SOURCE</div>
        <video id="${instanceId}-v" class="aeon-v" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-o"></div>
    </div>

    <script>
        (function() {
            /**
             * POSITION-AWARE CONFIG
             */
            const CONFIG = { 
                src: "${displayUrl}", 
                data: ${sectionsJSON}, 
                lerp: ${sensitivity}, 
                id: "${instanceId}", 
                startBuffer: ${startOffset}, 
                endBuffer: ${endOffset},
                viewportAnchor: ${viewportAnchor} // Trigger point relative to screen height
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-v');
            const stage = document.getElementById(CONFIG.id + '-g');
            const loader = document.getElementById(CONFIG.id + '-l');

            video.src = CONFIG.src;

            // Build Nodes
            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-t'; 
                node.id = CONFIG.id + '-t-' + i;
                node.style.textAlign = s.alignment;
                node.innerHTML = \`<h2 class="aeon-h">\${s.title}</h2><p class="aeon-d">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0;
            let currentProgress = 0;
            let isSeeking = false;
            let isVisible = false;

            const observer = new IntersectionObserver((entries) => {
                isVisible = entries[0].isIntersecting;
            }, { threshold: 0 });
            observer.observe(track);

            function update() {
                if (!isVisible) return requestAnimationFrame(update);

                // Motion Smoothing
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;

                // Active Range Calculation
                const range = 1 - CONFIG.startBuffer - CONFIG.endBuffer;
                const narrativeProgress = Math.max(0, Math.min(1, (currentProgress - CONFIG.startBuffer) / range));

                // Frame Scrubbing
                if (video.duration && !isSeeking) {
                    const time = (video.duration - 0.1) * narrativeProgress;
                    if (Math.abs(video.currentTime - time) > 0.05) {
                        isSeeking = true;
                        video.currentTime = time;
                    }
                }

                // Node Animation
                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-t-' + i);
                    if (!el) return;

                    const dist = Math.abs(narrativeProgress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.15));

                    el.style.opacity = opacity;
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(narrativeProgress - s.triggerTime) * 150}px, 0)\`;
                });

                requestAnimationFrame(update);
            }

            // The 'Designated Space' logic:
            function onScroll() {
                const rect = track.getBoundingClientRect();
                const totalHeight = track.offsetHeight - window.innerHeight;

                // This relative trigger allows it to live anywhere in your DOM
                const triggerPoint = window.innerHeight * CONFIG.viewportAnchor;
                if (totalHeight > 0) {
                    targetProgress = Math.max(0, Math.min(1, (triggerPoint - rect.top) / totalHeight));
                }
            }

            video.onseeked = () => isSeeking = false;
            window.addEventListener('scroll', onScroll, { passive: true });

            video.onloadedmetadata = () => {
                loader.style.opacity = '0';
                onScroll();
                update();
            };

            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>`;
}

import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  scrollDepth?: number;
  startOffset?: number;
  endOffset?: number;
  viewportAnchor?: number;
  widthMode?: 'full' | 'boxed';
  maxWidth?: string;
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  scrollDepth = 8,
  startOffset = 0.05,
  endOffset = 0.05,
  viewportAnchor = 0,
  widthMode = 'full',
  maxWidth = '1200px',
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.load();
    video.oncanplay = () => { setIsLoaded(true); video.currentTime = 0; };
  }, [videoUrl]);

  useEffect(() => {
    const animate = () => {
      currentProgress.current += (targetProgress.current - currentProgress.current) * 0.1;
      const progress = currentProgress.current;
      const activeRange = 1 - startOffset - endOffset;
      const narrativeProgress = Math.max(0, Math.min(1, (progress - startOffset) / activeRange));

      if (videoRef.current && videoRef.current.readyState >= 2 && !isSeeking.current) {
        const targetTime = (videoRef.current.duration - 0.1) * narrativeProgress;
        if (Math.abs(videoRef.current.currentTime - targetTime) > 0.05) {
          isSeeking.current = true;
          videoRef.current.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;
        const d = Math.abs(narrativeProgress - section.triggerTime);
        const op = Math.max(0, 1 - (d / 0.15));
        el.style.opacity = op.toString();
        el.style.visibility = op > 0.01 ? 'visible' : 'hidden';
        el.style.transform = `translate3d(0, ${(narrativeProgress - section.triggerTime) * 150}px, 0)`;
      });
      requestAnimationFrame(animate);
    };

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const total = containerRef.current.offsetHeight - window.innerHeight;
      const triggerPoint = window.innerHeight * viewportAnchor;

      if (total > 0) {
        targetProgress.current = Math.max(0, Math.min(1, (triggerPoint - rect.top) / total));
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    const rafid = requestAnimationFrame(animate);
    return () => { window.removeEventListener('scroll', handleScroll); cancelAnimationFrame(rafid); };
  }, [sections, startOffset, endOffset, viewportAnchor]);

  const containerStyles = widthMode === 'boxed' 
    ? { maxWidth: maxWidth, margin: '40px auto', borderRadius: '40px', border: '1px solid rgba(255,255,255,0.1)', boxShadow: '0 40px 100px -20px rgba(0,0,0,0.8)', overflow: 'hidden' }
    : { width: '100%' };

  return (
    <div ref={containerRef} className="relative overflow-visible transition-all duration-500" style={{ height: `${scrollDepth * 100}vh`, ...containerStyles }}>
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0">
        <div className="absolute inset-0 bg-black">
          <video 
            ref={videoRef} 
            src={videoUrl} 
            onSeeked={() => isSeeking.current = false} 
            playsInline 
            muted 
            preload="auto" 
            className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
          />
          <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/60 pointer-events-none" />
          {!isLoaded && <div className="absolute inset-0 flex items-center justify-center bg-black"><div className="w-12 h-12 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" /></div>}
        </div>

        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div key={idx} ref={(el) => { sectionRefs.current[idx] = el; }} className="absolute w-full max-w-7xl mx-auto px-12" style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}>
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-4xl mx-auto space-y-4">
                   <div className="flex justify-center bg-black/40 p-2 rounded-t-xl border-x border-t border-white/10">
                      <input 
                        type="range" min="0" max="1" step="0.01" value={section.triggerTime} 
                        onChange={(e) => onUpdateSection?.(idx, { ...section, triggerTime: parseFloat(e.target.value) })}
                        className="w-full max-w-xs accent-indigo-500 h-1"
                      />
                   </div>
                  <input 
                    className="bg-black/80 backdrop-blur-xl border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-4xl md:text-8xl font-black text-white w-full text-center tracking-tighter uppercase focus:border-white transition-all shadow-2xl" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                  <textarea 
                    className="bg-black/60 backdrop-blur-lg border border-white/10 p-4 rounded-xl outline-none text-sm font-bold text-white/50 w-full text-center tracking-widest uppercase mt-4 resize-none"
                    value={section.description}
                    onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    rows={2}
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  <h2 className="text-6xl md:text-[12rem] font-black text-white leading-none uppercase select-none tracking-tighter">{section.title}</h2>
                  <p className="text-white/40 text-sm md:text-xl max-w-2xl mx-auto font-black tracking-[0.3em] uppercase">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

