import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  sensitivity?: number;
  scrollDepth?: number;
  startOffset?: number;
  endOffset?: number;
  viewportAnchor?: number;
  widthMode?: 'full' | 'boxed';
  maxWidth?: string;
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  sensitivity = 0.15,
  scrollDepth = 8,
  startOffset = 0.05,
  endOffset = 0.05,
  viewportAnchor = 0,
  widthMode = 'full',
  maxWidth = '1200px',
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);
  const targetProgress = useRef(0);
  const currentProgress = useRef(0);

  // Re-initialize video on source change
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.load();
    video.onloadedmetadata = () => { 
      setIsLoaded(true); 
      video.currentTime = 0; 
      handleScroll(); // Initial sync
    };
  }, [videoUrl]);

  const handleScroll = () => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const totalScrollableHeight = containerRef.current.offsetHeight - window.innerHeight;
    const triggerPoint = window.innerHeight * viewportAnchor;

    if (totalScrollableHeight > 0) {
      // Progress calculation relative to the designated trigger point
      const rawProgress = (triggerPoint - rect.top) / totalScrollableHeight;
      targetProgress.current = Math.max(0, Math.min(1, rawProgress));
    }
  };

  useEffect(() => {
    let rafId: number;

    const animate = () => {
      // Use the user-defined sensitivity for smooth lerping
      currentProgress.current += (targetProgress.current - currentProgress.current) * sensitivity;

      const progress = currentProgress.current;

      // Calculate the active narrative window based on start/end offsets
      const activeRange = 1 - startOffset - endOffset;
      const narrativeProgress = Math.max(0, Math.min(1, (progress - startOffset) / activeRange));

      // Video Scrubbing Engine
      if (videoRef.current && videoRef.current.duration) {
        const targetTime = (videoRef.current.duration - 0.1) * narrativeProgress;
        // Small threshold to avoid redundant seeks
        if (Math.abs(videoRef.current.currentTime - targetTime) > 0.01) {
          videoRef.current.currentTime = targetTime;
        }
      }

      // Narrative Node Animations
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(narrativeProgress - section.triggerTime);
        const opacity = Math.max(0, 1 - (distance / 0.15));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        // Vertical parallax based on proximity to trigger time
        const yOffset = (narrativeProgress - section.triggerTime) * 150;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      rafId = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    rafId = requestAnimationFrame(animate);

    return () => { 
      window.removeEventListener('scroll', handleScroll); 
      cancelAnimationFrame(rafId); 
    };
  }, [sections, startOffset, endOffset, viewportAnchor, sensitivity]);

  const containerStyles = widthMode === 'boxed' 
    ? { maxWidth: maxWidth, margin: '40px auto', borderRadius: '40px', border: '1px solid rgba(255,255,255,0.1)', boxShadow: '0 40px 100px -20px rgba(0,0,0,0.8)', overflow: 'hidden' }
    : { width: '100%' };

  return (
    <div ref={containerRef} className="relative overflow-visible transition-all duration-500" style={{ height: `${scrollDepth * 100}vh`, ...containerStyles }}>

      {/* Precision Anchor Guide - Only visible during architecture/edit */}
      {isEditMode && (
        <div 
          className="fixed left-0 w-full border-t border-indigo-500/50 z-[150] pointer-events-none transition-all duration-300"
          style={{ top: `${viewportAnchor * 100}%` }}
        >
          <div className="absolute right-4 top-2 bg-indigo-600/90 backdrop-blur-md text-[8px] font-black px-3 py-1.5 rounded-full text-white uppercase tracking-widest shadow-xl border border-white/10">
            Anchor Point: {Math.round(viewportAnchor * 100)}%
          </div>
        </div>
      )}

      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0 bg-black">
        <video 
          ref={videoRef} 
          src={videoUrl} 
          playsInline 
          muted 
          preload="auto" 
          className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-transparent to-black/80 pointer-events-none" />

        {!isLoaded && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-10 h-10 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        {/* Narrative Nodes Overlay */}
        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div 
              key={idx} 
              ref={(el) => { sectionRefs.current[idx] = el; }} 
              className="absolute w-full max-w-7xl mx-auto px-12 transition-none" 
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-4xl mx-auto space-y-4">
                   <div className="flex flex-col gap-2 bg-black/40 backdrop-blur-md p-4 rounded-t-2xl border-x border-t border-white/10">
                      <div className="flex justify-between items-center text-[8px] font-black text-white/40 uppercase tracking-widest">
                        <span>Node Sync</span>
                        <span>{Math.round(section.triggerTime * 100)}%</span>
                      </div>
                      <input 
                        type="range" min="0" max="1" step="0.01" value={section.triggerTime} 
                        onChange={(e) => onUpdateSection?.(idx, { ...section, triggerTime: parseFloat(e.target.value) })}
                        className="w-full accent-indigo-500 h-1 bg-white/10 rounded-full appearance-none cursor-pointer"
                      />
                   </div>
                  <input 
                    className="bg-black/80 backdrop-blur-xl border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-4xl md:text-8xl font-black text-white w-full text-center tracking-tighter uppercase focus:border-white transition-all shadow-2xl" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                  <textarea 
                    className="bg-black/60 backdrop-blur-lg border border-white/10 p-4 rounded-xl outline-none text-sm font-bold text-white/50 w-full text-center tracking-widest uppercase mt-4 resize-none"
                    value={section.description}
                    onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    rows={2}
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  <h2 className="text-6xl md:text-[12rem] font-black text-white leading-none uppercase select-none tracking-tighter drop-shadow-2xl">{section.title}</h2>
                  <p className="text-white/40 text-sm md:text-xl max-w-2xl mx-auto font-black tracking-[0.3em] uppercase">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

