            </button>
            <div className="w-[1px] h-6 bg-white/10 mx-2" />
            <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 px-5 py-2.5 bg-white text-black rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-indigo-50 transition-all active:scale-95"><Terminal size={14} /> <span>Get Code</span></button>
