import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  onUpdateSection, 
  isEditMode 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  // Constants for the "perfect" feel
  const LERP_FRICTION = 0.08; 
  const SCROLL_DEPTH = 6;
  const VIEWPORT_ANCHOR = 0; // Trigger at top of screen

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.load();
    video.onloadedmetadata = () => { 
      setIsLoaded(true); 
      video.currentTime = 0; 
    };
  }, [videoUrl]);

  useEffect(() => {
    let rafId: number;

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollableHeight = containerRef.current.offsetHeight - window.innerHeight;
      const triggerPoint = window.innerHeight * VIEWPORT_ANCHOR;

      if (totalScrollableHeight > 0) {
        const rawProgress = (triggerPoint - rect.top) / totalScrollableHeight;
        targetProgress.current = Math.max(0, Math.min(1, rawProgress));
      }
    };

    const animate = () => {
      // Smooth interpolation
      currentProgress.current += (targetProgress.current - currentProgress.current) * LERP_FRICTION;
      const progress = currentProgress.current;

      // Video Scrubbing - PERFORMANCE FIX
      // We only seek if:
      // 1. The video is loaded
      // 2. We aren't ALREADY seeking (prevents frame queue lag)
      // 3. The change is significant (> 1/60th of a second roughly)
      if (videoRef.current && isLoaded && !isSeeking.current) {
        const targetTime = (videoRef.current.duration - 0.05) * progress;
        if (Math.abs(videoRef.current.currentTime - targetTime) > 0.03) {
          isSeeking.current = true;
          videoRef.current.currentTime = targetTime;
        }
      }

      // Narrative Node Animations
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const opacity = Math.max(0, 1 - (distance / 0.12));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      rafId = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    rafId = requestAnimationFrame(animate);

    return () => { 
      window.removeEventListener('scroll', handleScroll); 
      cancelAnimationFrame(rafId); 
    };
  }, [sections, isLoaded]);

  return (
    <div 
      ref={containerRef} 
      className="relative overflow-visible" 
      style={{ height: `${SCROLL_DEPTH * 100}vh` }}
    >
      <div className="sticky top-0 left-0 w-full h-screen overflow-hidden z-0 bg-black">
        <video 
          ref={videoRef} 
          src={videoUrl} 
          onSeeked={() => { isSeeking.current = false; }} 
          playsInline 
          muted 
          preload="auto" 
          className={`w-full h-full object-cover transition-opacity duration-700 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-transparent to-black/60 pointer-events-none" />

        {!isLoaded && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div 
              key={idx} 
              ref={(el) => { sectionRefs.current[idx] = el; }} 
              className="absolute w-full max-w-7xl mx-auto px-12" 
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-3xl mx-auto space-y-4">
                  <div className="bg-black/60 backdrop-blur-md p-3 rounded-t-2xl border-x border-t border-white/10 flex flex-col gap-2">
                    <span className="text-[7px] font-black text-indigo-400 uppercase tracking-widest text-center">Synchronize Frame</span>
                    <input 
                      type="range" min="0" max="1" step="0.01" value={section.triggerTime} 
                      onChange={(e) => onUpdateSection?.(idx, { ...section, triggerTime: parseFloat(e.target.value) })}
                      className="w-full accent-indigo-500 h-1 bg-white/10 rounded-full appearance-none cursor-pointer"
                    />
                  </div>
                  <input 
                    className="bg-black/80 backdrop-blur-xl border-2 border-indigo-500/50 p-6 rounded-2xl outline-none text-4xl md:text-7xl font-black text-white w-full text-center tracking-tighter uppercase focus:border-white transition-all shadow-2xl" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                  <textarea 
                    className="bg-black/60 backdrop-blur-lg border border-white/10 p-4 rounded-xl outline-none text-xs font-bold text-white/40 w-full text-center tracking-widest uppercase mt-4 resize-none"
                    value={section.description}
                    onChange={(e) => onUpdateSection?.(idx, { ...section, description: e.target.value })}
                    rows={2}
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  <h2 className="text-5xl md:text-[10rem] font-black text-white leading-none uppercase select-none tracking-tighter drop-shadow-2xl">{section.title}</h2>
                  <p className="text-white/40 text-xs md:text-lg max-w-2xl mx-auto font-black tracking-[0.4em] uppercase">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

