/**
 * AEON UNIVERSAL NARRATIVE EXPORT v17.0
 * Generates a high-performance, self-contained interactive component.
 */
export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.08, // Using the optimized studio default
  scrollDepth: number = 6,
  startOffset: number = 0.05,
  endOffset: number = 0.05,
  viewportAnchor: number = 0,
  widthMode: 'full' | 'boxed' = 'full',
  maxWidth: string = '1200px'
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'https://YOUR_DOMAIN.com/path/to/video.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  const containerStyles = widthMode === 'boxed' 
    ? `max-width: ${maxWidth}; margin: 80px auto; border-radius: 40px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 40px 100px -20px rgba(0,0,0,0.8);` 
    : `width: 100%; margin: 0;`;

  return `
<!-- 
  ================================================================
  AEON NARRATIVE MODULE [${instanceId}]
  ================================================================

  HOW TO IMPLEMENT THIS ON YOUR WEBSITE:

  1. PASTE ANYWHERE: 
     Copy this entire block and paste it into the <body> of any HTML file, 
     or inside a "Custom HTML" block in WordPress, Webflow, or Shopify.

  2. !!! REQUIRED ACTION !!!
     Find the line below: 'src: "${displayUrl}"'
     Replace the placeholder URL with your actual public video link (.mp4).

  3. HOW TO CHANGE SCROLL SPEED:
     In the first line of the code, change 'height: ${scrollDepth * 100}vh'.
     - Higher number (e.g., 800vh) = Slower, more cinematic scroll.
     - Lower number (e.g., 300vh) = Faster, punchier scroll.

  4. NO DEPENDENCIES: 
     This code is pure HTML/CSS/JS. No external libraries are required.
  ================================================================
-->

<div id="${instanceId}-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible; ${containerStyles}">
    <style>
        #${instanceId}-track { font-family: 'Inter', -apple-system, sans-serif; contain: paint; }

        /* The Sticky Stage: Keeps video locked while you scroll */
        #${instanceId}-track .aeon-stage { 
            position: sticky; top: 0; left: 0; width: 100%; height: 100vh; 
            overflow: hidden; display: flex; align-items: center; justify-content: center; background: #000;
        }

        #${instanceId}-track .aeon-video { 
            position: absolute; inset: 0; width: 100%; height: 100%; 
            object-fit: cover; z-index: 1; transition: opacity 0.8s ease; opacity: 0;
        }

        #${instanceId}-track .aeon-overlay { 
            position: absolute; inset: 0; z-index: 2; 
            display: flex; align-items: center; justify-content: center; pointer-events: none;
            background: linear-gradient(to bottom, rgba(0,0,0,0.6) 0%, transparent 40%, transparent 60%, rgba(0,0,0,0.6) 100%);
        }

        #${instanceId}-track .aeon-node { 
            position: absolute; width: 100%; padding: 0 10%; 
            opacity: 0; visibility: hidden; will-change: transform, opacity; 
        }

        #${instanceId}-track .aeon-title { 
            font-size: clamp(2.5rem, 10vw, 9rem); font-weight: 900; 
            text-transform: uppercase; line-height: 0.85; letter-spacing: -0.04em; color: white; margin: 0;
            filter: drop-shadow(0 20px 50px rgba(0,0,0,0.5));
        }

        #${instanceId}-track .aeon-desc { 
            font-size: clamp(10px, 1.5vw, 18px); font-weight: 700; text-transform: uppercase; 
            color: rgba(255,255,255,0.4); margin-top: 2rem; letter-spacing: 0.4em; 
        }

        #${instanceId}-track .aeon-loader { 
            position: absolute; inset: 0; z-index: 10; background: #000; 
            display: flex; align-items: center; justify-content: center; 
            color: rgba(255,255,255,0.2); font-size: 10px; font-weight: 900; letter-spacing: 0.5em; transition: opacity 0.5s ease; 
        }
    </style>

    <div class="aeon-stage">
        <div id="${instanceId}-l" class="aeon-loader">SYNCING_ASSETS...</div>
        <video id="${instanceId}-v" class="aeon-video" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-overlay"></div>
    </div>

    <script>
        (function() {
            /**
             * AEON CORE CONFIGURATION
             */
            const CONFIG = { 
                /* ACTION REQUIRED: Paste your public MP4 URL below */
                src: "${displayUrl}", 

                data: ${sectionsJSON}, 
                lerp: ${sensitivity}, 
                id: "${instanceId}", 
                startBuffer: ${startOffset}, 
                endBuffer: ${endOffset},
                viewportAnchor: ${viewportAnchor}
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-v');
            const stage = document.getElementById(CONFIG.id + '-g');
            const loader = document.getElementById(CONFIG.id + '-l');

            video.src = CONFIG.src;

            // Build Narrative Nodes
            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-node'; 
                node.id = CONFIG.id + '-n-' + i;
                node.style.textAlign = s.alignment;
                node.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0;
            let currentProgress = 0;
            let isSeeking = false;
            let isVisible = false;

            // Performance: Only run when in view
            const observer = new IntersectionObserver((entries) => {
                isVisible = entries[0].isIntersecting;
            }, { threshold: 0 });
            observer.observe(track);

            function update() {
                if (!isVisible) return requestAnimationFrame(update);

                // Smooth Motion (LERP)
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;

                const range = 1 - CONFIG.startBuffer - CONFIG.endBuffer;
                const narrativeProgress = Math.max(0, Math.min(1, (currentProgress - CONFIG.startBuffer) / range));

                // Frame Scrubbing Engine (Lag-Free)
                if (video.duration && !isSeeking) {
                    const targetTime = (video.duration - 0.05) * narrativeProgress;
                    if (Math.abs(video.currentTime - targetTime) > 0.03) {
                        isSeeking = true;
                        video.currentTime = targetTime;
                    }
                }

                // UI Transitions
                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-n-' + i);
                    if (!el) return;

                    const dist = Math.abs(narrativeProgress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.12));

                    el.style.opacity = opacity;
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(narrativeProgress - s.triggerTime) * 120}px, 0)\`;
                });

                requestAnimationFrame(update);
            }

            function onScroll() {
                const rect = track.getBoundingClientRect();
                const totalHeight = track.offsetHeight - window.innerHeight;
                const triggerPoint = window.innerHeight * CONFIG.viewportAnchor;

                if (totalHeight > 0) {
                    targetProgress = Math.max(0, Math.min(1, (triggerPoint - rect.top) / totalHeight));
                }
            }

            video.onseeked = () => isSeeking = false;
            window.addEventListener('scroll', onScroll, { passive: true });

            video.onloadedmetadata = () => {
                loader.style.opacity = '0';
                video.style.opacity = '1';
                onScroll();
                update();
            };

            // Safety check for cached videos
            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>
`;
}

