            background: linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.4) 30%, transparent 60%, rgba(0,0,0,0.8) 100%);
            padding-bottom: clamp(60px, 15vh, 180px);
        }
        #${instanceId}-track .aeon-node { 
            position: absolute; width: 100%; padding: 0 8%; 
            opacity: 0; visibility: hidden; will-change: transform, opacity;
        }
        #${instanceId}-track .aeon-title { 
            font-size: clamp(2.2rem, 12vw, 8.5rem); font-weight: 900; 
            text-transform: uppercase; line-height: 0.85; letter-spacing: -0.05em; color: white; margin: 0;
            filter: drop-shadow(0 15px 30px rgba(0,0,0,0.6));
        }
        #${instanceId}-track .aeon-desc { 
            font-size: clamp(9px, 2vw, 16px); font-weight: 700; text-transform: uppercase; 
            color: rgba(255,255,255,0.4); margin-top: 1.5rem; letter-spacing: 0.35em; 
        }
        #${instanceId}-track .aeon-loader { 
            position: absolute; inset: 0; z-index: 10; background: #000; 
            display: flex; align-items: center; justify-content: center; 
            color: rgba(255,255,255,0.2); font-size: 10px; font-weight: 900; letter-spacing: 0.5em;
        }
    </style>

    <div class="aeon-stage">
        <div id="${instanceId}-l" class="aeon-loader">LOADING_ENGINE...</div>
        <video id="${instanceId}-v" class="aeon-video" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-overlay"></div>
    </div>

    <script>
        (function() {
            const CONFIG = { 
                src: "${displayUrl}", 
                data: ${sectionsJSON}, 
                lerp: ${sensitivity}, 
                id: "${instanceId}", 
                startBuffer: ${startOffset}, 
                endBuffer: ${endOffset},
                viewportAnchor: ${viewportAnchor}
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-v');
            const stage = document.getElementById(CONFIG.id + '-g');
            const loader = document.getElementById(CONFIG.id + '-l');

            video.src = CONFIG.src;

            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-node'; 
                node.id = CONFIG.id + '-n-' + i;
                node.style.textAlign = s.alignment;
                node.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0, currentProgress = 0, isSeeking = false, isVisible = false;

            const observer = new IntersectionObserver((e) => { isVisible = e[0].isIntersecting; }, { threshold: 0 });
            observer.observe(track);

            function update() {
                if (!isVisible) return requestAnimationFrame(update);
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;
                const range = 1 - CONFIG.startBuffer - CONFIG.endBuffer;
                const progress = Math.max(0, Math.min(1, (currentProgress - CONFIG.startBuffer) / range));

                if (video.duration && !isSeeking) {
                    const targetTime = (video.duration - 0.05) * progress;
                    if (Math.abs(video.currentTime - targetTime) > 0.03) {
                        isSeeking = true;
                        video.currentTime = targetTime;
                    }
                }

                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-n-' + i);
                    if (!el) return;
                    const dist = Math.abs(progress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.12));
                    el.style.opacity = opacity;
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(progress - s.triggerTime) * 80}px, 0)\`;
                });
                requestAnimationFrame(update);
            }

            function onScroll() {
                const rect = track.getBoundingClientRect();
                const totalHeight = track.offsetHeight - window.innerHeight;
                if (totalHeight > 0) {
                    targetProgress = Math.max(0, Math.min(1, ((window.innerHeight * CONFIG.viewportAnchor) - rect.top) / totalHeight));
                }
            }

            video.onseeked = () => isSeeking = false;
            window.addEventListener('scroll', onScroll, { passive: true });
            video.onloadedmetadata = () => { loader.style.opacity = '0'; video.style.opacity = '1'; onScroll(); update(); };
            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>
`;
}

