const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect, onSampleSelect, isAnalyzing }) => {
  const [showSamples, setShowSamples] = useState(true);

  const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) onFileSelect(file);
  };

  if (isAnalyzing) {
    return (
      <div className="flex flex-col items-center justify-center py-20 md:py-32 gap-8 md:gap-12">
        <div className="relative">
          <div className="w-24 h-24 md:w-40 md:h-40 border-4 border-indigo-500/10 rounded-full animate-spin border-t-indigo-500 shadow-[0_0_40px_rgba(79,70,229,0.2)]" />
          <div className="absolute inset-0 flex items-center justify-center">
            <Sparkles className="text-indigo-400 animate-pulse w-8 h-8 md:w-12 md:h-12" />
          </div>
        </div>
        <div className="text-center space-y-3">
          <p className="text-sm md:text-base font-black uppercase tracking-[0.4em] md:tracking-[0.6em] text-white">Generating Sequence</p>
          <p className="text-[10px] md:text-[12px] font-bold text-white/40 uppercase tracking-widest">Architecting narrative nodes...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-10 md:space-y-14 w-full">
      {/* Control Header */}
      <div className="flex items-center justify-end relative z-30">
         <button 
           type="button"
           onClick={(e) => {
             e.stopPropagation();
             setShowSamples(!showSamples);
           }}
           className="flex items-center gap-3 px-6 md:px-8 py-3 md:py-4 bg-white/[0.03] border border-white/5 rounded-2xl text-[10px] md:text-[11px] font-black uppercase tracking-widest hover:bg-white/5 hover:border-white/10 transition-all text-white/40 hover:text-white active:scale-95 cursor-pointer"
         >
           {showSamples ? <EyeOff size={16} /> : <Eye size={16} />}
           {showSamples ? "Hide Samples" : "Show Samples"}
         </button>
      </div>

      {/* Samples Grid */}
      {showSamples && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8 animate-in fade-in slide-in-from-top-4 duration-500">
          {SAMPLES.map(sample => (
            <button 
              key={sample.id}
              onClick={() => onSampleSelect(sample.url, sample.name, sample.id)}
              className="group relative bg-black/40 border border-white/5 p-8 md:p-10 rounded-3xl hover:border-indigo-500/40 hover:bg-black/60 transition-all text-left overflow-hidden shadow-2xl"
            >
              <div className="relative z-10 flex flex-col gap-6 md:gap-8">
                <div className="w-12 h-12 md:w-16 md:h-16 bg-indigo-500/10 border border-indigo-500/20 rounded-2xl flex items-center justify-center text-indigo-400 group-hover:scale-110 transition-transform shadow-lg">
                  {sample.icon}
                </div>
                <div>
                  <span className="text-[9px] md:text-[10px] font-black tracking-widest text-indigo-400/60 uppercase">{sample.tag}</span>
                  <h3 className="text-base md:text-xl font-black tracking-tight text-white mt-1 uppercase">{sample.name}</h3>
                </div>
              </div>
              <div className="absolute bottom-8 right-8 flex items-center gap-2">
                 <div className="p-3 bg-white/5 rounded-full md:opacity-0 group-hover:opacity-100 transition-opacity">
                   <Play size={18} className="text-white fill-white" />
                 </div>
              </div>
            </button>
          ))}
        </div>
      )}

      {/* Divider */}
      {showSamples && (
        <div className="flex items-center gap-6 md:gap-10 opacity-10 px-4 md:px-8">
          <div className="h-px flex-1 bg-white/20" />
          <span className="text-[10px] md:text-[12px] font-black tracking-[0.5em] uppercase whitespace-nowrap">OR IMPORT SOURCE</span>
          <div className="h-px flex-1 bg-white/20" />
        </div>
      )}

      {/* Upload Zone */}
      <div className="relative w-full group">
        <input 
          type="file" 
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" 
          accept="video/*" 
          onChange={handleFile} 
        />
        <div className="bg-transparent border-2 border-dashed border-white/5 p-16 md:p-32 rounded-[2.5rem] md:rounded-[4rem] group-hover:bg-white/[0.01] group-hover:border-indigo-500/20 transition-all flex flex-col items-center gap-6 md:gap-10 text-center pointer-events-none relative overflow-hidden">
          <div className="w-16 h-16 md:w-24 md:h-24 bg-white/5 rounded-3xl md:rounded-[2rem] flex items-center justify-center text-white/10 group-hover:text-indigo-400/80 group-hover:scale-110 transition-all duration-700 shadow-2xl">
            <Film size={40} className="md:w-12 md:h-12" />
          </div>
          <div className="space-y-3">
            <h2 className="text-2xl md:text-4xl font-black uppercase tracking-tight text-white">Select Asset</h2>
            <p className="text-white/20 text-[10px] md:text-[13px] font-bold uppercase tracking-[0.5em]">Import High-Res Video Sources</p>
          </div>
          <div className="mt-4 px-6 py-2 md:px-10 md:py-3 bg-indigo-500/5 border border-indigo-500/10 rounded-full text-indigo-400/60 text-[10px] md:text-[12px] font-black uppercase tracking-widest">
            MAX ASSET SIZE: 100MB
          </div>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;
